(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("hierocles-golden-verses-e", [{"sp": "HDR", "t": "ΤΑ ΤΩΝ ΠΥΘΑΓΟΡΕΙΩΝ ΧΡΥΣΑ ΕΠΗ", "st": "GV"}, {"sp": "N", "t": "<span class=\"sm-frag\">Ἀθανάτους μὲν πρῶτα θεούς, νόμῳ ὡς διάκεινται,<br>τίμα, καὶ σέβου ὅρκον· ἔπειθ' ἥρωας ἀγαυούς,<br>τούς τε καταχθονίους σέβε δαίμονας, ἔννομα ῥέζων·<br>τούς τε γονεῖς τίμα, τούς τ' ἄγχιστ' ἐκγεγαῶτας·<br>τῶν δ' ἄλλων ἀρετῇ ποιεῦ φίλον ὅστις ἄριστος.<\/span>", "st": "v1"}, {"sp": "N", "t": "<span class=\"sm-frag\">πραέσι δ' εἶκε λόγοις, ἔργοισί τ' ἐπωφελίμοισι,<br>μηδ' ἔχθαιρε φίλον σὸν ἁμαρτάδος εἵνεκα μικρῆς,<br>ὄφρα δύνῃ· δύναμις γὰρ ἀνάγκης ἐγγύθι ναίει.<br>ταῦτα μὲν οὕτως ἴσθι· κρατεῖν δ' εἰθίζεο τῶνδε·<br>γαστρὸς μὲν πρώτιστα καὶ ὕπνου λαγνείης τε<\/span>", "st": "v6"}, {"sp": "N", "t": "<span class=\"sm-frag\">καὶ θυμοῦ. πρήξῃς δ' αἰσχρόν ποτε μήτε μετ' ἄλλου<br>μήτ' ἰδίῃ· πάντων δὲ μάλιστ' αἰσχύνεο σαυτόν.<br>εἶτα δικαιοσύνην ἄσκει ἔργῳ τε λόγῳ τε·<br>μηδ' ἀλογίστως σαυτὸν ἔχειν περὶ μηδὲν ἔθιζε·<br>ἀλλὰ γνῶθι μὲν ὡς θανέειν πέπρωται ἅπασι.<\/span>", "st": "v11"}, {"sp": "N", "t": "<span class=\"sm-frag\">χρήματα δ' ἄλλοτε μὲν κτᾶσθαι φίλει, ἄλλοτ' ὀλέσσαι.<br>ὅσσα τε δαιμονίῃσι τύχαις βροτοὶ ἄλγε' ἔχουσιν,<br>ἣν ἂν μοῖραν ἔχῃς, ταύτην φέρε, μηδ' ἀγανάκτει.<br>ἰᾶσθαι δὲ πρέπει, καθόσον δύνῃ· ὧδε δὲ φράζευ·<br>οὐ πάνυ τοῖς ἀγαθοῖς τούτων πολὺ μοῖρα δίδωσι.<\/span>", "st": "v16"}, {"sp": "N", "t": "<span class=\"sm-frag\">πολλοὶ δ' ἀνθρώποισι λόγοι δειλοί τε καὶ ἐσθλοὶ<br>προσπίπτουσ', ὧν μήτ' ἐκπλήσσεο, μήτ' ἄρ' ἐάσῃς<br>εἴργεσθαι σαυτόν· ψεῦδος δ' ἤνπερ τι λέγηται,<br>πράως εἶκ'. ὃ δέ τοι ἐρέω, ἐπὶ παντὶ τελείσθω·<br>μηδεὶς μήτε λόγῳ σε παρείπῃ, μήτε τι ἔργῳ,<\/span>", "st": "v21"}, {"sp": "N", "t": "<span class=\"sm-frag\">πρῆξαι, μηδ' εἰπεῖν, ὅ τι τοι μὴ βέλτερόν ἐστι.<br>βουλεύου δὲ πρὸ ἔργου, ὅπως μὴ μωρὰ πέληται·<br>δειλοῦ τοι πρήσσειν τε λέγειν τ' ἀνόητα πρὸς ἀνδρός·<br>ἀλλὰ τάδ' ἐκτελέειν, ἅ σε μὴ μετέπειτ' ἀνιήσει.<br>πρῆσσε δὲ μηδὲν τῶν μὴ ἐπίστασαι, ἀλλὰ διδάσκευ<\/span>", "st": "v26"}, {"sp": "N", "t": "<span class=\"sm-frag\">ὅσσα χρεών, καὶ τερπνότατον βίον ὧδε διάξεις.<br>οὐδ' ὑγιείης τῆς περὶ σῶμ' ἀμέλειαν ἔχειν χρή,<br>ἀλλὰ ποτοῦ τε μέτρον καὶ σίτου γυμνασίων τε<br>ποιεῖσθαι· μέτρον δὲ λέγω τόδ', ὃ μή σ' ἀνιήσει.<br>εἰθίζου δὲ δίαιταν ἔχειν καθάρειον, ἄθρυπτον·<\/span>", "st": "v31"}, {"sp": "N", "t": "<span class=\"sm-frag\">καὶ πεφύλαξό γε ταῦτα ποιεῖν, ὁπόσα φθόνον ἴσχει.<br>μὴ δαπανᾶν παρὰ καιρόν, ὁποῖα καλῶν ἀδαήμων·<br>μηδ' ἀνελεύθερος ἴσθι· μέτρον δ' ἐπὶ πᾶσιν ἄριστον.<br>πρῆσσε δὲ ταῦθ' ἅ σε μὴ βλάψει· λόγισαι δὲ πρὸ ἔργου.<br>μηδ' ὕπνον μαλακοῖσιν ἐπ' ὄμμασι προσδέξασθαι,<\/span>", "st": "v36"}, {"sp": "N", "t": "<span class=\"sm-frag\">πρὶν τῶν ἡμερινῶν ἔργων λογίσασθαι ἕκαστον·<br>πῇ παρέβην; τί δ' ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη;<br>ἀρξάμενος δ' ἀπὸ πρώτου ἐπέξιθι· καὶ μετέπειτα<br>δειλὰ μὲν ἐκπρήξας ἐπιπλήσσεο, χρηστὰ δέ, τέρπευ.<br>ταῦτα πόνει, ταῦτ' ἐκμελέτα· τούτων χρὴ ἐρᾶν σε·<\/span>", "st": "v41"}, {"sp": "N", "t": "<span class=\"sm-frag\">ταῦτά σε τῆς θείης ἀρετῆς εἰς ἴχνια θήσει·<br>ναὶ μὰ τὸν ἁμετέρᾳ ψυχᾷ παραδόντα τετρακτύν,<br>παγὰν ἀενάου φύσεως. ἀλλ' ἔρχευ ἐπ' ἔργον<br>θεοῖσιν ἐπευξάμενος τελέσαι. τούτων δὲ κρατήσας<br>γνώσεαι ἀθανάτων τε θεῶν θνητῶν τ' ἀνθρώπων<\/span>", "st": "v46"}, {"sp": "N", "t": "<span class=\"sm-frag\">σύστασιν, ᾗ τε ἕκαστα διέρχεται ᾗ τε κρατεῖται·<br>γνώσῃ δ', ᾗ θέμις ἐστί, φύσιν περὶ παντὸς ὁμοίην,<br>ὥστε σε μήτε ἄελπτ' ἐλπίζειν, μήτε τι λήθειν.<br>γνώσῃ δ' ἀνθρώπους αὐθαίρετα πήματ' ἔχοντας<br>τλήμονας, οἵ τ' ἀγαθῶν πέλας ὄντων οὔτ' ἐσορῶσιν<\/span>", "st": "v51"}, {"sp": "N", "t": "<span class=\"sm-frag\">οὔτε κλύουσι· λύσιν δὲ κακῶν παῦροι συνίσασι.<br>τοίη μοῖρα βροτῶν βλάπτει φρένας· ὡς δὲ κύλινδροι<br>ἄλλοτ' ἐπ' ἄλλα φέρονται, ἀπείρονα πήματ' ἔχοντες.<br>λυγρὴ γὰρ συνοπαδὸς ἔρις βλάπτουσα λέληθε<br>σύμφυτος, ἣν οὐ δεῖ προάγειν, εἴκοντα δὲ φεύγειν.<\/span>", "st": "v56"}, {"sp": "N", "t": "<span class=\"sm-frag\">Ζεῦ πάτερ, ἦ πολλῶν κε κακῶν λύσειας ἅπαντας,<br>εἰ πᾶσιν δείξαις, οἵῳ τῷ δαίμονι χρῶνται.<br>ἀλλὰ σὺ θάρσει, ἐπεὶ θεῖον γένος ἐστὶ βροτοῖσιν,<br>οἷς ἱερὰ προφέρουσα φύσις δείκνυσιν ἕκαστα.<br>ὧν εἴ σοί τι μέτεστι, κρατήσεις ὧν σε κελεύω,<\/span>", "st": "v61"}, {"sp": "N", "t": "<span class=\"sm-frag\">ἐξακέσας, ψυχὴν δὲ πόνων ἀπὸ τῶνδε σαώσεις.<br>ἀλλ' εἴργου βρωτῶν, ὧν εἴπομεν, ἔν τε καθαρμοῖς<br>ἔν τε λύσει ψυχῆς κρίνων, καὶ φράζευ ἕκαστα,<br>ἡνίοχον γνώμην στήσας καθύπερθεν ἀρίστην.<br>ἢν δ' ἀπολείψας σῶμα ἐς αἰθέρ' ἐλεύθερον ἔλθῃς,<\/span>", "st": "v66"}, {"sp": "N", "t": "<span class=\"sm-frag\">ἔσσεαι ἀθάνατος θεός, ἄμβροτος, οὐκ ἔτι θνητός.<\/span>", "st": "v71"}, {"sp": "HDR", "t": "ΙΕΡΟΚΛΕΟΥΣ ΕΙΣ ΤΑ ΧΡΥΣΑ ΕΠΗ ΥΠΟΜΝΗΜΑ"}, {"sp": "SEC", "t": "Προοίμιον", "st": "0"}, {"sp": "N", "t": "Ἡ φιλοσοφία ἐστὶ ζωῆς ἀνθρωπίνης κάθαρσις καὶ τελειότης, κάθαρσις μὲν ἀπὸ τῆς ὑλικῆς ἀλογίας καὶ τοῦ θνητοειδοῦς σώματος, τελειότης δὲ ὡς τῆς οἰκείας εὐζωΐας ἀνάληψις πρὸς τὴν θείαν ὁμοίωσιν ἐπανάγουσα. Ταῦτα δὲ πέφυκεν ἀρετὴ καὶ ἀλήθεια μάλιστα ἀπεργάζεσθαι, ἡ μὲν τὴν ἀμετρίαν τῶν παθῶν ἐξορίζουσα, ἡ δὲ τὸ θεῖον εἶδος τοῖς εὐφυῶς ἔχουσι προσκτωμένη.", "st": "0.0"}, {"sp": "N", "t": "Δεῖ οὖν πρὸς ταύτην τὴν ἐπιστήμην, τὴν μέλλουσαν ἡμᾶς καθαροὺς καὶ τελείους ποιεῖν, κανόνας ἔχειν τινὰς ἐν βραχεῖ διωρισμένους, οἷον ἀφορισμούς τινας τεχνικούς, ὅπως ἂν ἐν τάξει καὶ εὐμεθόδως πρὸς τὸ τῆς εὐζωΐας τέλος ἀφικώμεθα. Τῶν δὲ τοιούτων κανόνων τῶν πρὸς τὴν ὅλην φιλοσοφίαν συντεινόντων τὰ Πυθαγορικὰ ἔπη τὰ οὕτως ἐπικαλούμενα χρυσᾶ ἐν πρώτοις ἂν θείημεν εὐλόγως. Περιέχει γὰρ πάσης φιλοσοφίας πρακτικῆς τε καὶ θεωρητικῆς τὰ καθόλου δόγματα, δι' ὧν ἄν τις ἀλήθειαν καὶ ἀρετὴν κτήσαιτο καὶ ἑαυτὸν καθαρὸν ἀπολάβοι καὶ τὴν πρὸς θεὸν ὁμοίωσιν εὐτυχήσειε, καὶ (ὥς φησιν ὁ Πλάτωνος Τίμαιος, τῶν Πυθαγορείων δογμάτων ὁ ἀκριβὴς διδάσκαλος) ὑγιής τε καὶ ὁλόκληρος γενόμενος εἰς τὸ τῆς προτέρας ἀφίκοιτο εἶδος ἕξεως.", "st": "0.1"}, {"sp": "N", "t": "Καὶ πρῶτά γε τὰ τῆς πρακτικῆς ἀρετῆς παρατίθεται παραγγέλματα. Πρῶτον γὰρ δεῖ τάξαι τὴν ἐν ἡμῖν ἀλογίαν τε καὶ ῥᾳθυμίαν· ἔπειτα οὕτως ἐπιβαλεῖν τῇ τῶν θείων γνώσει. Ὥσπερ γὰρ ὀφθαλμῷ λημῶντι καὶ οὐ κεκαθαρμένῳ τὰ σφόδρα φωτεινὰ ἰδεῖν οὐχ οἷόν τε, οὕτω καὶ ψυχῇ μὴ ἀρετὴν κεκτημένῃ τὸ τῆς ἀληθείας ἐνοπτρίσασθαι κάλλος ἀμήχανον. Μὴ καθαρῷ γὰρ καθαροῦ ἐφάπτεσθαι μὴ οὐ θεμιτὸν ᾖ.", "st": "0.2"}, {"sp": "N", "t": "Ἔστι δὲ ἡ μὲν πρακτικὴ φιλοσοφία ἀρετῆς ποιητική, ἀληθείας δὲ ἡ θεωρητική, ὡς καὶ ἐν αὐτοῖς τοῖς ἔπεσι τὴν μὲν πρακτικὴν φιλοσοφίαν ἀνθρωπίνην ἀρετὴν εὑρίσκομεν λεγομένην, τὴν δὲ θεωρητικὴν θείαν ἀρετὴν ὑμνουμένην, ἐν οἷς συμπεράνας ὁ λόγος τὰ τῆς πολιτικῆς ἀρετῆς παραγγέλματα,", "st": "0.3"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">ταῦτα πόνει (φησί), ταῦτ' ἐκμελέτα· τούτων χρὴ ἐρᾶν σε,<br>ταῦτά σε τῆς θείης ἀρετῆς εἰς ἴχνια θήσει.<\/span><\/span>", "st": "0.4"}, {"sp": "N", "t": "Πρῶτον οὖν ἄνθρωπον δεῖ γενέσθαι, καὶ τότε θεόν. Ἄνθρωπον δὲ ποιοῦσιν ἀγαθὸν αἱ πολιτικαὶ ἀρεταί· θεοποιοῦσι δὲ αἱ πρὸς τὴν θείαν ἀρετὴν ἀνάγουσαι ἐπιστῆμαι. Τὰ δὲ μικρὰ πρὸ τῶν μεγάλων ἐστὶν ἐν τάξει τοῖς ἀνιοῦσι· διὸ καὶ ἐν ταῖς Πυθαγορικαῖς ὑποθήκαις τὰ τῶν ἀρετῶν παραγγέλματα πρῶτα παραδίδωσιν ἐν τοῖς ἔπεσιν ὁ λόγος, παιδαγωγῶν ἡμᾶς ἀπὸ τῆς τῶν περὶ τὸν βίον ἀρίστης χρήσεως πρὸς τὴν θείαν ὁμοίωσιν ἀνιέναι. Καὶ οὗτος μὲν ὁ σκοπὸς τῶν ἐπῶν καὶ ἡ τάξις, χαρακτῆρα φιλόσοφον πρὸ τῶν ἄλλων ἀναγνωσμάτων ἐκθεῖναι τοῖς ἀκροαταῖς.", "st": "0.5"}, {"sp": "N", "t": "Χρυσᾶ δὲ τὴν ἐπωνυμίαν ἔσχε, διὰ τό, ὡς ἐν ἔπεσιν, ἄριστα εἶναι καὶ θεῖα. Οὕτω γὰρ καὶ χρυσοῦν γένος λέγομεν τὸ ἐν τοῖς ἀνθρωπίνοις γένεσιν ἄριστον, ἀπὸ τῆς τῶν ὑλῶν ἀναλογίας τὴν τῶν ἠθῶν διαφορὰν λαμβάνοντες. Ἔστι δὲ καὶ ὁ χρυσὸς ἀκίβδηλόν τι καὶ γῆς οὐκ ἀναπεπλησμένον, ὥσπερ τὰ συγγενῆ καὶ ἐφεξῆς ὄντα τούτῳ, οἷον ἄργυρος καὶ χαλκὸς καὶ σίδηρος· πρὸς ἃ καὶ τὸ ὑπερέχον φύσει κέκτηται ὁ χρυσός, μόνος τῶν ἄλλων ἰὸν οὐ ποιῶν, ἐκείνων ἑκάστου, καθ' ὅσον γῆς μετέχει, κατὰ τοσοῦτον καὶ εἰς ἰὸν μεταβάλλοντος. Τοῦ οὖν γεώδους ἰοῦ κατὰ τὴν ἔνυλον κακίαν λαμβανομένου, τὸ ἅγιον καὶ καθαρὸν γένος καὶ τὸ πάντη καθαρεῦον πονηρίας ἦθος εἰκότως χρυσοῦν ἐλέχθη· οὕτω δὴ καὶ ταῦτα τὰ ἔπη, ὅλα δι' ὅλου ὄντα καλά, χρυσᾶ καὶ θεῖα τὴν ἐπίκλησιν ἀναγέγραπται. Οὐ γάρ ἐστι τὸ μὲν αὐτῶν καλόν, τὸ δὲ οὐ καλόν, ὥσπερ ἔνια τῶν ἄλλων, ἀλλὰ πάντα ὁμοίως τὸ καθαρὸν ἦθος ἐμφαίνει καὶ πρὸς τὴν θείαν ὁμοίωσιν ἀνάγει, καὶ τῆς Πυθαγορικῆς φιλοσοφίας τὸν τελειότατον σκοπὸν ἐκκαλύπτει, ὡς ἐν τῇ καθ' ἕκαστον ἐξηγήσει σαφὲς γενήσεται. Καὶ πρῶτον μὲν ἀπὸ τῶν πρώτων ἀρξώμεθα.", "st": "0.6"}, {"sp": "SEC", "t": "I · 1", "st": "1"}, {"sp": "N", "t": "<span class=\"lemma\">Ἀθανάτους μὲν πρῶτα θεούς, νόμῳ ὡς διάκεινται, τίμα·<\/span>", "st": "1.0"}, {"sp": "N", "t": "Ἐπειδὴ πασῶν τῶν ἀρετῶν ἡγεμών ἐστιν ἡ εὐσέβεια, πρὸς τὴν θείαν αἰτίαν τὴν ἀναφορὰν ἔχουσα, εἰκότως καὶ τῶν ἐν τοῖς ἔπεσι νόμων τὸ περὶ ταύτης ἡγεῖται παράγγελμα· ὡς δεῖ τοὺς ἐγκοσμίους θεούς, κατὰ τὴν ἐνυπάρχουσαν αὐτοῖς τάξιν, τιμᾶν, ἣν ὁ δημιουργικὸς νόμος ἅμα τῇ οὐσίᾳ αὐτῶν συμπροήγαγε, τάξας αὐτῶν τοὺς μὲν ἐπὶ τῆς πρώτης σφαίρας, τοὺς δὲ ἐπὶ τῆς δευτέρας, καὶ ἐπὶ τῆς τρίτης ἄλλους, καὶ οὕτως ἐφεξῆς, μέχρι τῆς πάσης τῶν οὐρανίων κύκλων συμπληρώσεως. Τὸ γάρ, ᾗ ἐτάχθησαν ὑπὸ τοῦ δημιουργοῦ αὐτῶν καὶ πατρός, ταύτῃ αὐτοὺς ἐγνωκέναι τε καὶ τιμᾶν, τῷ θείῳ νόμῳ κατακολουθούντων ἐστὶ καὶ τὴν ὄντως τιμὴν αὐτοῖς ἀποδιδόντων· καὶ τὸ μήτε ὑπεραίρειν τὴν ἀξίαν μήτε ἀπολείπεσθαι ταύτης ἐν ταῖς περὶ αὐτῶν ἐννοίαις, ἀλλὰ τοῦτο αὐτοὺς εἶναι τίθεσθαι, ὃ γεγόνασι, καὶ ταύτην ἔχειν τὴν τάξιν ἣν εἰλήχασιν, ἐπὶ τὸν δημιουργὸν αὐτῶν θεὸν ἀναφέρει τὸ σέβας, ὃν καὶ θεὸν θεῶν κυρίως ἂν εἴποι τις καὶ θεὸν ὕπατον καὶ ἄριστον.", "st": "1.1"}, {"sp": "N", "t": "Τὴν δὲ ὄντως ἀξίαν τοῦ κοσμοποιοῦ καὶ ἀριστοτέχνα θεοῦ μόνως ἂν ἐξεύροιμεν, εἰ καὶ θεῶν αἴτιον αὐτὸν καὶ ἀτρέπτων λογικῶν οὐσιῶν ποιητὴν θησόμεθα. Τούτους γὰρ νῦν ἀθανάτους θεοὺς ὠνόμασεν ὁ λόγος τοὺς ἀεὶ καὶ ὡσαύτως νοοῦντας τὸν δημιουργὸν θεόν, καὶ ἀεὶ πρὸς τὸ ἐκείνου ἀγαθὸν συντεταμένους, καὶ ἀπ' ἐκείνου τὸ εἶναι καὶ τὸ εὖ εἶναι ἀμερίστως καὶ ἀτρέπτως λαμβάνοντας, ὡς τῆς δημιουργικῆς αἰτίας αὐτοὺς ὄντας εἰκόνας ἀπαθεῖς καὶ ἀκακώτους. Πρέπει γὰρ τῷ θεῷ καὶ τοιαύτας ὑποστῆσαι ἑαυτοῦ εἰκόνας, καὶ μὴ πάσας τρεπτὰς καὶ ἐμπαθεῖς τῇ εἰς κακίαν ὑποφορᾷ, οἷαί εἰσιν αἱ ἀνθρώπιναι ψυχαί, τῶν λογικῶν φύσεων τὸ ἔσχατον οὖσαι γένος, ὥσπερ αὖ ἀκρότατον ἦν τὸ νῦν τῶν ἀθανάτων θεῶν λεγόμενον γένος.", "st": "1.2"}, {"sp": "N", "t": "Καὶ μήποτε πρὸς ἀντιδιαστολὴν τῶν ἀνθρωπίνων ψυχῶν ἀθάνατοι θεοὶ οὗτοι ἐκλήθησαν, ὡς μὴ ἀποθνήσκοντες τὴν θείαν εὐζωΐαν, μηδὲ ἐν λήθῃ ποτὲ γιγνόμενοι μήτε τῆς ἑαυτῶν οὐσίας μήτε τῆς τοῦ πατρὸς ἀγαθότητος. Τούτοις δὲ ἡ ἀνθρωπίνη ψυχὴ τοῖς πάθεσιν ὑπόκειται, ποτὲ μὲν νοοῦσα τὸν θεὸν καὶ τὴν ἑαυτῆς ἀξίαν ἀπολαμβάνουσα, ποτὲ δὲ τούτων ἀποπίπτουσα. Διὸ καὶ εἰκότως θεοὶ θνητοὶ λέγοιντο ἂν αἱ ἀνθρώπιναι ψυχαί, ὡς ἀποθνήσκουσαί ποτε τὴν θείαν εὐζωΐαν τῇ ἀπὸ θεοῦ φυγῇ, καὶ ἀναβιωσκόμεναι αὐτὴν πάλιν τῇ πρὸς θεὸν ἐπιστροφῇ, καὶ οὕτω μὲν ζῶσαι τὸν θεῖον βίον, ἐκείνως δὲ ἀποθνήσκουσαι (ὡς οἷόν τε ἀθανάτῳ οὐσίᾳ θανάτου μοίρας μεταλαχεῖν), οὐ τῇ εἰς τὸ μὴ εἶναι ἐκβάσει, ἀλλὰ τῇ τοῦ εὖ εἶναι ἀποπτώσει. Θάνατος γὰρ λογικῆς οὐσίας ἀθεΐα καὶ ἄνοια, οἷς ἕπεται καὶ ἡ περὶ τὸν βίον ἄμετρος τῶν παθῶν ἐπανάστασις. Ἐν γὰρ τῇ ἀγνοίᾳ τῶν κρειττόνων ἀνάγκη δουλεύειν τοῖς χείροσιν· ὧν ἐλευθεριάσαι ἄλλως οὐχ οἷόν τε ἢ τῇ δι' ἀναμνήσεως εἰς νοῦν καὶ θεὸν ἐπιστροφῇ.", "st": "1.3"}, {"sp": "N", "t": "Μεταξὺ δὲ τῶν οὕτω λεγομένων ἀθανάτων θεῶν καὶ τῶν θνητῶν, ὡς εἴπομεν, θεῶν ἀνάγκη γένος τι εἶναι, τιμιώτερον μὲν ἀνθρώπου, καταδεέστερον δὲ θεοῦ, τῇ δι' ἑαυτοῦ μεσότητι τὰ ἄκρα πρὸς ἄλληλα συνάπτον, ὥστε τὸ πᾶν τῆς λογικῆς δημιουργίας αὐτὸ ἑαυτῷ συνδεδέσθαι καλῶς. Τοῦτο δὴ τὸ μέσον οὔτε παντελῆ ἄγνοιαν τοῦ θεοῦ ἴσχει ποτέ, οὔτε παντελῶς ἀκίνητον καὶ ἀεὶ ὡσαύτως διαμένουσαν γνῶσιν, ἀλλ' ἀεὶ μὲν γινώσκει, ἄλλως δὲ καὶ ἄλλως ἐπιβάλλει, καὶ μᾶλλον ἔστιν ὅτε καὶ ἧττον. Τῷ μὲν ἀεὶ γινώσκειν ἀναβέβηκε τοῦ ἀνθρωπίνου γένους, τῷ δὲ μὴ ἀτρέπτως μηδὲ ὡσαύτως ἀεὶ γινώσκειν ὑποβέβηκε τοῦ θείου, φύσει μέσον ὑπάρχον· καὶ οὔτε προκοπῇ βελτιωθὲν ἐξ ἀνθρώπου οὔτε ἀμελείᾳ ὑποβὰν ἐκ θεοῦ εἰς τὴν μέσην τάξιν.", "st": "1.4"}, {"sp": "N", "t": "Πρῶτα γὰρ καὶ δεύτερα καὶ τρίτα ὁ δημιουργὸς θεὸς ὑπέστησε φύσει διαφέροντα ἀλλήλων, καὶ μὴ συγχεόμενα πρὸς ἄλληλα, μηδὲ ἀρετῇ καὶ κακίᾳ τὴν τάξιν διαμείβοντα· ἃ δὴ κατ' οὐσίαν ἑστῶτα ἀϊδίως τῇ συμπροελθούσῃ αὐτοῖς τάξει κατὰ γένος διέστη καὶ ταῖς δημιουργικαῖς αἰτίαις ἀνάλογον ἐτάχθη. Ὡς γὰρ ἐκεῖ πρῶτα καὶ μέσα καὶ ἔσχατα τῆς παντελείου σοφίας ἡ τάξις ἔχει (τοῦτο γάρ ἐστιν αὐτῇ καὶ τὸ εἶναι τῇ σοφίᾳ, τὸ ἐν τάξει καὶ τελειότητι προάγειν τὴν ποίησιν, ὥστε συνιέναι ἀλλήλαις σοφίαν καὶ τάξιν καὶ τελειότητα), οὕτω δὴ καὶ ἐν τῷδε τῷ παντὶ τὰ πρὸς τὴν πρώτην νόησιν τοῦ θεοῦ γενόμενα πρῶτα ἂν εἴη ἐν κόσμῳ, τὰ δὲ πρὸς τὴν μέσην καὶ αὐτὰ μέσα, καὶ τὰ τῷ πέρατι τῶν νοήσεων ἐοικότα τελευταῖα ἂν εἴη ἐν λογικοῖς. Ἔστι γὰρ πᾶς μὲν ὁ λογικὸς διάκοσμος μετὰ τοῦ συμπεφυκότος αὐτῷ ἀφθάρτου σώματος εἰκὼν ὅλου τοῦ δημιουργοῦ θεοῦ. Τῆς δὲ ἐκεῖ ἀκρότητος τὰ ἐν κόσμῳ πρῶτα ἀκήρατος εἰκών, καὶ τῆς ἐκεῖ μεσότητος μέση εἰκὼν τὰ ἐνταῦθα μέσα, καὶ τοῦ πέρατος τῆς ἐκεῖ θεότητος τελευταία εἰκὼν τὰ ἐν λογικοῖς τρίτα καὶ ἔσχατα. Τούτων δὲ τῶν τριῶν γενῶν τὸ μὲν πρῶτον ἀθανάτους θεοὺς ὁ παρὼν λόγος ἐσήμανε, τὸ δὲ μέσον ἥρωας ἀγαυούς, καὶ τὸ ἔσχατον δαίμονας καταχθονίους, ὡς μικρὸν ὕστερον εἰσόμεθα.", "st": "1.5"}, {"sp": "N", "t": "Νῦν δὲ ἐπὶ τὰ πρῶτα πάλιν ἐπανέλθωμεν. Τίς ὁ νόμος καὶ ἡ κατὰ τοῦτον τάξις καὶ ἡ πρὸς τὴν τάξιν ἀποδιδομένη τιμή; Νόμος μὲν ὁ δημιουργικὸς νοῦς καὶ ἡ θεία βούλησις ἡ ἀϊδίως προάγουσα τὰ πάντα καὶ εἰς ἀεὶ διασῴζουσα, τάξις δὲ ἔννομος ἡ ἀπὸ τοῦ πατρὸς τῶν ὅλων καὶ δημιουργοῦ τοῖς ἀθανάτοις θεοῖς συνεισελθοῦσα, καὶ ποιοῦσα ἐν αὐτοῖς τοὺς μὲν πρώτους, τοὺς δὲ δευτέρους. Εἰ γὰρ καί, ὡς ἐν παντὶ τῷ λογικῷ διακόσμῳ, τὴν ἀκρότητα ἔλαχον, ἀλλ' ὁμοίως ἐν ἑαυτοῖς ποικίλλονται καί εἰσιν ἄλλοι ἄλλων θειότεροι. Μήνυμα δὲ τῆς κατ' οὐσίαν αὐτῶν ὑπεροχῆς τε καὶ ὑποβάσεως ἡ τῶν οὐρανίων σφαιρῶν τάξις, κατ' οὐσίαν καὶ δύναμιν τὴν θέσιν διαλαχοῦσα, ὡς ἐν τῇ οὐσίᾳ αὐτῶν κεῖσθαι τὸν νόμον, καὶ τὴν τάξιν ὁμοφυῆ εἶναι αὐτῶν τῇ ἀξίᾳ. Οὐ γάρ, ὡς ἔτυχεν, ὑποστάντες ὕστερον διεκρίθησαν, ἀλλὰ τεταγμένοι προῆλθον εἰς τὸ εἶναι, ὥσπερ ἐν ἑνὶ ζῴῳ τῷ ὅλῳ οὐρανῷ διάφορα ὄντες μέρη καὶ τὴν πρὸς ἄλληλα σύνταξιν ἐν τῇ κατ' εἶδος διαστάσει ἅμα καὶ συναφῇ ἀποσῴζοντες, ὥστε μηδὲ ἐπάλλαξιν τῆς θέσεως αὐτῶν ἐπινοηθῆναί ποτε δύνασθαι εἰ μὴ μετὰ τῆς φθορᾶς τοῦ παντός· ἣν ἀδύνατον ἐπισυμβῆναι, ἔστ' ἂν ᾖ τὸ πρῶτον αὐτῶν αἴτιον ἀμετάβλητον πάντη καὶ ἄτρεπτον, καὶ τὴν οὐσίαν τῇ ἐνεργείᾳ τὴν αὐτὴν κεκτημένον, καὶ τὴν ἀγαθότητα οὐκ ἐπίκτητον ἔχον, ἀλλ' οὐσιωμένην, καθ' αὐτὴν καὶ δι' αὐτὴν τὰ πάντα πρὸς τὸ εὖ εἶναι παράγον.", "st": "1.6"}, {"sp": "N", "t": "Αἰτία γὰρ τῆς τῶν πάντων ποιήσεως αὐτῷ οὐδεμία ἄλλη πρόσεστιν εὔλογος πλὴν τῆς κατ' οὐσίαν ἀγαθότητος. Ἀγαθὸς γὰρ ἦν, φησίν· ἀγαθῷ δὲ οὐδεὶς περὶ οὐδενὸς οὐδέποτε ἐγγίνεται φθόνος. Αἱ δὲ παρὰ τὴν ἀγαθότητα λεγόμεναι αἰτίαι τῆς δημιουργίας τοῦδε τοῦ παντὸς ἀνθρωπίναις μᾶλλον περιστάσεσιν ἢ τῷ θεῷ πρέπουσιν. Ἀγαθὸς δὴ ὢν τὴν οὐσίαν ὁ θεὸς τὰ μάλιστα ὡμοιωμένα αὑτῷ πρῶτα φύσει προήγαγε, καὶ δεύτερα τὰ τὴν μέσην ὁμοιότητα πρὸς αὐτὸν κεκτημένα, τρίτα δὲ καὶ ἔσχατα πάντων τῶν ἐοικότων αὑτῷ τὰ πρὸς τὴν θείαν ὁμοίωσιν μάλιστα ὑφειμένα. Τῇ δὲ οὐσίᾳ τῶν γινομένων σύνδρομος ἦν ἡ τάξις, ὥστε τὸ φύσει κρεῖττον προτεταγμένον εἶναι τοῦ καταδεεστέρου ἔν τε τοῖς ὅλοις γένεσι καὶ ἐν τοῖς καθ' ἕκαστον γένος τὴν κατ' εἶδος ὑπόβασιν κεκτημένοις. Οὐ γὰρ τύχαις ἐκληροῦτο τὴν τάξιν τὰ πάντα, οὐδὲ προαιρέσεων μεταβολαῖς, ἀλλὰ νόμοις δημιουργικοῖς διάφορα προήγετο, καὶ τὴν τάξιν ἀνάλογον ταῖς τῶν φύσεων ἀξίαις ἐλάγχανε. Διὸ τὸ «νόμῳ ὡς διάκεινται, τίμα» οὐ μόνον ἐπὶ τῶν ἀθανάτων θεῶν, ἀλλὰ καὶ ἐπὶ τῶν ἀγαυῶν ἡρώων καὶ τῶν ἀνθρωπίνων ψυχῶν κοινῶς ἀκουστέον. Ἔστι γὰρ πλῆθος εἰδῶν ἐν ἑκάστῳ γένει καθ' ὑπεροχὴν καὶ ὑπόβασιν τεταγμένον.", "st": "1.7"}, {"sp": "N", "t": "Τοιαύτη μὲν ἡ φύσις τῶν λογικῶν οὐσιῶν καὶ ἡ τάξις. Τίς δὲ ὁ νόμος καὶ ἡ τούτῳ ἑπομένη τιμή; Πάλιν λέγομεν ὅτι νόμος μὲν ἡ ἄτρεπτος τοῦ θεοῦ δημιουργικὴ ἐνέργεια, ἡ γεννῶσα τὰ θεῖα γένη καὶ τάττουσα ἀϊδίως καὶ ἀμεταβλήτως· ἡ δὲ σύμφωνος τῷ νόμῳ τιμὴ ἡ τῆς οὐσίας ἐστὶ τῶν τιμωμένων γνῶσις καὶ ἡ πρὸς αὐτὰ κατὰ δύναμιν ἐξομοίωσις. Ὃ γὰρ ἄγαταί τις, καὶ μιμεῖται, ὅσον αὐτῷ οἷόν τε· καὶ τιμὴν ποιεῖται τοῦ ἀνενδεοῦς τὴν τῶν ὑπ' ἐκείνου προτεινομένων ἀγαθῶν ὑποδοχήν. Οὐ γὰρ τιμήσεις τὸν θεὸν ἄριστα διδούς τι αὐτῷ, ἀλλ' ἄξιος τοῦ λαβεῖν τὰ παρ' ἐκείνου γινόμενος. Ὡς γάρ φασιν οἱ Πυθαγόρειοι, «τιμήσεις τὸν θεὸν ἄριστα, ἐὰν τῷ θεῷ τὴν διάνοιαν ὁμοιώσῃς»· καί, «ὅστις τιμᾷ τὸν θεὸν ὡς προσδεόμενον, οὗτος λέληθεν οἰόμενος ἑαυτὸν τοῦ θεοῦ εἶναι κρείττονα»· καί, «ἡ τῶν προσφερομένων πολυτέλεια τιμὴ εἰς θεὸν οὐ γίνεται, εἰ μὴ μετὰ τοῦ ἐνθέου φρονήματος προσάγοιτο. Δῶρα γὰρ καὶ θυηπολίαι ἀφρόνων, πυρὸς τροφή· καὶ ἀναθήματα, ἱεροσύλοις χορηγία. Τὸ δὲ ἔνθεον φρόνημα, διαρκῶς ἡδρασμένον, συνάπτει θεῷ». Χωρεῖν γὰρ ἀνάγκη τὸ ὅμοιον πρὸς τὸ ὅμοιον· ὅθεν καὶ μόνος ἱερεὺς ὁ σοφὸς λέγεται, μόνος θεοφιλής, μόνος εἰδὼς εὔξασθαι. Μόνος γὰρ οἶδε τιμᾶν ὁ τὴν ἀξίαν μὴ συγχέων τῶν τιμωμένων, καὶ ὁ προηγουμένως ἱερεῖον ἑαυτὸν προσάγων, καὶ ἄγαλμα θεῖον τεκταίνων τὴν ἑαυτοῦ ψυχήν, καὶ ναὸν εἰς ὑποδοχὴν τοῦ θείου φωτὸς τὸν ἑαυτοῦ κατασκευάζων νοῦν. Τί γὰρ τοιοῦτον προσάξεις ἀπὸ τῶν ἐν μέσῳ κειμένων ὑλῶν, ὃ τῷ θεῷ προσφυὲς ἄγαλμα ἐργάσῃ ἢ δῶρον ἑνοῦσθαι αὐτῷ δυνάμενον; Ἃ δὴ ἐπὶ τῆς λογικῆς οὐσίας καθαρθείσης συμβαίνειν ἀνάγκη. Ὡς γὰρ οἱ αὐτοὶ ἄνδρες φασί, ψυχῆς καθαρᾶς τόπον οἰκειότερον ἐπὶ γῆς θεὸς οὐκ ἔχει· οἷς καὶ ὁ Πύθιος συμφέρεται, λέγων·", "st": "1.8"}, {"sp": "N", "t": "εὐσεβέσιν δὲ βροτοῖς γάνυμαι τόσον, ὅσσον Ὀλύμπῳ.", "st": "1.9"}, {"sp": "N", "t": "Εὐσεβὴς δὲ ὁ τὴν θείαν ἐπιστήμην ἔχων καὶ τὴν ἑαυτοῦ τελείωσιν ὡς τιμὴν ἀρίστην προσάγων τοῖς τῶν ἀγαθῶν αἰτίοις, τῇ σπουδῇ τῆς κτήσεως πρὸς τοὺς χορηγεῖν πεφυκότας ἐπιστρεφόμενος, καὶ τῷ λαμβάνειν τὰ ἀγαθὰ δύνασθαι τιμῶν τοὺς ἀεὶ διδόντας αὐτά. Ὁ δὲ ἄλλως τιμᾶν τὸ θεῖον προαιρούμενος, καὶ μὴ δι' ἑαυτοῦ, παρανάλωμα τῆς ἔξωθεν εὐπορίας ποιεῖται τὴν τιμήν, οὐκ οἰκείαν ἀρετὴν προσφέρων, ἀλλὰ ἀπὸ τῶν ἐκτὸς αὐτῷ ἀφοσιούμενος. Ταῦτα δὲ οὐδὲ σπουδαίῳ ἀνδρὶ λαμβάνειν ἡδὺ μὴ μετὰ τῆς ἀρίστης διαθέσεως διδόμενα. Τοιοῦτον δὲ καὶ τὸ τοῦ Πυθίου πάλιν ἀπόφθεγμα. Πρὸς γὰρ τὸν ἑκατόμβας θύσαντα μὴ μετ' εὐσεβοῦς γνώμης, καὶ πυνθανόμενον πῶς εἴη προσδεδεγμένος τὰ παρ' αὐτοῦ δῶρα, ἀπεκρίνατο·", "st": "1.10"}, {"sp": "N", "t": "ἀλλά μοι εὔαδε χόνδρος ἀγακλυτοῦ Ἑρμιονῆος,", "st": "1.11"}, {"sp": "N", "t": "τὸ εὐτελέστατον προκρίνων τῆς τοσαύτης πολυτελείας, ὅτι δὴ θεοσεβεῖ γνώμῃ κεκόσμητο. Μετὰ ταύτης γὰρ πάντα θεοφιλῆ· καὶ ἄνευ ταύτης οὐδὲν θεῷ φίλον ἄν ποτε γένοιτο.", "st": "1.12"}, {"sp": "N", "t": "Καὶ τὰ μὲν περὶ θεοσεβείας καὶ ὁσιότητος ἱκανῶς ἐν τῷ παρόντι λέλεκται. Ἐπειδὴ δὲ τὸν νόμον τῆς τοῦ παντὸς διατάξεως ἄτρεπτος φρουρὰ διατηρεῖ, καὶ τῆς φρουρᾶς ταύτης φύλακα τοῖς παλαιοῖς ἔθος ἦν δι' ἀπορρήτων ὅρκον ὀνομάζειν, εἰκότως ἐφεξῆς τοῖς προειρημένοις ὡς ἀκόλουθον ἐπάγει δόγμα τὸ περὶ τοῦ ὅρκου παράγγελμα.", "st": "1.13"}, {"sp": "SEC", "t": "II · 2", "st": "2"}, {"sp": "N", "t": "<span class=\"lemma\">καὶ σέβου ὅρκον.<\/span>", "st": "2.0"}, {"sp": "N", "t": "Νόμον ἐν τοῖς προτέροις ἀπεφηνάμεθα τὴν ἀεὶ ὡσαύτως ἔχουσαν ἐνέργειαν τοῦ θεοῦ, τὴν ἀϊδίως καὶ ἀτρέπτως τὰ πάντα πρὸς τὸ εἶναι παράγουσαν. Ὅρκον δὲ νῦν ἑπομένως ἂν τῷ νόμῳ λέγοιμεν τὴν ἐν ταὐτότητι τὰ πάντα διατηροῦσαν αἰτίαν καὶ οὕτως αὐτὰ βεβαιουμένην, ὡς ἐν ὅρκου πίστει κρατούμενα καὶ διασώζοντα τοῦ νόμου τὴν τάξιν, ὥστε ἀποτέλεσμα τοῦ δημιουργικοῦ νόμου εἶναι τὸ ἀπαράβατον τῆς ἐν τοῖς δημιουργηθεῖσιν εὐταξίας. Τὸ γὰρ διαμένειν τὰ πάντα, νόμῳ ὡς διάκειται, προηγούμενον ἔργον ἂν εἴη τοῦ ὅρκου τοῦ θείου, ὃς ἐν μὲν τοῖς ἀεὶ νοοῦσι τὸν θεὸν μάλιστά τε καὶ ἀεὶ διασώζεται· ἐν δὲ τοῖς ποτὲ μὲν νοοῦσι ποτὲ δὲ ἀφισταμένοις τῆς θείας γνώσεως καὶ ὁ ὅρκος ὁμοίως παραβαίνεται μὲν ὑπὸ τῶν ἀφισταμένων, αὖθις δὲ τηρεῖται ὑπὸ τῶν πρὸς τὴν θείαν ἐπιστροφὴν ἀναγομένων. Ἡ γὰρ τήρησις τῶν θείων νόμων ὅρκος νῦν λέγεται, ᾧ δέδεται καὶ ἀνήρτηται πάντα πρὸς τὸν δημιουργὸν θεὸν τὰ γιγνώσκειν αὐτὸν πεφυκότα· ὧν τὰ μὲν ἀεὶ ἐχόμενα αὐτοῦ ἀεὶ σέβει τὸν ὅρκον, τὰ δὲ ἀφιστάμενά ποτε, τότε καὶ περὶ τὸν ὅρκον ἀσεβεῖ, οὐ μόνον τοῦ θείου νόμου τὴν τάξιν, ἀλλὰ καὶ τοῦ θείου ὅρκου τὴν πίστιν παραβαίνοντα. Τοιοῦτος μὲν οὖν ὁ τοῖς λογικοῖς γένεσιν ἐνουσιωμένος ὅρκος, ἔχεσθαι τοῦ πατρὸς αὐτῶν καὶ ποιητοῦ, καὶ μὴ παραβαίνειν μηδαμῆ τοὺς ὑπ' ἐκείνου διορισθέντας νόμους ἀναγκάζων.", "st": "2.1"}, {"sp": "N", "t": "Ὁ δὲ ἐν ταῖς κατὰ τὸν βίον ἀναστροφαῖς ὅρκος ἴχνος ἐστὶν ἐκείνου, πρὸς ἀλήθειαν ἀπευθύνων τοὺς δεόντως αὐτῷ χρωμένους. Τὸ γὰρ ἀμφίβολον τῆς ἀνθρωπίνης προαιρέσεως εἰς βεβαιότητα μεταρρυθμίζει, καὶ μένειν ἐπὶ τῆς ταὐτότητος ἀναγκάζει ἔν τε λόγοις καὶ ἔργοις, τοῦτο μὲν τῶν γεγενημένων τὸ σαφὲς ἐκφαίνων, τοῦτο δὲ τῶν μελλόντων γενήσεσθαι τὸ βέβαιον ἀπαιτῶν.", "st": "2.2"}, {"sp": "N", "t": "Διὰ ταῦτα δὴ καὶ μάλιστα σέβεσθαι προσήκει τὸν ὅρκον, τὸν μὲν κατ' οὐσίαν προϋπάρχοντα, διὰ τὴν τῆς ἀϊδιότητος φρουράν, τὸν δὲ ἀνθρώπινον καὶ τοῖς ἐν βίῳ πράγμασιν ἐπίκουρον ὡς εἰκόνα ἐκείνου, καὶ μετ' ἐκεῖνον βεβαιότητος καὶ ἀληθείας γενόμενον ἡμῖν πρύτανιν, καὶ τῶν καλλίστων ἠθῶν πληροῦντα τοὺς σέβειν αὐτὸν μεμαθηκότας. Σέβας δὲ ὅρκου μόνον ἂν εἴη ἡ τήρησις τῶν ὀμωμοσμένων, ὅσον ἐφ' ἡμῖν, ἀπαραπόδιστος, ἡ πρὸς τὸ μόνιμον καὶ ἀληθευτικὸν τῆς θείας ἕξεως τῇ ἑκουσίῳ ἀνάγκῃ τοὺς σέβοντας τὸν ὅρκον συναρμόζουσα.", "st": "2.3"}, {"sp": "N", "t": "Καὶ ἡ μὲν πρώτη καὶ ἀπόρρητος εὐορκία, διὰ τῆς εἰς θεὸν ἐπιστροφῆς, αὖθις ἀναλαμβάνεσθαι πέφυκε τοῖς ταῖς καθαρτικαῖς ἀρεταῖς τὴν παρέκβασιν ἰωμένοις τοῦ θείου ὅρκου· ἡ δὲ βιωτικὴ εὐορκία ταῖς πολιτικαῖς ἀρεταῖς διασώζεται. Μόνοι γὰρ οἱ τὰς ἀρετὰς ταύτας κεκτημένοι καὶ εὐορκεῖν ἐν τοῖς κατὰ τὸν βίον δύνανται· ἡ δὲ κακία μήτηρ ἐπιορκίας τῷ ἀβεβαίῳ τοῦ ἤθους τὸν ὅρκον καταπατοῦσα. Πῶς γὰρ ἂν ὁ φιλοχρήματος ἢ πρὸς ἀργυρίου λῆψιν ἢ ἀπόδοσιν εὔορκός ποτε γένοιτο; πῶς δὲ ὁ ἀκόλαστος ἢ ὁ δειλὸς ἐμμένῃ τοῖς ὅρκοις; καὶ οὐχ ὅπου δ' ἂν ἑκάτερος αὐτῶν οἰηθῇ πλέον τι ἕξειν, ἐν οἷς ἐστιν ἥττων, ἐνταῦθα τὸ σέβας τῶν ὅρκων ἀποδύσεται, θνητὰ καὶ ἐπίκηρα τῶν θείων ἀγαθῶν ἀνταλλαττόμενος; Οἷς δὲ καλῶς τὸ τῶν ἀρετῶν ἐνίδρυται κτῆμα, τούτοις εὖ καὶ τὸ σέβας τῶν ὅρκων διασώζεσθαι πέφυκε.", "st": "2.4"}, {"sp": "N", "t": "Μελέτη δὲ ἀρίστη τοῦ τηρεῖν τὸ περὶ αὐτὸν σέβας τὸ μὴ πυκνῶς μηδὲ ὡς ἔτυχε χρῆσθαι τῷ ὅρκῳ, μηδὲ ἐπὶ τοῖς παρατυχοῦσι, μηδὲ εἰς ἀναπλήρωσιν λόγου, μηδὲ εἰς πίστωσιν διηγήματος, ἀλλ' ὡς οἷόν τε τηρεῖν αὐτοῦ τὴν χρείαν ἐν τοῖς ἀναγκαίοις τε ἅμα καὶ τιμίοις, καὶ τότε, ὅτε μηδεμία ἄλλη τῶν τοιούτων σωτηρία παραφαίνεται, εἰ μὴ διὰ μόνης τῆς ἐκ τοῦ ὅρκου ἀληθείας. Ἔσται δὲ ταῦτα πιστὰ τοῖς ἀκούουσιν, εἰ τὸν τρόπον σύμφωνον τῷ ὅρκῳ παρεχοίμεθα, καὶ μηδεμίαν ὑποψίαν καταλείποιμεν, ὡς ἄρα ποτὲ τῶν ἀνθρωπίνων πραγμάτων φανείη τι μεῖζον ἡμῖν ἀληθείας, εἴτε ἀνωμότοις, εἴτε καὶ ὀμνύουσι.", "st": "2.5"}, {"sp": "N", "t": "Τὸ δὴ σέβου ὅρκον οὐ μόνον εὐορκεῖν, ἀλλὰ καὶ ἀπέχεσθαι ὅρκου παρεγγυᾷ. Οὕτω γὰρ ἂν τηρήσαιμεν τὸ εὐορκεῖν, εἰ μὴ καταχρησοίμεθα τοῖς ὅρκοις. Καὶ γὰρ ἐν τῇ συνεχείᾳ τοῦ ὀμνύειν ῥᾳδίως ἂν μεταπέσοι τις εἰς ἐπιορκίαν· φειδοῖ δὲ τήρησις ἕπεται. Ἢ γὰρ οὐκ ὀμεῖται, ἢ ὅταν ὄμνυσιν εὐορκήσει· καὶ οὔτε ἂν ὑπὸ συνηθείας προδράμοι ἡ γλῶσσα, οὔτε ὑπὸ παθῶν ἀκρατείας ἡ διάνοια σφαλείη. Τὴν μὲν γὰρ ὁ τρόπος ὀρθώσει χρηστὸς ὤν, τὴν δὲ τὸ ἔθος τῆς ἀποχῆς τοῦ ὀμνύναι.", "st": "2.6"}, {"sp": "N", "t": "Πρέπει δὲ τῇ προειρημένῃ τιμῇ τῶν θεῶν ἡ εὐορκία, ὡς ἀεὶ σύμφυτος καὶ ὀπαδὸς τῆς εὐσεβείας· καὶ γὰρ καὶ ὁ ὅρκος τοῦ θείου νόμου ἦν φύλαξ κατὰ τὴν τοῦ παντὸς διακόσμησιν. Τίμα οὖν τὸν νόμον ἑπόμενος αὐτοῦ τῇ διατάξει, καὶ σέβου τὸν ὅρκον τῷ μὴ προχείρως αὐτῷ καταχρῆσθαι, ἵν' ἐθισθῇς εὐορκεῖν ἐκ τοῦ μὴ εἰθίσθαι ὀμνύναι. Μέρος γὰρ οὐ μικρόν ἐστι τῆς εὐσεβείας ἡ εὐορκία.", "st": "2.7"}, {"sp": "N", "t": "Καὶ περὶ μὲν τοῦ πρώτου γένους τῶν κρειττόνων καὶ τοῦ θείου νόμου τοῦ τῆς τάξεως ἡγουμένου καὶ τοῦ συνεπομένου ὅρκου τῷ νόμῳ τοσαῦτα· ὅτι δὲ καὶ τὸ μετὰ θεοὺς γένος, ὃ ἔφαμεν ἀγγελικὸν εἶναι, δευτέρως χρὴ τιμᾶν ἐπάγει.", "st": "2.8"}, {"sp": "SEC", "t": "III · 2", "st": "3"}, {"sp": "N", "t": "<span class=\"lemma\">ἔπειθ' ἥρωας ἀγαυούς.<\/span>", "st": "3.0"}, {"sp": "N", "t": "Οὗτοι ἦσαν τὸ μέσον γένος τῶν λογικῶν οὐσιῶν, οἱ μετὰ θεοὺς τοὺς ἀθανάτους τὴν ἐφεξῆς πληροῦντες χώραν προηγοῦνται τῆς ἀνθρωπίνης φύσεως, καὶ συνάπτουσι δι' ἑαυτῶν τὰ ἔσχατα τοῖς πρώτοις. Τούτοις οὖν, ὡς δευτέροις, τὴν δευτέραν τιμὴν ἀποδιδόναι χρή, προσυπακούοντας καὶ ἐπ' αὐτῶν τὸ τίμα νόμῳ ὡς διάκεινται. Ἡ γὰρ ὅλη δύναμις τῆς τιμῆς ἐν τῇ γνώσει τῆς οὐσίας τῶν τιμωμένων κεῖται, ἀφ' ἧς καὶ τὸ τῶν δεόντων εἰπεῖν τι ἢ πρᾶξαι πρὸς τὰ τιμώμενα εὖ καὶ καλῶς ἐξευρίσκεται. Πῶς γὰρ ἂν διαλεχθείη τις οἷς ἀγνοεῖ; Πῶς δὲ δῶρον προσάξει τούτοις, ὧν τὴν ἀξίαν οὐκ οἶδεν; Ἡ πρώτη οὖν καὶ ὄντως τιμή, καὶ ἐπὶ τῶν ἀγαυῶν ἡρώων, ἐστὶν ἡ τῆς οὐσίας αὐτῶν καὶ τῆς τάξεως γνῶσις καὶ ἡ τῆς παρεπομένης ἐνεργείας καὶ εἰς τόδε τὸ πᾶν διατεινούσης συντελείας εἴδησις.", "st": "3.1"}, {"sp": "N", "t": "Συμμέτρως δὲ καὶ ταῖς οὐσίαις ἐπὶ πάντων ποιεῖσθαι δεῖ τὴν τιμήν· τοῦτο δὲ ἀπὸ τῆς περὶ αὐτὰς ἐπιστήμης παραγίνεται. Ὅταν γάρ, ὡς ἕκαστα φύσεως ἔχει καὶ τάξεως, διαγνῶμεν, τότε καὶ ἑπομένως τῷ νόμῳ τὴν τιμὴν αὐτοῖς ἀποδώσομεν. Τιμήσομεν δὲ οὐδὲν τῶν χειρόνων τῆς ἀνθρωπίνης οὐσίας, ἀλλὰ μόνα προηγουμένως μὲν τὰ φύσει κρείττονα, καὶ τὰ ἴσα δέ, ἀρετῆς ὑπεροχῇ κοσμηθέντα.", "st": "3.2"}, {"sp": "N", "t": "Ἔστι δὲ τῶν φύσει κρειττόνων πρώτιστος καὶ ἄριστος ὁ δημιουργὸς θεός, ἀσυγκρίτως τῶν πάντων προτιμώμενος. Τῶν δὲ ἐν κόσμῳ πρῶτοι οἱ ἀπ' αὐτοῦ καὶ μετ' αὐτόν, ἀτρέπτως αὐτὸν νοοῦντες καὶ ἀπαθῶς ἐνεικονιζόμενοι τὴν ἀπὸ τῆς δημιουργικῆς αἰτίας εἰς αὐτοὺς κατιοῦσαν τῶν ἀγαθῶν μετουσίαν· οὓς ὁ παρὼν λόγος ἀθανάτους θεοὺς προσεῖπεν, ὅτι οὐκ ἀποθνήσκουσιν οὐδὲ ἀποβάλλουσι τὴν πρὸς τὸν θεὸν ὁμοίωσιν, ἀλλ' ἀεὶ καὶ ὡσαύτως ἐν αὐτῇ διατελοῦσι.", "st": "3.3"}, {"sp": "N", "t": "Μέσοι δὲ οὐσίᾳ καὶ τιμῇ οἱ νῦν λεγόμενοι ἥρωες ἀγαυοί, ἀεὶ μὲν νοοῦντες τὸν δημιουργὸν καὶ τῇ παρ' αὐτοῦ εὐζωίᾳ καταλαμπόμενοι, οὐχ ὡσαύτως δὲ οὐδὲ ἀτρέπτως. Ἐν γὰρ τῷ μέσως ἡνῶσθαι πρὸς τὸν θεὸν καὶ τροπὴν ἀκάκυντον ἐπιδεχόμενοι ἄλλοτε ἄλλαις ἐπιβολαῖς περὶ αὐτὸν χορεύουσι καὶ τὴν ἀμετάβλητον καὶ ἡνωμένην θεωρίαν τῶν πρώτων τῇ ἑαυτῶν πεπληθυσμένῃ γνώσει διαιροῦσί τε ἅμα καὶ συνάγουσι, τὰ πέρατα τῆς ἐκείνων ἐποπτείας ἀρχὰς τῆς ἑαυτῶν ποιούμενοι μυήσεως.", "st": "3.4"}, {"sp": "N", "t": "Οἳ δὴ καὶ εἰκότως ἀγαυοὶ ἥρωες λέγονται, ἀγαυοὶ μὲν ὡς ἀγαθοὶ ὄντες καὶ φωτεινοὶ ἀεὶ καὶ μήτ' ἐν κακίᾳ μήτ' ἐν λήθῃ ποτὲ γινόμενοι, ἥρωες δὲ ὡς ἔρωές τινες ὄντες καὶ ἔρωτες, οἷον ἐρωτικοὶ καὶ διαλεκτικοὶ ἐρασταὶ τοῦ θεοῦ, αἴροντες ἡμᾶς καὶ κουφίζοντες πρὸς τὴν θείαν πολιτείαν ἀπὸ τῆς ἐν γῇ διατριβῆς. Τοὺς δὲ αὐτοὺς καὶ δαίμονας ἀγαθοὺς καλεῖν ἔθος, ὡς ὄντας δαήμονας καὶ ἐπιστήμονας τῶν θείων νόμων, ἔστι δὲ ὅτε καὶ ἀγγέλους ὡς ἐκφαίνοντας καὶ διαγγέλλοντας ἡμῖν τοὺς πρὸς εὐζωΐαν κανόνας.", "st": "3.5"}, {"sp": "N", "t": "Πολλάκις δὲ καὶ ταῖς τρισὶν ἐπινοίαις χρώμενοι τὸ πλάτος τοῦ μέσου γένους εἰς τρία τέμνομεν, καὶ τὸ μὲν προσεχὲς τοῖς οὐρανίοις καλοῦμεν ἀγγέλους, τὸ δὲ τοῖς ἐπιγείοις συναπτόμενον ἥρωας, τὸ δὲ ἐξ ἴσου τῶν ἄκρων ἀμφοτέρων ἀπέχον δαίμονας, ὥσπερ πολλαχοῦ ποιεῖ Πλάτων. Ἔνιοι δὲ ὅλον τὸ μέσον γένος ἑνὶ τῶν τριῶν προσαγορεύουσιν ὀνόματι, ἀγγέλους πάντας λέγοντες ἢ δαίμονας ἢ ἥρωας, δι' ἃς εἴπομεν αἰτίας, ὥσπερ καὶ νῦν τὸ μέσον γένος πᾶν ἥρωας ἀγαυοὺς εἶπεν, οὕτως ἔχοντας πρὸς τὸ πρῶτον γένος, ὡς αὐγὴ πρὸς πῦρ καὶ ὡς παῖς πρὸς πατέρα.", "st": "3.6"}, {"sp": "N", "t": "Ὅθεν καὶ θεῶν παῖδες οἱ ἥρωες εἰκότως ἐπευφημοῦνται, οὐκ ἐκ θνητῆς συνουσίας αὐτοὶ γεννώμενοι, ἀλλ' ἐκ τῆς μονοειδοῦς αὐτῶν αἰτίας προϊόντες, οἷον φῶς τῇ οὐσίᾳ τοῦ φωτεινοῦ σώματος σύνδρομον· φῶς δὲ ὕπαιθρον καὶ καθαρόν, μεθ' ὃ ἐπινοεῖται τὸ ἐν σκιᾷ φῶς καὶ τὸ ὑποσυμμιγὲς σκότῳ γινόμενον· πρὸς ὃ τὴν ἀναλογίαν ἔχει τὸ τρίτον καὶ ἀνθρώπινον γένος τῷ εἰς κακίαν ποτὲ καὶ λήθην ἐπιρρεπὲς εἶναι, οἷς καὶ τοῦ ἀεὶ νοεῖν τὸν θεὸν ἀφίσταται ἄνθρωπος, τῶν μὲν ἀεὶ νοούντων ἀπολειπόμενος τῷ ποτὲ μὴ νοεῖν, τῶν δὲ ἀλόγων ἀναβεβηκὼς τῷ ποτὲ νοεῖν καὶ πρὸς τὴν θείαν ἐπιστήμην ἀνακαλεῖσθαι, ὅτε καὶ τῷ θείῳ συντάττεται χορῷ τὸν ὑλικὸν φθόνον ἀποφυγὼν καὶ τὴν θνητὴν προσπάθειαν ἀποσεισάμενος. Τότε οὖν καὶ τιμῆς ἄξιος παρ' ἡμῶν ὁ τῆς θείας ἀποδοχῆς ἠξιωμένος, ὡς τὸ τῆς φύσεως ἴσον τῇ τοῦ κρείττονος μετουσίᾳ κοσμήσας. Προσήκει γὰρ τιμᾶν τῷ ἐραστῇ τοῦ θεοῦ καὶ τὰ ὁπωσοῦν ὡμοιωμένα αὐτῷ, εἴτε ἐξ ἀϊδίου τὴν ὁμοίωσιν εἴη κεκτημένα, εἴτε ἀπό τινος χρόνου τυγχάνοι ταύτην ἀσκήσαντα· οἷοί εἰσιν οἱ ἀρετῇ διενεγκόντες ἄνθρωποι, περὶ ὧν ἑξῆς ὁ παρὼν λόγος νομοθετεῖ.", "st": "3.7"}, {"sp": "SEC", "t": "IV · 3", "st": "4"}, {"sp": "N", "t": "<span class=\"lemma\">Τούς τε καταχθονίους σέβε δαίμονας ἔννομα ῥέζων.<\/span>", "st": "4.0"}, {"sp": "N", "t": "Τὰς ἀνθρωπίνας ψυχὰς ἀληθείᾳ καὶ ἀρετῇ κοσμηθείσας δαίμονας καλεῖ, ὡς δαήμονας καὶ ἐπιστήμονας. Εἶτα χωρίζων αὐτὰς τῶν φύσει δαιμόνων, οἱ τὸ μέσον γένος πληροῦσι, καταχθονίους προσεῖπεν, ὡς δυναμένας ἐπὶ γῆς πολιτεύεσθαι καὶ γήινα σώματα ἐπεισιέναι καὶ κατὰ γῆς οἰκεῖν, ἵνα τῷ μὲν δαίμονας εἰπεῖν χωρίσῃ τῶν φαύλων καὶ ἀνεπιστημόνων ἀνθρώπων, ὡς ἀδαημόνων τινῶν καὶ οὐ δαιμόνων, τῷ δὲ καταχθονίους προσθεῖναι διαστήσῃ τῶν ἀεὶ δαημόνων καὶ ἐπιστημόνων ἀεί, καὶ ἐπὶ γῆς πολιτεύεσθαι μὴ πεφυκότων μηδὲ γηΐνοις συζῇν σώμασιν. Ἡ γὰρ τοῦ καταχθονίου δαίμονος πρόσρησις οὐδενὶ ἄλλῳ προσήκει, ἢ τῷ φύσει μὲν ὄντι ἀνθρώπῳ, σχέσει δὲ γενομένῳ δαίμονι, ἐπειδὴ τὸ τρίτον γένος χθόνιον ἰδίως λέγεται, ὡς ἔσχατον ἐν λογικαῖς οὐσίαις καὶ χθονίας ζωῆς ἐπιστρεφόμενον. Τὸ γὰρ πρῶτον οὐράνιον ἦν καὶ τὸ μέσον αἰθέριον.", "st": "4.1"}, {"sp": "N", "t": "Πάντων οὖν ἀνθρώπων ὄντων κατὰ τοῦτο καταχθονίων λογικῶν, οὐ πάντων δὲ δαιμόνων, οὐδὲ σοφῶν, εἰκότως ἐπισυνάψας εἶπε καταχθονίους δαίμονας τοὺς σοφοὺς ἀνθρώπους. Οὔτε γὰρ πάντες ἄνθρωποι σοφοί εἰσιν, οὔτε πάντες οἱ σοφοί, ἄνθρωποι· ἀλλὰ καὶ ἥρωες ἀγαυοὶ καὶ ἀθάνατοι θεοί, φύσει κρείττονες ἀνθρώπων ὄντες, σοφοί τέ εἰσι καὶ ἀγαθοί. Τοὺς οὖν τοῖς θείοις γένεσι συντεταγμένους ἀνθρώπους σέβειν ὁ λόγος παραινεῖ, τοὺς ἰσοδαίμονας καὶ ἰσαγγέλους καὶ τοῖς ἀγαυοῖς ἥρωσιν ὁμοίους.", "st": "4.2"}, {"sp": "N", "t": "Μὴ γὰρ φαῦλόν τι δαιμόνων γένος ὑπολάβωμεν εἰσηγεῖσθαι δεῖν τιμᾶν, ὡς ἄν τῳ δόξειεν ὑπὸ τῆς συνηθείας τὴν λέξιν ἐμφαίνειν. Ὅλως γὰρ τὰ χείρονα τῆς ἀνθρωπίνης οὐσίας οὐ καθήκει τιμᾶν τῷ ἐρωτικῶς ἔχοντι τοῦ θεοῦ καὶ τῆς ἑαυτοῦ ἀξίας ἠσθημένῳ. Ἀλλ' οὐδὲ αὐτὸν τὸν ἄνθρωπον μετὰ τὰ κρείττονα τιμήσομεν, ἐὰν μὴ τοῖς κρείττοσιν ὡμοιωμένος ᾖ καὶ τῷ θείῳ χορῷ συμφερόμενος.", "st": "4.3"}, {"sp": "N", "t": "Τίς οὖν ἡ τιμὴ καὶ τούτων; τὸ ἔννομα ῥέζειν, φησί. Τοῦτο δέ ἐστι τὸ πείθεσθαι οἷς καταλελοίπασιν ἡμῖν παραγγέλμασι, καὶ ὡς νόμοις ἐμμένειν τοῖς ἐκείνων λόγοις καὶ τὴν αὐτὴν ὁδὸν μετιέναι τοῦ βίου, ἣν ἐκεῖνοι διελθόντες οὐκ ἐφθόνησαν ταύτης ἡμῖν μεταδοῦναι, ἀλλ' ὥσπερ τινὰ ἀθάνατον καὶ πατρῷον κλῆρον διηγωνίσαντο τοῖς μεταγενεστέροις διαφυλάξαι, τὰ στοιχεῖα τῶν ἀρετῶν καὶ τῆς ἀληθείας τοὺς κανόνας εἰς κοινὸν ὄφελος ἐν γράμμασι καταθέμενοι· οἷς τὸ πείθεσθαι καὶ ζῇν ἑπομένως, ἀληθεστέρα ἐκείνων τιμὴ γίγνεται, ἢ εἴ τις χοὰς αὐτοῖς ἐπιφέρῃ πολυτελεστάτας καὶ ἐναγίζῃ πλουσίως.", "st": "4.4"}, {"sp": "N", "t": "Τοιαύτη μὲν ἡ τῶν κρειττόνων τιμή, ἀπὸ τοῦ δημιουργοῦ ἀρξαμένη καὶ εἰς ἀνθρώπους τοὺς ἀγαθοὺς περατουμένη διὰ μέσων τῶν οὐρανίων καὶ αἰθερίων γενῶν.", "st": "4.5"}, {"sp": "N", "t": "Ἐπειδὴ δὲ καὶ τῶν κατὰ τὸν βίον σχέσεων πλεῖστον δεῖ ποιεῖσθαι λόγον, οἷον πατέρων καὶ συγγενῶν, (οἱ οὐ πάντως μέν εἰσιν ἀγαθοί, πάντως δὲ τὸ τίμιον ὡς πρὸς ἡμᾶς τῇ ἀξίᾳ τῆς σχέσεως κέκτηνται) τούτου χάριν ἐπήγαγε.", "st": "4.6"}, {"sp": "SEC", "t": "V · 4", "st": "5"}, {"sp": "N", "t": "<span class=\"lemma\">τούς τε γονεῖς τίμα, τούς τ' ἄγχιστ' ἐκγεγαῶτας.<\/span>", "st": "5.0"}, {"sp": "N", "t": "Τοὺς μὲν ἀγαθοὺς ἀνθρώπους, ὡς δαιμονίους καὶ θείους, σέβειν ὁ λόγος ὑπέθετο· τοὺς δὲ γονέας καὶ τοὺς ἐγγύς τι τούτων τῇ φυσικῇ συγγενείᾳ προσήκοντας, ὁποῖοί ποτ' ἂν ὦσι, δι' αὐτὴν τὴν τῆς σχέσεως ἀνάγκην τιμᾶν εἰσηγεῖται. Ὅπερ γὰρ ἡμῖν οἱ κρείττονές εἰσι κατὰ τὴν ἀΐδιον συγγένειαν, πατέρων μὲν τάξιν ἔχοντες οἱ οὐράνιοι, συγγενῶν δὲ τιμίων οἱ ἥρωες· τοῦτο πρὸς τὸν θνητὸν βίον συντελοῦσιν ἡμῖν οἱ γονεῖς καὶ οἱ ἀγχιστεῖς, οἱ ἐγγύτατα τῶν γονέων ὄντες, καὶ διὰ τοῦτο τῇ μετὰ γονέας τιμῇ σεμνυνόμενοι.", "st": "5.1"}, {"sp": "N", "t": "Πῶς οὖν καὶ τούτους τιμήσομεν; Ἆρα τὸν ἑαυτῶν βίον πρὸς τὴν ἐκείνων ἀπευθύνοντες γνώμην, ὥστε δοξάζειν τε ταῦτα καὶ πράττειν, ἃ ἂν ἐκείνοις εἴη φίλα; Ἀλλ' οὕτως ἂν περιτραπείη ἡ τῶν ἀρετῶν ἄσκησις πρὸς κακίας σπουδήν, εἰ τύχοιεν ὄντες πονηροὶ οἱ πατέρες. Ἀλλὰ ἀτιμάσομεν αὐτοὺς εἰς πάντα διὰ τὴν τῆς κακίας κατάγνωσιν; καὶ πῶς ἔτι τῷ παρόντι νόμῳ πειθόμεθα; Πῶς δὲ τὴν θεοειδῆ εἰκόνα τῶν γονέων ἢ τὴν ἡρωϊκὴν τῶν ἀγχιστέων ἔμφασιν μὴ τιμῶντες οὐκ εἰς ἐκείνους ἀσεβήσομεν, οἷς τούτους ἐοικέναι φαμέν; καὶ οὕτως ἡ δοκοῦσα δι' ἀπειθείας γονέων ἀρετὴ ἡμῖν ἀσκεῖσθαι εἰς μεῖζον κακὸν περιστήσεται, τὴν ἀσέβειαν. Πειθόμενοι δὲ πάντα γονεῦσι, πῶς οὐκ ἂν πάλιν τῆς εὐσεβείας ἀποπέσοιμεν καὶ τῆς ἄλλης ἀρετῆς, εἰ τύχοιεν ἐκεῖνοι διὰ μοχθηρίαν τρόπου μὴ πρὸς τὰ ὄντως καλὰ παιδαγωγοῦντες ἡμᾶς;", "st": "5.2"}, {"sp": "N", "t": "Εἰ μὲν γὰρ τοῦτο πάντως ἦν ἀληθὲς καὶ καλόν, ὃ τοῖς γονεῦσι παρίστατο, σύμφωνος ἡ τῶν γονέων τιμὴ τῇ τῶν κρειττόνων ἐγίνετο. Εἰ δὲ ἔστιν ὅτε τῶν θείων νόμων ἀνήκοός ἐστιν ἡ τῶν γονέων προαίρεσις, τί δεῖ ποιεῖν εἰς ἀντινομίαν ἐμπεσόντας τοιαύτην, ἢ τοῦτο, ὃ καὶ ἐπὶ τῶν ἄλλων καθηκόντων ἐκ περιστάσεως εἰς ἐναντίωσιν ἐλθόντων προσήκει φυλάττειν;", "st": "5.3"}, {"sp": "N", "t": "Μειζόνων γὰρ καὶ ἐλαττόνων προκειμένων καλῶν τὰ μείζονα πρὸ τῶν ἐλαττόνων ποιεῖσθαι δεῖ, ὅταν μὴ ἀμφότερα ἐξῇ διασώζειν. Οἷον καλὸν μὲν τῷ θεῷ πείθεσθαι, καλὸν δὲ καὶ τοῖς γονεῦσι. Εἰ γοῦν ἐς ταὐτὰ ἄγοι ἡ ἀμφοτέρων πειθώ, ἕρμαιον ἂν εἴη καὶ ἄμαχον τὸ γινόμενον· εἰ δὲ πρὸς ἄλλο μὲν ὁ θεῖος νόμος, πρὸς ἄλλο δὲ οἱ γονεῖς φέροιεν, μαχομένης τῆς αἱρέσεως, τοῖς ἀμείνοσιν ἕπεσθαι δεῖ, πρὸς ταῦτα μόνον ἀπειθοῦντας τοῖς γονεῦσι, πρὸς ἃ καὶ αὐτοὶ τοῖς θείοις νόμοις οὐ πείθονται. Τὸν γὰρ φυλάττειν βουλόμενον τοὺς τῆς ἀρετῆς κανόνας οὐχ οἷόν τε τοῖς τούτους παραβαίνουσι συμφωνεῖν.", "st": "5.4"}, {"sp": "N", "t": "Εἰς δὲ τὰ ἄλλα πάντα γονέας τιμήσομεν ὑπερβαλλόντως, σώματος ὑπηρεσίαν καὶ χρημάτων χορηγίαν αὐτοῖς παρέχοντες ὅτι μάλιστα προθυμοτάτην. Δίκαιον γὰρ χρῆσθαι αὐτοὺς οἷς ἐγέννησάν τε καὶ ἔθρεψαν.", "st": "5.5"}, {"sp": "N", "t": "Ὃ δὲ τῆς ἀπ' ἐκείνων διαδοχῆς οὐκ ἤρτηται, τοῦτο ἐλεύθερον τῆς ἀπ' ἐκείνων δεσποτείας ἀφίησιν ὁ νόμος, καὶ τὸν ὄντως πατέρα ζητεῖν παρακελεύεται, κἀκείνου ἔχεσθαι, καὶ τῆς πρὸς ἐκεῖνον ὁμοιώσεως πλείστην ἐπιμέλειαν ποιεῖσθαι. Καὶ οὕτως ἀμφότερα δύνασθαι συμβαίνει, τά τε θεῖα ἀγαθὰ δύνασθαι τηρεῖν καὶ τὰ ἀνθρώπινα. Καὶ οὔτε δι' οἴησιν ἀρετῆς γονέων θεραπείας ὀλιγωρήσομεν, οὔτε διὰ τὴν ἀνόητον ὕπειξιν τὸ μέγιστον τῶν κακῶν ἀσέβειαν εἰσδεξόμεθα.", "st": "5.6"}, {"sp": "N", "t": "Εἰ γὰρ προτείνοιεν θάνατον μὴ πειθομένοις ἢ κλήρου ἀλλοτρίωσιν, οὐδὲν ἐκφοβεῖσθαι δεῖ τοῖς τοιούτοις, ἀλλ' εὖ εἰδέναι τί τὸ ταῦτα πεισόμενον, καὶ ὅτι ᾧ ἐγέννησαν ἀπειλοῦσι μόνῳ· τὸ δὲ ἀπαθὲς τούτων ἐλεύθερον προσήκει τηρεῖν καὶ μόνῳ θεῷ εὐπειθές.", "st": "5.7"}, {"sp": "N", "t": "Τιμὴ οὖν γονέων ἡ ὄντως, ἣν δίδωσιν ὁ τῆς ἀρετῆς σκοπός, μήτε σωμάτων φειδομένους ἡμᾶς μήτε χρημάτων, ἀλλ' ἑκόντας αὐτοῖς ὑποτετάχθαι εἰς πάντα τὰ τοιαῦτα. Πρέπει γὰρ μήτε τὴν δι' αὐτουργίας θεραπείαν ἐπὶ γονέων παραιτεῖσθαι, ἐνευσχημονεῖν δὲ μᾶλλον αὐτῇ, ὅσῳ ἂν μᾶλλον ἐπίπονος γένηται καὶ δουλοπρεπής, μήτε οὐσίας δαπανωμένης φειδωλοὺς γίνεσθαι, ἀλλὰ πάντα πρὸς τὴν ἐκείνων χρείαν ἑτοίμως παρέχεσθαι, γεγηθότας καὶ ἡδομένους ἐπὶ τοῖς εἰς ἐκείνους πόνοις τε καὶ ἀναλώμασι. Τὸ γὰρ εὐχαρίστως ταῦτα ποιεῖν καὶ τὸν τῆς ἀρετῆς διασώζει νόμον καὶ τὸν τῆς φύσεως ἀποδίδωσιν ἔρανον.", "st": "5.8"}, {"sp": "N", "t": "Τοιαύτη μὲν ἡ τῶν γονέων τιμή. Ἡ δὲ τῶν ἀγχιστέων, δευτέρα μετ' ἐκείνην τεταγμένη, πρὸς τὴν τῆς φύσεως ἐγγύτητα παραμετρήσει τὴν θεραπείαν, τοσοῦτον τῆς μετὰ γονέας τιμῆς ἑκάστῳ τῶν συγγενῶν νέμουσα, ὅσον ἂν ἡ πρὸς ἐκείνους ἐγγύτης ὑποφαίνῃ· δῆλον δὲ ὅτι καὶ ἐπὶ τούτων τῆς ἀρετῆς ἀδεσπότου μενούσης.", "st": "5.9"}, {"sp": "SEC", "t": "VI · 5", "st": "6"}, {"sp": "N", "t": "<span class=\"lemma\">τῶν δ' ἄλλων ἀρετῇ ποιεῦ φίλον, ὅστις ἄριστος.<\/span>", "st": "6.0"}, {"sp": "N", "t": "Μετὰ τὴν πρώτην τιμὴν τῆς ἄνω συγγενείας καὶ ἑπομένην ἐκείνῃ τὴν περὶ γονέας καὶ συγγενεῖς ἀκολούθως ὁ φιλοποιὸς παραδίδοται νόμος, τῶν ἔξω τοῦ γένους τὸν ἄριστον εἰς φιλίαν ἐκλέγεσθαι καὶ πρὸς τὴν τῶν ἀρετῶν κοινωνίαν αὐτῷ συνάπτεσθαι κελεύων, ἵνα τὸν ἀγαθὸν ἄνδρα δι' ἀγαθὴν αἰτίαν ἔχωμεν φίλον, καὶ μὴ κατ' ἄλλας χρείας αὐτὸν οἰκειώμεθα, ὥστ' ἐοικέναι τὸ παράγγελμα τοῦτο τῇ περὶ τῶν μετηλλαχότων τὸν βίον σπουδαίων ἀνδρῶν ὑποθήκῃ. Ὡς γὰρ ἐκεῖ τοὺς ἐπιστήμονας μόνους τῶν ἀνθρώπων ἔλεγε δεῖν τιμᾶν· οὕτως ἐνταῦθα τοὺς ἀγαθοὺς φιλοποιεῖσθαι παραινεῖ μόνους, διδοὺς ἐπὶ μὲν τῶν ἄλλων ἐκλογήν, ἐπὶ δὲ γονέων καὶ συγγενῶν ἀρκούμενος τῇ φύσει. Ἁπλῶς γὰρ τὸ πρόσωπον τοῦ πατρὸς καὶ τοῦ ἀδελφοῦ συνεισάγει τὴν τιμήν, ἐπὶ δὲ τῶν ἄλλων ἡ ἀρετὴ ποιεῖ τὸ τίμιον, ὥσπερ καὶ ἐπὶ τῶν ἐκ τοῦ βίου ἀπελθόντων. Τὰ δὲ πρὸ τούτων κατ' αὐτὴν τὴν φύσιν ἐστὶ τίμια, ἐκεῖ μὲν θεοὶ καὶ ἥρωες, ἐνταῦθα δὲ πατέρες καὶ συγγενεῖς, ἐν θνητῇ φύσει τῆς ἀθανάτου συγγενείας ἡμῖν εἰκόνας προτείνοντες. Τοιαύτη μὲν ἡ πρώτη θήρα καὶ ἡ κτῆσις τοῦ φίλου. Τίς δὲ ἡ τήρησις αὐτοῦ ἡ πρὸς κοινωνίαν τῶν ἀγαθῶν ἡμῖν συντελοῦσα, καὶ τίς ἡ ἀπόθεσις, ἐὰν πρὸς τὸ χεῖρον μεταβαλλόμενος φαίνηται καὶ μὴ πειθόμενος ταῖς πρὸς τὸ βέλτιον ἀγούσαις συμβουλίαις, ἑξῆς λέγει.", "st": "6.1"}, {"sp": "SEC", "t": "VII · 6–8", "st": "7"}, {"sp": "N", "t": "<span class=\"lemma\">Πραέσι δ' εἶκε λόγοις ἔργοισί τ' ἐπωφελίμοισι.<br>Μηδ' ἔχθαιρε φίλον σὸν ἁμαρτάδος εἵνεκα μικρῆς,<br>ὄφρα δύνῃ· δύναμις γὰρ ἀνάγκης ἐγγύθι ναίει.<\/span>", "st": "7.0"}, {"sp": "N", "t": "Πῶς δεῖ προσφέρεσθαι τοῖς φίλοις ἐνταῦθα διαλέγεται, καὶ πρῶτον μὲν ὅτι τὰ καλὰ εἰσηγουμένοις αὐτοῖς καὶ ἐπ' ὠφελείᾳ τῇ ἡμετέρᾳ πράττουσιν ὁτιοῦν ἑκόντας δεῖ πειθαρχεῖν. Πρὸς γὰρ τοῦτο τὸ κοινωνικὸν ἀγαθὸν ὁ τῆς φιλίας συνάπτει νόμος, ὅπως ἡμεῖς τε ὠφελώμεθα παρ' ἐκείνων εἰς ἀρετῆς ἐπίδοσιν καὶ παρ' ἡμῶν ἐκεῖνοι. Ὡς γὰρ κοινὴν ὁδὸν τοῦ ἀρίστου βίου πορευομένους, ὅπερ ἂν ἄλλος ἄλλου προΐδῃ μᾶλλον, τοῦτο εἰς κοινὸν ὄφελος κατατίθεσθαι δεῖ, πράως μὲν εἴκοντας τοῖς καλῶς ὑφηγουμένοις τῶν φίλων, πράως δὲ αὐτοῖς τῶν καλῶν τὴν κοινωνίαν προτείνοντας, περὶ δὲ χρημάτων ἢ δόξης ἤ τινος ἄλλου τῶν ἐκ τῆς θνητῆς συστοιχίας μηδεπώποτε αὐτοῖς διαφερομένους. Τοῦτο γὰρ ἦν ἁμαρτάδος εἵνεκα μικρῆς εἰς ἀπέχθειαν καθίστασθαι τοῖς περὶ τὰ μέγιστα ἀγαθὰ φίλοις ἡμῖν ὑπάρχουσιν. Εἰς πάντα οὖν τῶν φίλων ἀνεξόμεθα, ὡς ὑπὸ μεγίστης ἀνάγκης τῆς φιλικῆς διαθέσεως πιεζόμενοι, πλὴν ἑνός. Οὐ γὰρ δὴ καὶ πρὸς τὸ χεῖρον ὑποφερομένοις αὐτοῖς εἴξομεν, οὐδὲ μεταβαλλομένοις ἐκ τῆς περὶ φιλοσοφίαν σπουδῆς εἰς ἑτέραν τινὰ τοῦ βίου πρόθεσιν ἐπακολουθήσομεν καὶ αὐτοὶ συνεκφερόμενοι τοῖς ἀποπίπτουσιν ἀπὸ τοῦ πρὸς ἀρετὴν σκοποῦ, ἀλλὰ μάλιστα μὲν πάσῃ μηχανῇ πειρασόμεθα τὸν φίλον ἐπανορθώσασθαι· μὴ πείθοντες δὲ ἡσυχίαν ἕξομεν, οὔτε ἐχθρὸν ποιούμενοι διὰ τὴν προϋπηργμένην φιλίαν, οὔτε φίλον ἔτι διὰ τὴν πρὸς τὸ χεῖρον μεταβολήν. Ὥστε τούτου χάριν τὸν φίλον ποτὲ ἀποθησόμεθα, ὡς μηκέτι δυνάμενον εἶναι κοινωνὸν ἡμῖν ἀρετῆς, ἧς ἕνεκα καὶ τὴν ἀρχὴν φίλον αὐτὸν ἐποιησάμεθα. Ἡ δὲ ἀπόθεσις φυλαττέτω τὸ μὴ εἰς ἔχθραν μεταπεσεῖν. Δεῖ γάρ, εἰ καὶ ἐκεῖνος τῆς φιλίας ἑαυτὸν ὑπεξήγαγεν, ἡμᾶς γοῦν πλείστην ἐπιμέλειαν ποιεῖσθαι, ὅπως ἐπανακληθείη πρὸς τὸ δέον, οὐκ ἀγαπῶντας τὴν ἀπόπτωσιν τοῦ φίλου οὐδὲ ὑπερφρονοῦντας τὸ καταδεὲς αὐτοῦ τῆς γνώμης, ὀδυρομένους δὲ μᾶλλον καὶ θρηνοῦντας ὑπεραλγεῖν αὐτοῦ καὶ ὑπερεύχεσθαι, καὶ πάντα πειρᾶσθαι ποιεῖν τὰ πρὸς τὴν ἐκ μεταμελείας σωτηρίαν αὐτὸν ἐπανάγοντα. Τοιαῦτα δέ ἐστι τὸ μήτε περὶ χρημάτων μήτε περὶ δόξης αὐτῷ διαφέρεσθαι, καὶ τὸ μὴ ἐφ' ὕβρει τῆς κοινωνίας αὐτὸν ἀποστερεῖν, μηδὲ φιλοτιμίαν ἑαυτοῦ ποιεῖσθαι τὴν ἐκείνου δυστυχίαν.", "st": "7.1"}, {"sp": "N", "t": "Ἐπειδὴ δὲ καὶ πρὸς τὴν ἀρίστην τῶν φίλων τήρησιν καὶ πρὸς τὴν εὔλογον ἀπόθεσιν καὶ πρὸς τὴν ἐκ μεταμελείας αὐτῶν ἐπανάκλησιν πλεῖστα συμβάλλεται τὸ ἡμέτερον ἀνεξίκακον καὶ περὶ μηδενὸς πρὸς τοὺς φίλους μικρολογούμενον, μηδὲ ἐξεταστικὸν πρὸς ἀκρίβειαν, ἀλλ' ὅσον οἷόν τε ὑπομονητικόν· διὰ τοῦτο ἐπήγαγεν ὄφρα δύνῃ. Εἶτα ἵνα μὴ τὴν δύναμιν τῷ τῆς προαιρέσεως μέτρῳ κανονίσῃ τις, ἀλλ' αὐτῷ τῷ τῆς φύσεως φορητῷ, ὅσον ἡ ἀνάγκη προσελθοῦσα ἐξευρίσκει, ἐπήγαγε δύναμις γὰρ ἀνάγκης ἐγγύθι ναίει. Ἕκαστος γάρ, ὧν οἴεται δύνασθαι, πλέον δυνάμενος ὑπὸ τῆς ἀνάγκης ἐλέγχεται. Τοσοῦτον οὖν προθυμεῖσθαι χρὴ τῶν φίλων ἀνέχεσθαι, ὅσον ἡ ἀνάγκη δείκνυσιν ἡμᾶς δυναμένους, καὶ τό γε ἐξαίφνης ἀφόρητον φανὲν τῇ τῆς φιλίας ἀνάγκῃ φορητὸν ποιεῖν. Μὴ γὰρ δή που τὰ πρὸς βίαν ἐπιταττόμενα μόνα οἰώμεθα προσήκειν γενναίως ὑπομένειν, ἀλλὰ καὶ τὰ πρὸς φυλακὴν τῶν φίλων καὶ ἀνάκλησιν συντείνοντα μείζονος ὑπομονῆς ἄξια δεῖ τίθεσθαι, ὡς τῆς θείας ἀνάγκης ἐπιτάγματα. Δυνατωτέρα δὲ παρὰ τοῖς εὖ φρονοῦσιν ἡ τοῦ νοῦ ἀνάγκη τῆς ἔξωθεν βίας. Εἴτε οὖν πρὸς τὴν ἐκ περιστάσεως ἀνάγκην ἀπίδοις, εἴτε πρὸς τὴν ἑκούσιον, τὴν ἐκ τῶν ἐπιστημονικῶν ὅρων συμπληρουμένην καὶ ἐκ τῶν θείων νόμων καθήκουσαν, ἐξευρήσεις τὸ ἐνυπάρχον σοι τῆς δυνάμεως μέτρον, ὃ νῦν ὁ λόγος εἰσηγεῖται δεῖν τοῖς φίλοις προσφέρειν, ἐν τῷ προστάττειν μὴ προχείρως αὐτοῖς εἰς ἀπέχθειαν καθίστασθαι ἁμαρτάδος εἵνεκα μικρῆς, τὰ ἔξω τῆς ψυχῆς πάντα μικρὰ θέμενος καὶ ἀπαγορεύων μὴ φειδοῖ τούτων τὸν φίλον ἐχθρὸν ποιεῖν, ἀδιαφορίᾳ δὲ μᾶλλον τῇ περὶ τὰ τοιαῦτα καὶ τὸν ἀποπεσόντα φίλον ἀνακαλεῖσθαι καὶ πανταχοῦ τοῦτο ἑαυτοῖς συνειδέναι, ὅτι ὅσον ἐφ' ἡμῖν καὶ τοὺς ὄντας φίλους ἐτηρήσαμεν καὶ τοὺς πρὸς τὸ χεῖρον ὑπενεχθέντας ἀνεκτησάμεθα, καὶ οὔτε τὴν ἀρχὴν εἰς ἔχθραν τινὰ κατεστήσαμεν, οὔτε παρ' ἑαυτοῦ γενόμενον ἐχθρὸν τοῖς ἴσοις ἠμειψάμεθα.", "st": "7.2"}, {"sp": "N", "t": "Ταῦτα γὰρ ὁ τῆς φιλίας ὑπαγορεύει θεσμός, μεγίστης οὔσης ἀρετῆς καὶ ταῖς ἄλλαις ὡς τελειότητος ἐπιφαινομένης. Πέρας μὲν γὰρ τῶν ἀρετῶν ἡ φιλία, ἀρχὴ δὲ ἡ εὐσέβεια. Καί ἐστιν ὁ τῆς εὐσεβείας λόγος σπέρμα τῶν ἀγαθῶν ἁπάντων ἡμῖν· ἡ δὲ τῆς φιλίας ἕξις ὁ τελειότατος τῶν ἀρετῶν καρπός. Ὥσπερ οὖν δικαιοσύνης ποιεῖσθαι δεῖ λόγον οὐ μόνον πρὸς τοὺς δικαίως ἡμῖν προσφερομένους, ἀλλὰ καὶ πρὸς τοὺς ἀδικεῖν ἐγχειροῦντας, ἵνα μὴ τῷ ἀνταδικεῖν εἰς τὴν ἴσην καχεξίαν αὐτοῖς ἔλθωμεν· οὕτω καὶ τῆς φιλίας ἀντέχεσθαι δεῖ, τοῦτ' ἔστι τῆς φιλανθρωπίας τῆς πρὸς ἅπαντας, οἳ τοῦ γένους ἡμῖν κοινωνοῦσιν. Ἐν τάξει δὲ τῇ πρεπούσῃ τὰ τῆς φιλίας μέτρα ποιησόμεθα, τοὺς μὲν ἀγαθοὺς ὡς ἀποσώζοντας τὴν τοῦ ἀνθρώπου τελειότητα καὶ διὰ τὴν φύσιν καὶ διὰ τὴν γνώμην παντοίως ἀσπαζόμενοι, τοὺς δὲ φαύλους ὡς μηδὲν ἀπὸ γνώμης εἰς αἵρεσιν φιλίας ἡμῖν ὑπέχοντας διὰ μόνην τὴν κοινὴν φύσιν ἀγαπῶντες. Διὸ καὶ λέγεται ὀρθῶς, ὡς οὐδεὶς ἐχθρὸς τῷ σπουδαίῳ, καὶ μόνος ὁ ἀγαθὸς ἀγαθῷ φίλος. Ὡς μὲν γὰρ τὸν ἄνθρωπον φιλῶν, οὐδὲ τὸν κακὸν ἐχθρὸν τίθεται, ὡς δὲ τὸν ἀρετῇ κεκοσμημένον ζητῶν πρὸς κοινωνίαν τὸν ἀγαθὸν ἐκ πάντων ἐκλέγεται, μιμούμενος καὶ ἐν τοῖς τῆς φιλίας μέτροις τὸν θεόν, ὃς μισεῖ μὲν οὐδένα ἄνθρωπον, τὸν δὲ ἀγαθὸν διαφερόντως ἀσπάζεται. Τὸ γὰρ τῆς φιλανθρωπίας ἀγαθὸν κοινῇ τῷ γένει προτείνων τῆς προσηκούσης μοίρας ἕκαστον ἀξιοῦ, τοὺς μὲν ἀγαθοὺς πρὸς ἑαυτὸν ἀνάγων, τοὺς δὲ τῆς ἀρετῆς φυγάδας τοῖς τῆς δίκης νόμοις πρὸς τὸ δέον ἀπευθύνων. Τοῦτο γὰρ τοῖς ἑκατέροις σύμμετρόν τε καὶ ὠφέλιμον. Οὕτω καὶ ἡμᾶς προσήκει τὴν φιλίαν τηρεῖν πρὸς πάντας ἀνθρώπους μετὰ τῆς πρὸς τὴν ἀξίαν ἀπονεμήσεως.", "st": "7.3"}, {"sp": "N", "t": "Καὶ γὰρ σωφροσύνην καὶ δικαιοσύνην πρὸς ἅπαντας ἕξομεν, καὶ οὐ πρὸς μόνους τοὺς δικαίους καὶ σώφρονας· οὐδὲ ἀγαθοὶ μὲν τοῖς ἀγαθοῖς ἐσόμεθα, κακοὶ δὲ τοῖς κακοῖς. Οὕτω γὰρ ῥᾳδίως συμμεταβαλλόμενοι τοῖς προσπίπτουσιν οὐδὲν οἰκεῖον ἕξομεν ἀγαθόν, ὃ διὰ παντὸς καὶ πρὸς πάντας τηρήσομεν. Εἰ δὲ ἕξιν τὴν ἀρετὴν κεκτήμεθα, οὐκ ἔστιν ἐπὶ τῷ βουλομένῳ ταύτης ἡμᾶς ἀποστῆσαι· οὐδὲ τοῖς ἐντυγχάνουσι τὰς διαθέσεις συναλλοιώσομεν, τὸ μόνιμον τῆς ἀρετῆς εὐτυχοῦντες. Ὅπερ οὖν ἐπὶ τῶν ἄλλων ἀρετῶν, τοῦτο καὶ ἐπὶ τῆς φιλίας δεήσει φυλάττειν, φιλίας, ὡς ἔφαμεν, μεγίστης οὔσης ἀρετῆς, φιλανθρωπίας δὲ κοινῶς μὲν πρὸς ἅπαντας, ἰδίως δὲ πρὸς τοὺς ἀγαθοὺς θεωρουμένης, ὅτι καὶ τὸ τῆς φιλανθρωπίας ὄνομα αὐτῇ μᾶλλον ἐπιπρέπει. Ταῦτα δὲ περὶ τούτων, ἐπὶ δὲ τὰ ἑξῆς προΐωμεν.", "st": "7.4"}, {"sp": "SEC", "t": "VIII · 9–11", "st": "8"}, {"sp": "N", "t": "<span class=\"lemma\">Ταῦτα μὲν οὕτως ἴσθι· κρατεῖν δ' εἰθίζεο τῶνδε·<br>γαστρὸς μὲν πρώτιστα καὶ ὕπνου λαγνείης τε<br>καὶ θυμοῦ.<\/span>", "st": "8.0"}, {"sp": "N", "t": "Συστέλλειν δεῖ ταῦτα πάντα καὶ τάττειν, ἵνα μὴ παρενοχλῇ τὸν λογισμόν. Φέρε οὖν, τὴν ἀλογίαν ὅλην ἐν τάξει χαλινώσωμεν ὀρθαῖς παιδαγωγίαις, ἐπειδὴ καὶ τὰ ταύτης μέρη χορηγά ἐστι κακίας ἀλλήλοις ἐφεξῆς. Οἷον γαστὴρ ἄγαν πληρουμένη ὕπνον πολὺν ἐπάγεται· ἀμφότερα δὲ ἀφθονίαν παρέχεται σπέρματος, ἥτις ἀμέτρως ἐγείρει πρὸς ἀφροδίσια καὶ τὸ ἐπιθυμητικὸν τῆς ψυχῆς πρὸς τὸ ἀκόλαστον ἐποξύνει. Τούτῳ δὲ τὸ θυμικὸν συνεκφερόμενον διὰ πάσης ἴεται μάχης, νῦν μὲν σιτία καὶ ποτὰ ἐκδικοῦν, νῦν δὲ περὶ ἑταίρας μαχόμενον καὶ ἄλλοτε ἄλλας ἡδονὰς φιλονεικοῦν κτήσασθαι. Κρατεῖν οὖν ἐθίζου τούτων, ἀπὸ τῆς γαστρὸς πρώτης ἀρξάμενος, ἵνα τοῦ τε λόγου κατήκοα γένηται τὰ ἄλογα τῆς ψυχῆς εἴδη, καὶ αὐτὸς ἐπὶ σαυτοῦ τὴν εὐσέβειαν καὶ τὴν περὶ γονέας τιμὴν καὶ πάντα, ἃ μικρῷ πρόσθεν παρήνεσεν ὁ λόγος, ἀπαραγώγως φυλάξαι δυνηθῇς. Δύναμις γὰρ τῆς τῶν προτέρων τηρήσεως ταυτὶ τὰ ἑπόμενα. Ἐπεὶ παραβαθείη ἂν πάντα ἐκεῖνα, μὴ ἑπομένων τῷ λογισμῷ τῶν παθητικῶν δυνάμεων. Ἢ γὰρ θυμὸς ἐξετάραξε κατὰ γονέων, ἢ ἐπιθυμία πρὸς ἀπείθειαν αὐτῶν ὥπλισε. Καὶ πάλιν, ἢ θυμὸς πρὸς βλασφημίαν ἐπήγειρεν, ἢ ἐπιθυμία χρημάτων πρὸς ἐπιορκίαν. Καὶ ὅλως τὰ κακὰ διὰ ταύτας πράττεται τὰς δυνάμεις, μὴ τῆς λογικῆς ψυχῆς πρὸς τὸ δέον αὐτὰς ἀπευθυνούσης. Ἐντεῦθεν ἀσέβειαι παντοῖαι καὶ πόλεμοι συγγενικοὶ καὶ φίλων προδοσίαι καὶ πάντα τῆς παρανομίας τὰ εἴδη, ὡς καὶ βοᾶν ἀναγκάζεσθαί τινας· <span class=\"sm-q\"><span class=\"sm-qi\">μανθάνω μὲν οἷα μέλλω δρᾶν κακά,<br>θυμὸς δὲ κρείσσων τῶν ἐμῶν βουλευμάτων,<\/span><\/span>", "st": "8.1"}, {"sp": "N", "t": "ἄλλους δὲ ἢ τοὺς αὐτοὺς ἄλλοτε βοᾶν·", "st": "8.3"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">μανθάνω μὲν οἷα μέλλω δρᾶν κακά,<br>ἐπιθυμία δὲ κρείσσων τῶν ἐμῶν βουλευμάτων,<\/span><\/span>", "st": "8.4"}, {"sp": "N", "t": "καί·", "st": "8.5"}, {"sp": "N", "t": "Εὖ μέν μοι δοκεῖς λέγειν, πέπονθα δὲ τὸ τῶν πολλῶν πάθος, οὐ πάνυ σοι πείθομαι.", "st": "8.6"}, {"sp": "N", "t": "Τὸ γὰρ λογικὸν γένος πρὸς τὴν τῶν καλῶν αἴσθησιν εὐφυῶς διακείμενον, εὐανάμνηστόν ἐστι καὶ εὐάγωγον πρὸς τὴν τοῦ ὀρθοῦ λόγου διδασκαλίαν, ὅταν μὴ ταῖς παθητικαῖς ὁλκαῖς, ὥσπερ τισὶ μολυβδίσιν, ὑποφέρηται πρὸς κακίαν. Δεῖ οὖν καὶ αὐτοὺς ἡμᾶς εἰδέναι τὰ δέοντα, καὶ τὰς ἀλόγους δυνάμεις ἐθίσαι, ὅσον οἷόν τε, καὶ αὐτὰς τῷ ἐν ἡμῖν λόγῳ συνέπεσθαι. Οὕτω δὲ ταχθέντων τῶν παθῶν, ἱκανὸς ὁ λογισμὸς γένοιτο ἂν ἀπερισπάστως φυλάξαι τὰ πρῶτα παραγγέλματα, περὶ ὧν εἴρηται ταῦτα μὲν οὕτως ἴσθι. Περὶ δὲ τῶν ἑξῆς ἐθίζου κρατεῖν εἶπεν, ἐνδεικνύμενος, ὅτι τὸ μὲν λογικὸν διδασκαλίᾳ καὶ ἐπιστήμῃ τάττεται, τὸ δὲ ἄλογον ἐθισμοῖς καὶ πλάσεσι τρόπον τινὰ σωματικαῖς· οὕτω δὲ καὶ τῶν ζώων τὰ ἄλογα μόνῳ ἔθει ἄγεται ὑπὸ τῶν ἀνθρώπων. Ἐθισθεῖσα οὖν γαστὴρ ζητεῖν τὰ μέτρια, τάς τε ἄλλας ἐπιθυμίας τοῦ σώματος κοσμιωτέρας παρέχεται καὶ τὸν θυμὸν ἐμμελέστερον, ἵν' ἐφ' ἡσυχίας τὰ περὶ τῶν δεόντων βουλευώμεθα, μὴ σφόδρα ὑπὸ τῶν συνεχόντων παθῶν ἐνοχλούμενοι, ὅθεν καὶ τὸ ἑαυτοὺς γνῶναι ὅ ἐσμεν τῇ ἀληθείᾳ καὶ τὸ αἰδεῖσθαι οὓς ἔγνωμεν διδασκόμεθα. Ἐκ δὲ τῆς γνώσεως ταύτης καὶ τῆς συνούσης αὐτῇ αἰδοῦς ἡ τῶν αἰσχρῶν φυγὴ παραγίνεται. Τὰ γὰρ κακὰ αἰσχρὰ λέγεται, ὡς ἀπρεπῆ καὶ ἀνάξια δρᾶσθαι ὑπὸ λογικῆς οὐσίας· περὶ ὧν τὰ ἑξῆς ἐπιλέγει.", "st": "8.7"}, {"sp": "SEC", "t": "IX · 11–12", "st": "9"}, {"sp": "N", "t": "<span class=\"lemma\">Πρήξῃς δ' αἰσχρόν ποτε μήτε μετ' ἄλλου,<br>μήτ' ἰδίῃ· πάντων δὲ μάλιστ' αἰσχύνεο σαυτόν.<\/span>", "st": "9.0"}, {"sp": "N", "t": "Ἢ γὰρ καθ' ἑαυτοὺς πράττοντές τι αἰσχρὸν ἀδιάφορον αὐτὸ ἡγούμεθα, ὃ μετ' ἄλλου οὐκ ἂν ἐπράξαμέν ποτε, τὸν κοινωνὸν τῆς πράξεως αἰσχυνόμενοι· ἢ ἀνάπαλιν, συμπεριφερόμενοί τισι πράττομεν ἃ μή ποτ' ἂν καθ' ἑαυτοὺς ἐδράσαμεν, τῇ κοινωνίᾳ τῶν συμπραττόντων εἰς παρρησίαν τοῦ ἔργου προκαλούμενοι. Διὰ τοῦτο προανεῖλεν ἑκατέραν ὁδὸν τῆς εἰς τὸ αἰσχρὸν καὶ τὸ κακὸν παρεκβάσεως. Εἰ γὰρ τὸ αἰσχρὸν τῇ ἀληθείᾳ φευκτόν, οὐκ ἄν ποτε διὰ περίστασιν αἱρετὸν γένοιτο. Διὸ συνάψας εἶπε, μήτε μετ' ἄλλου, μήτ' ἰδίῃ· ἵνα μήτε μόνωσις ἐπεγείρῃ σε πρὸς τὸ μὴ πρέπον, μήτε κοινωνία εὐαπολόγητόν σοι ποιήσῃ τὴν ἁμαρτίαν. Εἶτ' ἐπήγαγε τὴν αἰτίαν, τὴν μόνην τῶν κακῶν ἀποτρέπουσαν, πάντων δὲ μάλιστ' αἰσχύνεο σαυτόν. Ἐὰν γὰρ ἐθισθῇς σαυτὸν αἰσχύνεσθαι, ἕξεις πανταχοῦ, ὃν αἰδεσθήσῃ, οἰκειότατον φύλακα καὶ ἀναπόδραστον. Ἐπεὶ πολλοὶ μονωθέντες φίλων, ἢ οἰκετῶν, ἔδρασαν ταῦτα, ἃ πρότερον δι' ἐκείνους ποιῆσαι ἠσχύνοντο. Ἆρ' οὖν οὐδένα εἶχον συνόντα; ἐῶ θεόν· (πορρωτέρω γὰρ οὗτος τῆς τῶν κακῶν συνειδήσεως·) ἀλλὰ ἑαυτοὺς οὐκ εἶχον καὶ τὸ τοῦ συνειδότος κριτήριον; Εἶχον μὲν οὖν· ἀλλ' ἠγνόουν ὅτι εἶχον, τοῖς πάθεσι κατατεινόμενοι. Οἱ δὲ τοιοῦτοι τὸ ἐν αὐτοῖς λογικὸν ἄτιμον καὶ ἀνδραπόδου φαυλότερον ἔθεντο. Οἰκειότατον οὖν ἐπίτροπον ἔχε σαυτόν· καὶ πρὸς τοῦτον ἐπιστρέφων κατάρχου τῆς ἀποτροπῆς τῶν κακῶν. Ἡ γὰρ ἑαυτοῦ αἰδὼς ἑκάστῳ φυγὴ τῶν αἰσχρῶν καὶ ἀναξίων τῆς λογικῆς οὐσίας ἐξ ἀνάγκης γίνεται. Ὁ δὲ οὕτως ἀπαξιῶν τὰ κακὰ πῶς πρὸς ἀρετὴν οἰκειοῦται, ἐπάγει.", "st": "9.1"}, {"sp": "SEC", "t": "X · 13–16", "st": "10"}, {"sp": "N", "t": "<span class=\"lemma\">Εἶτα δικαιοσύνην ἄσκει ἔργῳ τε λόγῳ τε·<br>μηδ' ἀλογίστως σαυτὸν ἔχειν περὶ μηδὲν ἔθιζε·<br>ἀλλὰ γνῶθι μὲν ὡς θανέειν πέπρωται ἅπασι·<br>χρήματα δ' ἄλλοτε μὲν κτᾶσθαι φίλει, ἄλλοτ' ὀλέσσαι.<\/span>", "st": "10.0"}, {"sp": "N", "t": "Ὁ ἑαυτὸν αἰσχυνόμενος φύλαξ ἑαυτοῦ γίνεται μηδαμοῦ κακίᾳ περιπεσεῖν. Κακίας δὲ εἴδη πλείονα. Κατὰ μὲν τὸ λογικόν, ἀφροσύνη· κατὰ δὲ τὸ θυμικόν, δειλία· κατὰ δὲ τὸ ἐπιθυμητικόν, φιληδονία καὶ φιλοχρηματία· κατὰ δὲ πάσας ὁμοῦ τὰς δυνάμεις, ἀδικία. Τετράδος οὖν ἀρετῶν ἐδέησεν ἡμῖν πρὸς τὴν τῶν τοιούτων κακῶν ἀποτροπήν· φρονήσεως μέν, περὶ τὸ λογιζόμενον· ἀνδρείας δέ, περὶ τὸ θυμούμενον· σωφροσύνης δέ, περὶ τὸ ἐπιθυμητικόν· δικαιοσύνης δέ, περὶ πάσας ὁμοῦ τὰς δυνάμεις, τελειοτάτης οὔσης πασῶν ἀρετῶν καὶ περιεκτικῆς τῶν ἄλλων, ὡς οἰκείων μερῶν. Διὸ καὶ ταύτης πρώτης ἐμνημόνευσεν ὁ λόγος· εἶτα φρονήσεως, καὶ ἐφεξῆς τῶν ἀπὸ τῆς φρονήσεως ἀπογεννωμένων ἀρίστων ἐπιτηδευμάτων, καὶ εἰς τὴν τῆς δικαιοσύνης ὁλότητα συντελούντων. Ὁ γὰρ ὀρθῷ λογισμῷ χρώμενος, ἐν μὲν τοῖς δεινοῖς τὴν ἀνδρείαν σύμμαχον κτᾶται· ἐν δὲ τοῖς ἡδέσι τὴν σωφροσύνην, ἐν πᾶσι δὲ ὁμοῦ τὴν δικαιοσύνην. Καὶ οὕτως ἀρχὴ μὲν τῶν ἀρετῶν ἡ φρόνησις εὑρίσκεται· πέρας δέ, ἡ δικαιοσύνη· διὰ μέσου δέ, ἡ ἀνδρεία καὶ ἡ σωφροσύνη. Ἡ γὰρ πάντα ἐκλογιζομένη δύναμις, καὶ τὸ ἑκάστου πρόσφορον ταῖς πράξεσιν ἀεὶ ζητοῦσα, ἵν' εὐλόγως ἕκαστα διατεθείη, ἡ τῆς φρονήσεώς ἐστιν ἕξις· ἀρίστη διάθεσις οὖσα τῆς λογικῆς ἡμῶν οὐσίας, ἀφ' ἧς καὶ ταῖς ἄλλαις δυνάμεσιν ἡ εὐκοσμία παραγίγνεται, ὡς ἀνδρίζεσθαι μὲν τὸν θυμόν, σωφρονεῖν δὲ τὴν ἐπιθυμίαν, καὶ τὴν δικαιοσύνην τῆς ἀναλογίας ἔχεσθαι, καὶ ταύτῃ κοσμεῖσθαι τὸν θνητὸν ἡμῶν ἄνθρωπον ἐκ περιουσίας τῆς ἐνούσης ἀρετῆς τῷ ἀθανάτῳ ἀνθρώπῳ. Προηγουμένως γὰρ αἱ ἀρεταὶ ἀπὸ νοῦ εἰς ψυχὴν λογικὴν ἐλλάμπονται, καὶ ταύτης εἰσὶν οἰκεῖον εἶδος, καὶ τελειότης, καὶ εὐζωΐα. Εἰς δὲ τὴν ἀλογίαν καὶ τὸ θνητὸν σῶμα μετουσία τις τῶν ἀρετῶν ἔρχεται, ὅπως ἂν καὶ τὰ συμπεφυκότα τῇ λογικῇ οὐσίᾳ εὐσχημοσύνης καὶ μετριότητος πληρωθῇ.", "st": "10.1"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Τὸ δὲ τῶν θείων ἀγαθῶν ἡγεμονοῦν ἡ φρόνησις αὕτη, καλῶς ἐνιδρυθεῖσα τῇ λογικῇ ψυχῇ, δίδωσι περὶ πάντων εὖ βουλεύεσθαι, καὶ τὸν μὲν θάνατον ἀνδρείως φέρειν, τὴν δὲ ἀποβολὴν τῶν χρημάτων πράως καὶ ἐμμελῶς. Πάσας γὰρ τὰς μεταβολὰς τῆς θνητῆς φύσεως, καὶ τῆς ἑπομένης αὐτῇ τύχης, σωφρόνως καὶ ἀνεκπλήκτως ὑπομένειν ἡ φρόνησις δύναται. Τὴν γὰρ φύσιν ἐκλελόγισται τῶν πραγμάτων, καὶ οἶδεν, ὡς ἀνάγκη τὸ συμπλασθὲν ἐκ γῆς καὶ ὕδατος διαλυθῆναι πάλιν εἰς αὐτά· καὶ πρὸς τὴν ἀνάγκην οὐκ ἀγριαίνεται· οὐδὲ ἀπρονόητα εἶναι τίθεται τὰ καθ' ἡμᾶς, ἐὰν τὸ θνητὸν ἀποθνήσκῃ. Γινώσκει γὰρ ὡς θανέειν πέπρωται ἅπασι, καί τις ὡρισμένος ἐστὶ χρόνος πρὸς διαμονὴν τοῖς θνητοῖς ἡμῶν σώμασιν, οὗ ἐνστάντος, οὐ δεῖ χαλεπαίνειν, ἀλλ' ὡς νόμῳ θείῳ ἑκόντας ἕπεσθαι. Τοῦτο γὰρ νῦν ἡ πεπρωμένη δηλοῖ, ὅροις τισὶν ἀναγκαίοις πεπερατῶσθαι τὴν θνητὴν ἡμῶν ζωήν· φρονήσεως δὲ ἴδιον εἶναι τοῖς τῶν κρειττόνων ἕπεσθαι δόγμασιν, οὐ τὸ μὴ ἀποθανεῖν, ἀλλὰ τὸ εὖ ἀποθανεῖν, ζητούσης. Ὁμοίως δὲ καὶ τὴν τῶν χρημάτων φύσιν οὐκ ἀγνοεῖ, ὅτι νῦν μὲν ἦλθε, νῦν δὲ ἀπῆλθε, κατά τινας ὡρισμένας αἰτίας, αἷς ἀντιτείνειν ἀβέλτερον. Τῶν γὰρ οὐκ ἐφ' ἡμῖν τῆς κτήσεως ἡμεῖς οὐ κύριοι. Οὐκ ἐφ' ἡμῖν δὲ τὸ σῶμα καὶ τὰ χρήματα· καὶ ἁπλῶς, ὅσα τῆς λογικῆς ἡμῶν οὐσίας ἔξω κεῖται, οὔτε τὴν ἀρχὴν κτήσασθαι ἐφ' ἡμῖν, οὔτε φυλάξαι ἐφ' ὅσον βουλόμεθα· τὸ δέ, προσγινομένων καὶ ἀπογινομένων αὐτῶν, μετὰ ἀρετῆς ἀποδέχεσθαι αὐτά, καὶ ἀποτίθεσθαι, τοῦτο ἦν ἐφ' ἡμῖν, καὶ τῆς λογικῆς οὐσίας ἴδιον, ἂν μὴ ἀλογίστως ἔχειν περὶ τῶν συμβαινόντων ἑαυτὴν ἐθίζῃ, ἀλλὰ τοῖς θείοις ἕπηται μέτροις, οἷς πάντα τὰ περὶ ἡμᾶς ὥρισται. Ἐνταῦθα οὖν τὸ ἐφ' ἡμῖν δύναμιν ἔχει μεγίστην, ἐν τῷ εὖ κρῖναι περὶ τῶν οὐκ ἐφ' ἡμῖν, καὶ μὴ τῇ τούτων προσπαθείᾳ τὴν τοῦ αὐτεξουσίου ἀρετὴν προσαπολέσαι. Τί οὖν ἡ ἔμφρων κρίσις λέγει; Παρόντι μὲν τῷ σώματι καὶ τῷ πλούτῳ καλῶς χρῆσθαι, καὶ πρὸς ὑπηρεσίαν ἀρετῆς· ἀπιόντων δέ, εἰδέναι τὸ δέον, καὶ πρὸς ταῖς ἄλλαις ἀρεταῖς ἀλυπίαν κερδαίνειν. Οὕτω γὰρ καὶ ἡ πρὸς θεοὺς εὐσέβεια τηρηθήσεται, καὶ τὰ τῆς δικαιοσύνης μέτρα, εἰ τὸ λογικὸν ἐκμάθοι ταῖς περιστάσεσιν εὖ καὶ καλῶς χρῆσθαι, καὶ τοὺς τῆς φρονήσεως ὅρους ἀντιτιθέναι τοῖς δοκοῦσιν ὡς ἔτυχε καὶ ἀτάκτως συμβαίνειν. Ἄλλως γὰρ οὐκ ἂν ἀρετὴ φυλαχθείη, ἂν μὴ ὀρθοδοξία τις ἐνυπάρχῃ τῇ λογικῇ οὐσίᾳ. Οὔτε γὰρ τοῖς κρείττοσιν ἕπεσθαι δύναται, ὡς κρείττοσιν, ἀλλὰ ὡς ὑπὸ τυράννων βιαζόμενος διατεθήσεται· οὔτε τῶν συζώντων λόγον τινὰ ποιήσεται, οὔτε σώματος, ἢ χρημάτων τὴν ἀρίστην οἰκονομίαν ἐξευρήσει, ἀλογίστως ἔχειν ἑαυτὸν ἐθίσας. Ὅρα γὰρ ὅτι οἱ ἐξ ἅπαντος φεύγοντες τὸν θάνατον, ἢ τὰ χρήματα τηρεῖν ἐπιθυμοῦντες, πολλαῖς ἐξ ἀνάγκης ἀδικίαις χρήσονται καὶ βλασφημίαις, ἀρώμενοι μὲν κατὰ θεῶν ἀνόσια, καὶ μὴ προνοεῖσθαι φάσκοντες, ἐπειδὰν περιπέσωσιν οἷς ἀνοήτως ἔφευγον, ἀφειδῶς δὲ τοὺς ἄλλους ἀδικοῦντες, καὶ τὰ πάντων ἀθροίζειν πειρώμενοι πρὸς τὸ ἑαυτοῖς λυσιτελές, ὡς οἴονται. Καὶ οὕτως ἐκφανὴς ἡ τῆς ψευδοδοξίας ἐν αὐτοῖς γίνεται βλάβη, ὡς τὰ μέγιστα τῶν κακῶν ἐκβλαστάνειν· ἀδικίαν μὲν πρὸς τοὺς ὁμοίους, ἀνοσιότητα δὲ πρὸς τοὺς κρείττονας. Ὧν καθαρεύσειεν ἂν ὁ τοῖς προκειμένοις στίχοις πειθόμενος, ὁ τῇ εὐλογίστῳ κρίσει τὸν θάνατον γενναίως ὑπομένων, καὶ τὴν τῶν χρημάτων ἀποβολὴν οὐκ ἀφόρητον ἡγούμενος. Ἐξ ὧν καὶ πρὸς δικαιοσύνην ἀφορμὰς λαμβάνει, ὡς δέοι τῶν ἀλλοτρίων ἀπέχεσθαι, καὶ βλάπτειν μηδένα, μηδὲ ὠφέλειαν ἑαυτοῦ τὰς τῶν ἄλλων ποιεῖσθαι συμφοράς.<br>Τούτων δὲ οὐδὲν τηρῆσαι δυνατὸς ἔσται ὁ θνητὴν ὑπολαμβάνων εἶναι τὴν ἑαυτοῦ ψυχήν, καὶ ἀλογίστως ἔχειν ἑαυτὸν ἐθίσας, τί μέν ἐστι τὸ ἀποθνῆσκον ἡμῶν μηδαμῶς λογιζόμενος, καὶ τὸ τῶν χρημάτων δεόμενον, τί δὲ τὸ ἀσκοῦν τὴν ἀρετήν, καὶ τὸ ἐκ ταύτης ὠφελούμενον. Μόνη γὰρ ἡ τούτων διάκρισις προθυμίαν εἰς ἀρετῆς ἄσκησιν ἂν παράσχοι, καὶ πρὸς τὴν τῶν καλῶν κτῆσιν ἐπεγείρειεν ἡ ἐκ τοῦ γνῶθι σεαυτὸν καὶ αἰσχύνεο σαυτὸν ἔνθεος ὁρμή. Πρὸς γὰρ τὴν ἡμετέραν ἀξίαν καὶ τὰ τῶν ἄλλων καθήκοντα παραμετρεῖσθαι δεῖ ἐν ἔργοις τε καὶ λόγοις. Ἡ δὲ τῶν καθηκόντων τήρησις ἀπαράβατος δικαιοσύνη ἂν εἴη· διὸ καὶ προτέτακται τῶν ἄλλων ἀρετῶν, ἵνα τῶν καθηκόντων γένηται μέτρον. Δικαιοσύνην, γάρ φησιν, ἄσκει ἔργῳ τε λόγῳ τε. Οὐκ οὖν οὐδὲν βλάσφημον ἐρεῖς ἐν ἀπωλείαις χρημάτων, ἢ νόσων ἀλγηδόσιν, ἵνα μὴ ἀδικῇς ἐν λόγῳ· ἀλλ' οὐδὲ τὰ τῶν πλησίον ἁρπάσεις, οὐδὲ μηχανήσῃ δυστυχίας ἀνθρώποις, ἵνα μὴ ἀδικῇς ἐν ἔργῳ. Δικαιοσύνης γὰρ τὴν ψυχὴν φρουρούσης, τὰ προσήκοντα ἂν πράττοιμεν καὶ περὶ ἀνθρώπους, καὶ περὶ ἡμᾶς αὐτούς.<\/span><\/span>", "st": "10.2"}, {"sp": "N", "t": "Τῆς δὲ δικαιοσύνης τὸ ἄριστον μέτρον ἐστὶν ἡ φρόνησις· ὅθεν τῷ, δικαιοσύνην ἄσκει, ἐπήγαγε, μηδ' ἀλογίστως σαυτὸν ἔχειν περὶ μηδὲν ἔθιζε· ὡς μὴ δυναμένης ὑποστῆναι δικαιοσύνης ἄνευ φρονήσεως. Τοῦτο γάρ ἐστιν ὄντως δίκαιον, ὃ ἡ τελεία φρόνησις ὁρίζει. Αὕτη δ' ἂν εἴη ἡ περὶ μηδὲν ἀλογίστως ἔχουσα, ἀλλ' ἐπεσκεμμένως μὲν περὶ τοῦ σώματος ἔχουσα, ἐπεσκεμμένως δὲ καὶ περὶ τῶν εἰς τὴν τούτου χρείαν συντελούντων· πάντα δὲ ἀτιμότερα ἀρετῆς τιθεμένη, καὶ μεγίστην ὠφέλειαν τὴν ἀρίστην διάθεσιν τῆς λογικῆς ψυχῆς, ἀφ' ἧς καὶ τὰ ἄλλα κοσμεῖται κατὰ δύναμιν. Τοιοῦτος μὲν τῶν προκειμένων ἐπῶν ὁ σκοπός, τὴν τετράδα τῶν πρακτικῶν ἀρετῶν ἀναφῆναι καὶ παραδοῦναι τοῖς ἀκροαταῖς, μετὰ τῆς ἀγρύπνου τηρήσεως, καὶ παραφυλακῆς τῆς ἐν λόγοις καὶ ἔργοις πρεπούσης. Τὸ μὲν γὰρ φρόνησιν, τὸ δὲ ἀνδρείαν, τὸ δὲ σωφροσύνην, παραδίδωσι· τὸ δὲ προηγούμενον αὐτῶν τὴν ἐπὶ πάσαις ταῖς ἄλλαις ἀρεταῖς κοινῶς ἐπιθεωρουμένην δικαιοσύνην ἀσκεῖσθαι παραινεῖ· τὸ δέ, χρήματα δ' ἄλλοτε μὲν κτᾶσθαι φίλει, ἄλλοτ' ὀλέσσαι, παρίστησιν, ὅτι τῇ σωφρονικῇ διαθέσει καὶ ἡ ἐλευθεριότης παρέπεται, ἀρετὴ οὖσα περὶ χρημάτων πρόσοδον καὶ δαπάνην. Τὸ γὰρ μόνον τότε αὐτὰ κτᾶσθαι, καὶ ἀποκτᾶσθαι, ὅτε δίδωσιν ὁ λόγος, μικρολογίας καὶ ἀσωτίας προαναιρεῖ τὰς ἀφορμάς.", "st": "10.3"}, {"sp": "N", "t": "Ταῦτα δὲ πάντα, ὡς ἀπὸ πηγῆς καὶ ἀρχῆς πρώτης, τοῦ ἑαυτὸν αἰσχύνεσθαι προάγεται. Τοῦτο δὲ τὸ παράγγελμα προείληφεν ἐν ἑαυτῷ τὸ Σαυτὸν γνῶθι, ὃ πασῶν μὲν σπουδαίων πράξεων, πασῶν δὲ θεωρητικῶν γνώσεων προϋποκεῖσθαι δεῖ. Ἐπεὶ πόθεν εἰσόμεθα, ὅτι προσήκει ἡμῖν μετριάσαι τῶν παθῶν, καὶ γνῶναι τὰ ὄντα; Ἀπορεῖται γὰρ περὶ αὐτῶν· πρῶτον μέν, εἰ δυνατὰ ἀνθρώποις ταῦτα· ἔπειτα, εἰ ὠφέλιμα τοῖς ἔχουσι γίνεται. Φαίνεται γὰρ πᾶν τοὐναντίον ἐλαττούμενος ἐν τοῖς κατὰ τὸν βίον ὁ σπουδαῖος, τῷ μὴ λαμβάνειν ἀδίκως ὅθεν οὐ δεῖ, καὶ τῷ ἀναλίσκειν δικαίως εἰς ἃ δεῖ· καὶ περὶ τὸ σῶμα παντὸς μᾶλλον εὐεπιχειρήτως διάκειται, μήτε ἀρχὴν αὐτὸς ἐπιτηδεύων, μήτε ἀνελευθέρως θεραπεύων τοὺς ἄρχοντας. Ὥστε, εἰ μή τις ἄλλη οὐσία ἐν ἡμῖν εἴη ἀπὸ τῆς ἀρετῆς ὠφελουμένη, σχολῇ γ' ἂν πλοῦτον ἢ δυναστείαν δι' αὐτὴν προησοίμεθα. Ὅθεν καὶ οἱ θνητὴν οἰόμενοι τὴν ψυχὴν περὶ τοῦ μὴ προΐεσθαι τὴν ἀρετὴν κομψεύονται μᾶλλον, ἢ ἀληθεύουσιν. Εἰ γὰρ μὴ εἴη τι ὑπομένον ἡμῶν μετὰ θάνατον, καὶ τοῦτο φύσιν ἔχον ἀληθείᾳ καὶ ἀρετῇ κοσμεῖσθαι, (οἷον δή φαμεν εἶναι τὴν λογικὴν ψυχήν) οὐκ ἂν ἔφεσις ἡμῖν καθαρὰ γένοιτο τῶν καλῶν. Προαναιρεῖται γὰρ ἡ ὑποψία τῆς φθορᾶς τὴν περὶ ταῦτα σπουδήν, καὶ πρὸς ἀπολαύσεις ἄγει σωματικάς, ὁποῖαί ποτ' ἂν ὦσιν αὗται, καὶ πόθεν ἂν πορίζεσθαι δύνωνται. Πῶς γὰρ δόξει ἔμφρονος εἶναι, κατ' αὐτούς, ἢ μετρίως καθεστηκότος, μὴ πάντα χαρίζεσθαι τῷ σώματι, δι' ὃ καὶ ἡ τῆς ψυχῆς ὑπόστασις σώζεται, οὐκ οὔσης μὲν καθ' αὑτήν, ἐπιγινομένης δὲ τῇ ποιᾷ διαπλάσει τοῦ σώματος; Πῶς δὲ προησόμεθα δι' ἀρετὴν τὸ σῶμα, μέλλοντες καὶ τὴν ψυχὴν αὐτὴν ἅμα τῷ σώματι διαφθείρειν, ὥστε μηδαμοῦ εἶναι τὴν ἀρετήν, ἧς ἐφέσει τὸν θάνατον ὑπεμείναμεν; Ἀλλὰ περὶ μὲν τούτων ἱκανῶς τοῖς θείοις ἀνδράσιν ἀποδέδεικται, ὅτι τε ἀθάνατος ἡ ψυχή, καὶ ὅτι διὰ μόνης ἀρετῆς κοσμεῖσθαι πέφυκε.", "st": "10.4"}, {"sp": "N", "t": "Νῦν δὲ τὸ παρὸν ἐπισφραγισάμενοι δόγμα, ἐπὶ τὰ ἑξῆς μεταβαίνωμεν, τοσοῦτον τοῖς προειρημένοις ἐπειπόντες, ὅτι ὥσπερ τῇ ἀγνοίᾳ τῆς οὐσίας ἡμῶν πᾶσα ἐπεισρεῖ κακία, οὕτω τῇ ἑαυτῶν γνώσει, καὶ ἀπαξιώσει τῶν μὴ πρεπόντων τῇ λογικῇ φύσει, ἡ τῶν καθηκόντων ἀπαραλόγιστος τήρησις εὑρίσκεται πανταχοῦ· τοῦτο δὲ τῶν κατὰ μέρος ἀρετῶν γίνεται μέτρον. Ὡς γὰρ πρὸς κανόνα τὴν οὐσίαν ἡμῶν ἀποβλέποντες, τὸ δέον ἐν πᾶσιν εὑρίσκομεν, κατὰ τὸν ὀρθὸν λόγον συμφώνως τῇ ἑαυτῶν οὐσίᾳ διαζῶντες. Πᾶν γὰρ ὃ ἀμείνονα τὴν ψυχὴν ποιεῖ, καὶ πρὸς τὴν φύσει πρέπουσαν εὐζωΐαν αὐτὴν ἀνάγει, τοῦτο ὄντως ἀρετὴ καὶ φιλοσοφίας νόμος· τὰ δὲ μόνον πρὸς ἀνθρωπίνην εὐσχημοσύνην τείνοντα, δουλοπρεπῆ ἐστι σοφίσματα καὶ σκιαγραφία τῶν καλῶν, τὸν παρὰ τῶν πολλῶν ἔπαινον θηρωμένη, καὶ τοῦ δοκεῖν μόνον, οὐ τοῦ εἶναι, ἀγαθὸν τὴν πᾶσαν ποιουμένη φροντίδα. Καὶ ταῦτα μὲν περὶ τούτων.", "st": "10.5"}, {"sp": "N", "t": "Τοῖς δὲ ὀρθοῖς λογισμοῖς ἐξ ἀνάγκης ἕπεται καὶ περὶ τῶν δοκούντων ἀτάκτως κατὰ τὸν βίον συμβαίνειν μὴ ἀλογίστως ἔχειν, ἀλλ' εὖ καὶ γενναίως ἀπολελογίσθαι τὰς τούτων αἰτίας, καὶ φέρειν αὐτὰ μηδὲν ἐγκαλοῦντας τοῖς ἐπιμεληταῖς ἡμῶν, οἳ πρὸς ἀξίαν ἀπονέμοντες ἑκάστῳ τὰ προσήκοντα, οὐ τῶν ἴσων ἠξίωσαν ἅπαντας τοὺς μὴ ὁμοίως προβεβιωκότας. Πῶς γὰρ ἂν προνοίας μὲν οὔσης, καὶ τῆς ψυχῆς ἡμῶν ἀφθάρτου μὲν κατ' οὐσίαν, προαιρέσει δὲ αὐτοκινήτῳ πρὸς ἀρετὴν ἢ κακίαν ὁρμώσης, ἐνῆν τὰ ἴσα τοῖς μὴ ἴσοις τοὺς τοῦ πρὸς ἀξίαν φύλακας νόμου ἀποδιδόναι, ἀλλὰ μὴ τὴν προσήκουσαν ἀπονέμειν ἑκάστῳ τύχην, ἣν καὶ προϊὼν εἰς γένεσιν ὁ ἄνθρωπος κληροῦσθαι λέγεται; Εἰ οὖν μὴ μῦθος τὸ εἶναι πρόνοιαν, ἀπονέμουσαν ἑκάστῳ τὰ πρέποντα, καὶ τὴν ψυχὴν ἡμῶν ἀθάνατον εἶναι, δῆλον, ὡς μεταστῆσαι δεῖ τὴν αἰτίαν τῶν ἀλγεινῶν ἀπὸ τοῦ διοικοῦντος ἐφ' ἡμᾶς αὐτούς, ἐξ οὗ καὶ τὸ ἰᾶσθαι τὰ δυσχερῆ δύνασθαι δώσει ὁ λόγος. Ἐν ἑαυτοῖς γὰρ εὑρόντες τὰς αἰτίας τῆς τοσαύτης ἀνωμαλίας, πρῶτον μὲν τῷ ὀρθῷ τῆς κρίσεως ἐπελαφρυνοῦμεν τῶν συμβαινόντων τὸ μοχθηρόν· ἔπειτα ταῖς ἱεραῖς μεθόδοις καὶ ταῖς ὀρθαῖς νουθετήσεσι μεθαρμόζοντες τὴν ψυχὴν πρὸς τὸ ἄμεινον, παντελῶς ἑαυτοὺς τῶν ἀλγεινῶν ἐλευθερώσομεν. Τὸ δὲ πάσχοντα κακῶς μηδ' αἰσθάνεσθαι τὰς αἰτίας, μηδὲ καταμαντεύεσθαι τοῦ εἰκότως συμβαίνοντος, ἑαυτὸν ἦν ἐθίσαντος ἀλογίστως ἔχειν περὶ παντός, ὃ νῦν ἀπηγόρευσεν ὁ λόγος. Ἀνάγκη γὰρ τὸν ἀζητήτως ἔχοντα τῆς ἀληθοῦς αἰτίας ἐπὶ τὴν κρείττονα οὐσίαν μεταφέρειν τὸ ἔγκλημα, ἢ ὅτι οὐκ ἔστι παντελῶς, ἢ ὅτι οὐκ ἐπιμελεῖται ἡμῶν ὀρθῶς. Τὰ δὲ τοιαῦτα δοξάσματα οὐ μόνον τὰ ἐκ προβιοτῆς κακὰ ἐπιτείνει, ἀλλὰ καὶ εἰς πᾶσαν πονηρίαν τὴν ψυχὴν ἐπεγείρει, καὶ τῆς αὐτεξουσίου θεραπείας αὐτὴν ἀποστερεῖ, τῷ προστιθέναι λανθανούσας αἰτίας τῶν νῦν δυσχεραινομένων. Πῶς δὲ δεῖ περὶ τούτων φιλοσοφεῖν, ἐπάκουσον αὐτῶν τῶν ἐπῶν.", "st": "10.6"}, {"sp": "SEC", "t": "XI · 17–20", "st": "11"}, {"sp": "N", "t": "<span class=\"lemma\">Ὅσσα τε δαιμονίῃσι τύχαις βροτοὶ ἄλγε' ἔχουσιν,<br>ὧν ἂν μοῖραν ἔχῃς πράως φέρε, μηδ' ἀγανάκτει.<br>ἰᾶσθαι δὲ πρέπει, καθόσον δύνῃ· ὧδε δὲ φράζευ·<br>οὐ πάνυ τοῖς ἀγαθοῖς τούτων πολὺ μοῖρα δίδωσι.<\/span>", "st": "11.0"}, {"sp": "N", "t": "Πρὸ τῆς ἄλλης ἐξηγήσεως ἐκεῖνο προειπεῖν δεῖ, ὅτι ἄλγεα νῦν λέγει τὰ ἐπίπονα, καὶ τραχυτέραν ἡμῖν τὴν ὁδὸν τοῦ βίου παρασκευάζοντα· οἷον νόσον, πενίαν, φιλτάτων ἀποβολήν, ἀδοξίαν ἐν πόλει. Ταῦτα γὰρ χαλεπὰ μέν ἐστι, καὶ δυσδιάθετα κατὰ τὸν βίον· οὐ μὴν ὄντως κακά, οὐδὲ αὐτῇ τῇ ψυχῇ βλαβερὰ τυγχάνει, ἐὰν μὴ αὐτὴ ἐθέλῃ διά τι τούτων εἰς κακίαν ἀποκλῖναι· ὃ καὶ ἐπὶ τῶν ἀγαθῶν δοκούντων πάθοι ἄν, μὴ βουληθεῖσα καλῶς αὐτὰ μεταχειρίζεσθαι· οἷον ὑγίειαν καὶ πλοῦτον καὶ δυναστείαν. Ἔστι γὰρ καὶ ἐν τούτοις κακυνθῆναι, καὶ ἐν τοῖς ἐναντίοις ἀρετὴν κτήσασθαι. Τὰ δὲ ὄντως κακά, τὰ ἐκ προαιρέσεώς ἐστιν ἁμαρτανόμενα, οἷς συνεισελθεῖν ἀρετὴν φύσιν οὐκ ἔχει. Ταῦτα δέ ἐστιν ἀδικία, καὶ ἀκολασία, καὶ πάντα ὅσα τὴν τοῦ καλοῦ σύζευξιν οὐκ ἐπιδέχεται. Οὐ γάρ ἐστιν οὐδενὶ τῶν τοιούτων τὸ καλῶς ἐπιφθέγγεσθαι· οἷον, ἀδικεῖ καλῶς, ἀκολασταίνει καλῶς, ὥσπερ ἐπὶ τῶν ἐκτὸς κακῶν λέγομεν, νοσεῖ καλῶς, πένεται καλῶς· ὅταν εὖ καὶ κατὰ τὸν ὀρθὸν λόγον τὰ τοιαῦτα φέρῃ ὁ ἄνθρωπος. Ταῖς δὲ ψυχικαῖς πονηρίαις οὐκ ἐπιφέρεται τὸ καλῶς, διότι ἀποστροφαί εἰσι καὶ ἀποτεύγματα τοῦ ὀρθοῦ λόγου, ὃν φύσει ἐνόντα, καὶ ἐγγεγραμμένον αὐτῇ, παρορᾷ ἡ ἀνθρώπου ψυχὴ ὑπὸ τῆς προσπαθείας ἀποτυφλουμένη.", "st": "11.1"}, {"sp": "N", "t": "Τεκμήριον δὲ τοῦ ἐνεῖναι τὸν ὀρθὸν λόγον τοῖς ἀνθρώποις, τὸ καὶ τὸν ἄδικον, ἐν οἷς μηδὲν αὐτῷ διαφέρει, κρίνειν δικαίως, καὶ τὸν ἀκόλαστον, σωφρονικῶς· καὶ ὅλως, τὸν κακὸν ὀρθαῖς ἐπιβολαῖς χρῆσθαι, ἐν οἷς ἀπροσπαθής ἐστι. Διὸ καὶ μεθίστασθαι δύναται ὁ φαῦλος εἰς ἀρετὴν καταγνώσει τῆς προτέρας κακίας. Οὐ μὴν διὰ τοῦτο ἐνυπάρχειν δεῖ καὶ τὸν μὴ ὀρθὸν λόγον, ἵνα ἀρχὴ τῶν κακιῶν οὗτος γένηται, ὥσπερ ἐκεῖνος τῶν ἀρετῶν. Ἀρκεῖ γὰρ παρὼν ὁ ὀρθὸς λόγος, ὥσπερ νόμος ἐν πόλει, τά τε κατ' αὐτὸν πραττόμενα καὶ τὰ παρ' αὐτὸν διορίζειν, καὶ τὰ μὲν ἀποδέχεσθαι, τὰ δὲ σωφρονίζειν. Καὶ οὐδὲν δεῖ κακῶν ἀρχῆς, οὔτε ἐνυποκειμένης οὔτε ἔξωθεν κακοποιὸν αἰτίαν ἐνδιδούσης· ἀγαθῶν δὲ δεῖ ἀρχῆς μάλιστα καὶ μόνης, καὶ τῆς μὲν κεχωρισμένης τῶν λογικῶν οὐσιῶν, οἷός ἐστιν ὁ θεός· τῆς δὲ ἐνυπαρχούσης αὐταῖς, καὶ τῇ κατ' οὐσίαν ἐπαφῇ κυβερνώσης, οἷός ἐστιν ὁ ὀρθὸς λόγος.", "st": "11.2"}, {"sp": "N", "t": "Τοιαύτη μὲν ἡ τῶν κακῶν διάκρισις· ὧν οὐ τὰ προαιρετικά φησιν ἐκ τῆς δαιμονίας τύχης τοῖς ἀνθρώποις ἀπονέμεσθαι, ἀλλὰ τὰ περιστατικά, ἃ νῦν μὲν ἐν τοῖς οὐκ ἐφ' ἡμῖν κεῖται, πάλαι δὲ προαιρετικαῖς ἁμαρτίαις ἐπηκολούθησεν, ἀλγεινὰ μὲν ὄντα, ὡς ἔφαμεν, τὸν δὲ παρὰ τῆς ἀρετῆς κόσμον ἐπιδεχόμενα. Καὶ γὰρ πενίαν ἐκόσμησε σώφρων δίαιτα· καὶ ταπεινότητα γένους ἐπηνωρθώσατο φρόνησις· καὶ παίδων ἀποβολὴν πράως ἤνεγκεν ὁ δίκαιος βίος, ὁ δυνάμενος εἰπεῖν, Τέθνηκε τὸ παιδίον; οὐκοῦν ἀπεδόθη· καὶ, ᾜδειν θνητὸν γεγεννηκώς. Ὁμοίως δὲ καὶ τὰ ἄλλα πάντα, τῷ τῆς ἀρετῆς κάλλει περιβληθέντα, γίνεται εὐσχημονέστερα.", "st": "11.3"}, {"sp": "N", "t": "Ἑξῆς δὲ ζητεῖ ὁ λόγος τίνες αἱ δαιμόνιαι τύχαι, καθ' ἃς οἱ βροτοὶ τὰς ἐκτὸς δυσχερείας ἔχουσιν. Εἰ μὲν γὰρ προηγουμένως ἡ θεία κρίσις δίδωσι τῷδε μὲν πλοῦτον, ἑτέρῳ δὲ πενίαν, δαιμονίαν ἔδει ταύτην προαίρεσιν καλεῖν, καὶ μὴ τύχην. Εἰ δὲ μηδὲν ἐπιστατεῖ ταῖς τῶν τοιούτων λήξεσιν, ἀλλ' ὡς ἔτυχε καὶ αὐτομάτως συμπίπτει, τὸν μὲν εὐτυχῆ εἶναι, ὥς φασι, τὸν δὲ δυστυχῆ, τύχην ἔδει ταύτην καλεῖν, καὶ μὴ δαιμονίαν τύχην. Εἰ δὲ πρὸς τὴν ἀξίαν ἑκάστῳ τὰ προσήκοντα ἀπονέμει ὁ ἐπιτροπεύων ἡμῶν θεός, καὶ τοῦ μὲν εἶναι τοιούσδε ἢ τοιούσδε ἡμᾶς οὐκ ἔστιν αἴτιος, τοῦ δὲ τὰς ἀμοιβὰς ἀποδοῦναι κατὰ τοὺς θεσμοὺς τῆς δίκης μόνος ἐστὶ κύριος, εἰκότως συνάψας εἶπε δαιμονίας τύχας τὰς τῆς κρίσεως ἀποφάνσεις· ᾗ μὲν θεῖον καὶ νοερόν ἐστι τὸ κρῖνον, δαιμονίας καὶ ἐπιστημονικὰς αὐτὰς προσειπών· ᾗ δὲ οἰκείᾳ προαιρέσει κακύνεται τὸ κρινόμενον, καὶ διὰ τοῦτο γίνεται τῶν δυσχερῶν τούτων ἄξιον, προσθεὶς τὸ τύχας, ὅτι οὐ προηγουμένως τόνδε τινὰ κολάσαι ἢ τιμῆσαι πρόκειται τῷ θεῷ, ἀλλ' ἀεὶ τὸν τοιόνδε ἢ τοιόνδε γενόμενον· τούτου δὲ τὴν αἰτίαν ἐν ἡμῖν κεῖσθαι. Τὴν μὲν οὖν ἐπιπλοκὴν τῆς ἡμετέρας προαιρέσεως καὶ τῆς ἐκείνου κρίσεως τύχην ἀπογεννᾶν, ὥστε εἶναι τὸ ὅλον τοῦτο, δαιμονίαν τύχην, τὴν ἐπὶ τοῖς ἡμαρτημένοις θείαν ψῆφον· καὶ συνεισάγειν οὕτω τὴν τῶν ὀνομάτων τεχνικὴν εὕρεσιν, τήν τε θείαν ἐπιστασίαν, καὶ τὸ αὐτεξούσιον τῆς ψυχῆς, καὶ ἀθάνατον· καὶ μήτε καθ' εἱμαρμένην ἢ πρόνοιαν πάντα γίνεσθαι, μήτε ὡς ἔτυχε, καὶ ἀπὸ ταὐτομάτου, μήτε κατὰ τὸ αὐτοπροαίρετον ἡμῖν τὸν βίον διατίθεσθαι πάντα. Ἀλλ' ὅσα μὲν ἐν τοῖς ἐφ' ἡμῖν ἁμαρτάνομεν, ταῦτα εἰς προαίρεσιν ἀναφέρεσθαι· ὅσα δὲ ἐπὶ τοῖς ἡμαρτημένοις κατὰ τοὺς τῆς δίκης ἕπεται νόμους, εἰς εἱμαρμένην· τὰ δὲ προηγουμένως παρὰ τοῦ θεοῦ ἐνδιδόμενα ἀγαθά, εἰς πρόνοιαν· εἰς δὲ τὸ εἰκῆ, καὶ ὡς ἔτυχεν, οὐδὲν τῶν ὄντων ἀναφέρειν τὴν αἰτίαν· ἀλλ' οὐδὲ τῶν γινομένων· εἰ μὴ ἄρα κατὰ συμβεβηκός, καὶ κατ' ἐμπλοκὴν τῶν ἀπὸ προνοίας καὶ εἱμαρμένης καὶ προαιρέσεως προηγουμένως ἐνεργουμένων, ἐπακολουθήσει τὸ ὡς ἔτυχε τοῖς πρωτουργοῖς αἰτίοις.", "st": "11.4"}, {"sp": "N", "t": "Οἷον φέρε, ὁ δικαστὴς τὸν φονέα κολάζειν βούλεται, καὶ οὐ τόνδε τὸν ἄνθρωπον· κολάζει δὲ καὶ τοῦτον, ὃν οὐκ ἐβούλετο, ὅταν αὐτὸς ἑαυτὸν εἰς τὴν τοῦ φονέως ἐναρμόσῃ τάξιν. Καὶ γίνεται προηγουμένη μὲν ἡ κατὰ τοῦ φονέως αὐτῷ ψῆφος· κατὰ συμβεβηκὸς δέ, ἡ κατὰ τοῦδε τοῦ ἀνθρώπου, ὅτι ἑκὼν ὑπέδυ τὸ τοῦ φονέως πρόσωπον. Καὶ πάλιν, ὁ πονηρὸς ἄνθρωπος φονεῦσαι μὲν ἠβούλετο, δοῦναι δὲ ἐπὶ τούτῳ δίκας οὐκ ἤθελεν. Ὥστε καὶ ἐπὶ τούτου γίγνεσθαι προηγουμένην μὲν τὴν φονικὴν διάθεσιν, ὡς ἀπὸ τοῦ αὐτεξουσίου τῆς ψυχῆς ἠρτημένην· κατὰ συμβεβηκὸς δὲ ἐπακολουθεῖν τὰς ἐπὶ ταύτῃ στρεβλώσεις τε καὶ αἰκίας. Τούτων δὲ πάντων αἴτιος ὁ νόμος, ὁ καὶ τῷ δικαστῇ τὴν προαίρεσιν τοῦ κολάζειν τοὺς φαύλους ἐντιθείς, καὶ τῷ φονεῖ τὴν τιμωρὸν ψῆφον ἐπάγων. Ταὐτὸ δή μοι τοῦτο καὶ ἐπὶ τῆς θείας ἐπιστασίας λογίζου· προαιρέσεως ἀνθρωπίνης δρᾶσαι κακὰ βουληθείσης, καὶ προαιρέσεως νομοφυλάκων δικαστῶν ἐπανορθοῦσθαι τὰ κακὰ πάσῃ μηχανῇ πειρωμένης, τὴν συνδρομὴν δαιμονίαν τύχην ἀποτελεῖν, καθ' ἣν ὁ τὰ τοιάδε εἰργασμένος τῶν τοιῶνδε γίνεται ἄξιος τιμωρημάτων· τοῦ μὲν προῃρῆσθαι τὰ φαῦλα εἰς τὸ αὐτεξούσιον τοῦ κρινομένου τὴν αἰτίαν ἀναφέροντος, τοῦ δὲ ἑπομένου τῇ ἀξίᾳ τιμωρήματος εἰς τὴν τῶν κρινόντων νομοφυλακικὴν ἐπιστήμην· τούτων δὲ συναγωγέα εἶναι τὸν νόμον, τὸν ἀγαθὰ μὲν εἶναι πάντα κατὰ δύναμιν, φαῦλον δὲ μηδὲν εἶναι, διατεταγμένον. Οὗτος γὰρ προϋφεστὼς ἐν τῇ τοῦ θεοῦ ἀγαθότητι οὐκ ἐᾷ ἀνευθύνους εἶναι τοὺς κακούς, ἵνα μὴ ἐμμένον τὸ κακὸν εἰς ἀναισθησίαν παντελῆ τῶν ἀγαθῶν ἐλάσῃ, ὧν τὴν ἀναγκαίαν ὑπόμνησιν ἡ παρὰ τῶν νομοφυλάκων δίκη χορηγεῖ.", "st": "11.5"}, {"sp": "N", "t": "Συνάγει οὖν ὁ νόμος, ὡς εἴρηται, τοὺς πεφυκότας κρίνειν, καὶ τοὺς πεφυκότας κακύνεσθαι, δι' ἀμφοτέρων τὸ οἰκεῖον ἀπεργαζόμενος ἀγαθόν. Εἰ γὰρ τὸ διδόναι δίκην τοῦ μὴ διδόναι ἐστὶ λυσιτελέστερον, καὶ πρὸς σωφρονισμὸν τῆς ἀμετρίας τῶν κακῶν ἡ δίκη βλέπει, δῆλον ὅτι πρὸς τὸ ὠφελεῖν καὶ ὠφελεῖσθαι συνήρμοσεν ὁ νόμος τὰ δύο ταῦτα γένη· τὸ μὲν κριτικόν, ὡς νομοφυλακικόν, τοῦ ἑτέρου προτάξας· τὸ δὲ ἁμαρτάνειν καὶ κρίνεσθαι πεφυκός, ὡς παρανομητικόν, τῷ ἀμείνονι παραδοὺς γένει, κατὰ τὴν ἀξίαν αὐτὸ μεταχειρίζεσθαι, ὅπως ἂν εἰς ἀνάμνησιν καὶ ἔννοιαν ἔλθῃ ποτὲ τοῦ νόμου, δι' οὗ πάσχει κακῶς. Ὃν γὰρ ἐν τῷ πράττειν κακῶς ἀπηρνοῦντο, τοῦτον ἐν τῷ πάσχειν κακῶς ἐπιποθοῦσιν οἱ ἄνθρωποι. Οἷον, ὁ ἀδικῶν οὐ βούλεται εἶναι θεόν, ἵνα μὴ τὸ διδόναι δίκην, ὡσπερεί τινα Ταντάλου λίθον, ἐπικρεμάμενον ἔχῃ· ὁ δὲ ἀδικούμενος βούλεται εἶναι θεόν, ἵν' ἐπικουρίας ὧν πέπονθε τύχῃ. Διὸ τοὺς ἀδικοῦντας εἰς τὸ ἀδικεῖσθαι περιστῆναι δεῖ, ἵν' ὃ μὴ ἔβλεπον ἐν τῷ δρᾶν, τῷ τῆς πλεονεξίας πάθει μεθύοντες, ἐν τῷ πάσχειν μεταμάθωσι, τῷ τῆς ἐλαττώσεως ἀνιαρῷ παιδευόμενοι, εἴ γε καλῶς ὑπέχοιεν δίκας. Εἰ δὲ τῇ ἰταμότητι τῆς προαιρέσεως ἔτι κακύνοιντο, αὐτοὶ μὲν ἴσως ἧττον ὠφελοῦνται· παράδειγμα δέ που γίνονται πάντως παιδευτικὸν τοῖς εὖ φρονοῦσι, καὶ διαισθάνεσθαι δυναμένοις τὰς αἰτίας τῶν τοιούτων παθῶν.", "st": "11.6"}, {"sp": "N", "t": "Ταύτας τῆς κρίσεως ἀρχὰς κυριωτάτας ἀποδεχώμεθα, τὴν ἀγαθότητα τοῦ θεοῦ, τὸν ἀπὸ ταύτης νόμον, τὸν ἐν ἡμῖν παρανομούμενον ὀρθὸν λόγον, καί, ὥσπερ τινὰ ἔνοικον θεόν, πλημμελούμενον· ἀποτέλεσμα δὲ τῆς κρίσεως, τὰ ἄλγεα, ὥς φησι, ταῦτα, ὅσα τραχύτερον ἡμῖν ποιεῖ τὸν βίον ταῖς περὶ σῶμά τε καὶ τὰ ἐκτὸς λύμαις· ἃ δὴ πράως φέρειν ὁ παρὼν εἰσηγεῖται λόγος ἐνθυμουμένους τὰς αἰτίας αὐτῶν, καὶ ὅσον οἷόν τε περικόπτοντας, καὶ μετατιθέντας εἰς ὠφέλειαν τὰ δοκοῦντα βλαβερά· μάλιστα μὲν τῶν θείων ἀγαθῶν ἑαυτοὺς ἀξίους παρέχεσθαι διὰ τῆς ἀκροτάτης ἀρετῆς. Εἰ δέ τῳ τοῦτο οὔπω ἐν ὀρέξει, τῶν γοῦν πολιτικῶν ἀγαθῶν διὰ τῆς μέσης ἀρετῆς τυγχανέτω. Τοῦτο γὰρ ἦν, ὃ πρὸς τὸ πάσχειν καλῶς τὰ ἀλγεινὰ καὶ ἰᾶσθαι αὐτὰ ἐπιταττόμεθα. Τίς οὖν ἡ ἴασις, ἢ τὰ προειρημένα πάντα, ἀφ' ὧν καὶ ἡ εὐλόγιστος τῶν ἀλγεινῶν ὑπομονή, καὶ ἡ θεραπευτικὴ μέθοδος ὑποδείκνυται;", "st": "11.7"}, {"sp": "N", "t": "Κεφάλαιον δὲ τῶν εἰρημένων, ὅτι ὁ θεός, νομοθέτης ὢν ἅμα καὶ δικαστής, τίθεται μὲν τὰ ἀγαθά, ἀναιρεῖ δὲ τὰ κακά· διὸ καὶ πάντῃ κακῶν ἐστιν ἀναίτιος· τοὺς δὲ κακυνθέντας αὐτεξουσίοις ὁρμαῖς, καὶ τὸν ἐν αὑτοῖς ὀρθὸν λόγον ἀμνημονήσαντας, ὡς μὲν κακοὺς κολάζει τῷ νόμῳ τῷ ἀπαγορεύοντι τὰ κακά· ὡς δὲ ἀνθρώπους, τῇ ἐπεισιούσῃ ἐπιπλοκῇ τοῦ νόμου πρὸς τὴν προαίρεσιν, ἣν δὴ τύχην καλοῦμεν. Οὐ γὰρ ἁπλῶς τὸν ἄνθρωπον, ᾗ ἄνθρωπον, κολάζει ὁ νόμος, ἀλλ' ᾗ κακόν. Τοῦ δὲ κακὸν γενέσθαι τὴν πρώτην αἰτίαν εἶχεν ἡ προαίρεσις· ἐπειδὰν δὲ κακὸς γένηται (ὅπερ ἦν ἐφ' ἡμῖν, ἀλλ' οὐκ ἐπὶ τῷ θεῷ), τότε δίδωσι δίκας (ὅπερ ἦν ἐπὶ τῷ θείῳ νόμῳ, ἀλλ' οὐκ ἐφ' ἡμῖν). Σκοπὸς δὲ τοῦ νόμου μόνος ἂν εἴη πρέπων τε θεῷ, καὶ ἡμῖν ἐπωφελής, τὸ διακόψαι τὴν κακίαν, καὶ ἀποκαθᾶραι τοῖς παντοδαποῖς τῆς δίκης σωφρονισμοῖς, καὶ ἐπιστρέψαι τὴν ὑποπεσοῦσαν τῇ πονηρίᾳ ψυχὴν εἰς ἀνάμνησιν τοῦ ὀρθοῦ λόγου. Καὶ οὕτως ἑστῶτος τοῦ νόμου, καὶ τὰ αὐτὰ ἀεὶ φθεγγομένου, τὴν ἀξίαν ἕκαστος τὴν ἑαυτοῦ ἄλλοτε ἄλλην ποιήσας οὐ τῶν αὐτῶν ἀεὶ τυγχάνει· οὐ γὰρ δίκαιον τοῦτό γε, οὐδὲ ἡμῖν συμφέρον. Τὴν δὲ μεταβολὴν τῆς κρίσεως ἡ τοῦ κρινομένου μεταβολὴ δίδωσι· τὸν γὰρ μὴ τὸν αὐτὸν διαμείναντα πῶς τῶν αὐτῶν ἐστιν ἀξιοῦν;", "st": "11.8"}, {"sp": "N", "t": "Καλῶς φέρειν οὖν τὰς δαιμονίας τύχας δεῖ, καὶ μὴ ἀγανακτεῖν διδόντα δίκην, καί, ὅσον ἐπὶ τῇ θείᾳ κρίσει, καθαιρόμενον, διὰ τῶν δοκούντων ἐμποδίων εἶναι πρὸς εὐπάθειαν τοῦ τῇδε βίου. Ὁ δὲ τοιοῦτος λογισμὸς ἴασίς τε γίνεται τῶν προημαρτημένων, καὶ ἐπιστροφὴ πρὸς τὸν ἐνυπάρχοντα ἡμῖν ὀρθὸν λόγον· πῶς γὰρ ὁ κακίας εἶναι καρποὺς τὰ ἀλγεινὰ τιθέμενος, οὐ φεύξεται τὴν εἰς ταῦτα κατάγουσαν αὐτὸν αἰτίαν, καί, εἰ δεῖ χαλεπαίνειν ἐν τοῖς λυπηροῖς, ἑαυτῷ μᾶλλον οἰήσεται δεῖν χαλεπαίνειν, ἢ τῷ κωλύοντι τὴν πονηρίαν θεῷ διὰ τῶν ὀργάνων τῆς δίκης, δι' ὧν ἐστι συνιέναι καὶ ἀναμιμνήσκεσθαι, οἷον ἦν ἄρα ἀγαθὸν μὴ ἀφίστασθαι τῶν θείων νόμων, μηδὲ ἑκόντας κακύνεσθαι. Οὐ γὰρ ὡς ἔτυχε τὰ ἀλγεινὰ τοῖς ἀνθρώποις διανέμεται, εἴπερ θεὸς καὶ δίκης ὅροι προεστήκασιν ἡμῶν, τὴν ἀξίαν μοῖραν ἐφ' ἑκάστοις ἐπάγοντες· διό, καὶ τὸ οὐ πάνυ τοῖς ἀγαθοῖς τὰ ἀλγεινὰ συμπίπτειν, εὔλογον.", "st": "11.9"}, {"sp": "N", "t": "Πρῶτον μὲν γὰρ οἴσουσιν αὐτὰ πράως τῇ εὐαρεστίᾳ τῆς θείας κρίσεως, καὶ τῇ τῆς ἀρετῆς προσκτήσει, δι' ἣν πραότερα μὲν τὰ χαλεπὰ γίνεται. Καὶ εὔελπις δὲ τοῦ λοιποῦ ὁ βίος μηδαμῶς ἐνοχλήσειν ἡμᾶς τὰ τοιαῦτα, εἴπερ ἀγαθοῖς γενομένοις, κατὰ μὲν τὴν ἀκροτάτην ἀρετὴν τὰ θεῖα ἀγαθὰ ἡμῖν ἀπόκειται, κατὰ δὲ τὴν μέσην ἕξιν, τὰ ἀνθρώπινα. Ἔπειτα καὶ ἰάσονται κατὰ δύναμιν τὰ τοιαῦτα ἐξ αὐτοῦ τοῦ φέρειν πράως, τὰς μεθόδους τῆς θεραπείας αὐτῶν διδασκόμενοι. Πῶς γὰρ οἷόν τε ταῖς ἱεραῖς ἱκετείαις θεοπρεπῶς χρήσασθαι, μὴ πρόνοιαν καὶ δίκην ἐφορᾶν τὰ ἀνθρώπινα τιθεμένους, καὶ τὴν ψυχὴν ἡμῶν ἀθάνατον οὖσαν τοιούτων ἑκάστοτε τυγχάνειν τῶν ἔξωθεν, οἵων ἂν ἑαυτὴν ἀξίαν παράσχηται ἐκ τῶν προαιρετικῶν κινημάτων; Ὁ γὰρ μὴ εἰς ταῦτα ἀναφέρων τὴν παροῦσαν μοῖραν, πόθεν τοῦ πράως φέρειν αὐτὴν τὰς ἀφορμὰς λήψεται; πόθεν δὲ τοῦ ἰᾶσθαι τὴν τέχνην; οὐκ ἔστιν εἰπεῖν. Εὐαρεστῆσαι μὲν γὰρ αὐτόθεν τοῖς τοιούτοις οὐκ ἔστιν, ὡς ἀδιαφόροις, ἢ καὶ ἀμείνοσι τῶν ἐναντίων, ἐπειδὴ παρ' ἑαυτῶν φευκτὰ εἶναι φαίνεται, ἀλγεινὰ ὄντα καὶ ἐπίπονα. Τὰ δὲ τοιαῦτα οὐ προσίεται ἡμῶν ἡ φύσις, ὡς τὰ δι' ἑαυτὰ αἱρετά, εἰ μὴ ἄρα ἀγαθόν τι προσδοκώμενον εἴη ἐπὶ τῇ τληπαθείᾳ τῶν δυσχερῶν. Ἀνάγκη οὖν δυσχεραίνειν, καὶ δυσαρεστίας ἐμπίπλασθαι, καὶ προσεπιτείνειν τὰ ἀλγεινὰ ἐκ τῆς περὶ τὴν οὐσίαν ἡμῶν ἀγνοίας, καὶ οὐδὲν μὲν ἧττον διδόναι δίκας· τὴν μεγίστην δὲ ἐπικτᾶσθαι κακίαν, ἐὰν ἀπρονόητον τὸ πᾶν, ἢ κακῶς φροντιζόμενον, οἰηθῶμεν. Τοῦτο δὲ ταὐτόν ἐστι τῷ μὴ οἴεσθαι εἶναι θεόν, ἢ ὄντα μὴ προνοεῖν, ἢ προνοοῦντα μὴ ἀγαθὸν εἶναι, καὶ δίκαιον· ἃ δὴ τῆς παντοδαπῆς ἀσεβείας ἐστὶ συνεκτικώτατα, καὶ πρὸς πᾶσαν κακίαν συνωθοῦντα τὸν τοῖς τοιούτοις ἑαλωκότα δοξάσμασιν. Ὡς γὰρ ἡ εὐσέβεια μήτηρ τῶν ἀρετῶν ἀνεφάνη, οὕτω καὶ πάσης κακίας ἡγεμὼν ἡ τῆς εὐσεβείας ἀπόπτωσις.", "st": "11.10"}, {"sp": "N", "t": "Μόνος οὖν ἐξευρήσει τούτων τὴν ἴασιν ὁ πράως αὐτὰ φέρειν ἐκδεδιδαγμένος. Τοῦτο δὲ διὰ φιλοσοφίας μόνης παραγίνεται, τὰς πάντων τῶν ὄντων οὐσίας ἀκριβῶς ἐπισταμένης, καὶ τὰς ἑπομένας ταῖς οὐσίαις αὐτῶν ἐνεργείας, ὧν εἱρμὸς καὶ σύνταξίς ἐστιν ἡ τῶν ὅλων διοίκησις, ἀφ' ἧς καὶ τὰς δαιμονίας τύχας ἀπονέμεσθαι ἀνάγκη· εἶναι δὲ τὴν ἑκάστῳ ἀπονεμηθεῖσαν ἀξίαν, τὴν νῦν λεγομένην μοῖραν, ἠρτημένην τῆς τε προνοίας τοῦ θεοῦ καὶ τῆς κοσμικῆς εὐταξίας καὶ τῆς ἀνθρωπίνης προαιρέσεως. Εἰ γὰρ μὴ εἴη θεοῦ πρόνοια, οὐκ ἂν εἴη τάξις ἐν κόσμῳ, ἣν καὶ εἱμαρμένην ἂν εἴποι τις. Εἰ δὲ μὴ ταῦτα εἴη, δίκη καὶ κρίσις τῶν κακῶν οὐκ ἂν γένοιτο· ἀλλ' οὐδὲ τιμὴ καὶ ἀποδοχὴ τῶν ἀγαθῶν. Προνοίας δὲ οὔσης καὶ τάξεως, πάντας ἔδει τοὺς νῦν γεννωμένους τῶν ἴσων ἀγαθῶν τυγχάνειν, εἰ μηδὲν παρ' ἑαυτῶν εἰς τὴν ἀνισότητα συνετέλεσαν. Φαίνονται δὲ οὐ τῶν ἴσων τυγχάνοντες. Δῆλον οὖν, ὡς τὸ τῆς προαιρέσεως ἄνισον, ὑποβληθὲν τῇ τῆς προνοίας κρίσει, οὐκ ἐᾷ τὴν ἴσην αὐτοῖς ἀπονέμεσθαι μοῖραν, εἴγε τῶν πρὸς ἀξίαν ἀνάγκη τυγχάνειν.", "st": "11.11"}, {"sp": "N", "t": "Μὴ ταραττέτω δὲ ἡμᾶς τὸ καὶ ἐπὶ ζῴων ἀλόγων, καὶ φυτῶν, καὶ αὐτῶν τῶν ἀψύχων τὴν αὐτὴν ἀνωμαλίαν ἐπιφαίνεσθαι, ἣν καὶ ἐπ' ἀνθρώπων. Οὐ γὰρ διὰ τοῦτο τὰ καθ' ἡμᾶς ἀπρονόητα, εἴγε ἐκείνοις ταῦτα, ὡς ἔτυχε, συμβαίνει, ἢ καὶ ἐπ' ἐκείνων δίκη καὶ κρίσις, καὶ ἀρετῆς καὶ κακίας ἐκλογισμοί, ἐπεὶ τὰ καθ' ἡμᾶς οὕτως ἠκρίβωται. Πρῶτον μὲν γὰρ τὰ ἄψυχα οὕτως ἔκκειται ὡς κοινὴ ὕλη φυτοῖς, καὶ ζῴοις, καὶ ἀνθρώποις· ἔπειτα τὰ φυτὰ ζῴοις καὶ ἀνθρώποις κοινὴ τροφὴ πρόκειται, καὶ ἔνια δὲ ζῴων ζῴοις τε καὶ ἀνθρώποις. Διὸ καὶ ποιεῖ ταῦτα εἰς ἄλληλα, οὐ τὴν τῶν πασχόντων ἀξίαν ἐπισκεπτόμενα, ἀλλὰ τὴν ἑαυτῶν πεῖναν ἢ τὴν νόσον θεραπεύοντα, καὶ ὅλως τὸ ἐνδεὲς αὑτῶν πληροῦντα, ὅθεν ἂν τοῦτο ποιεῖν ἐξῇ. Ὥστε δυστυχίας ἀφορμὴν εἶναι τοῖς ζῴοις τὴν ἡμετέραν χρείαν ἐκ τῶν παρατυχόντων πληρουμένην, καὶ τῆς δοκούσης εὐτυχίας αὐτοῖς αἴτιον τὸ παρ' ἡμῶν προσπαθές. Εἰ μὲν οὖν προϊὼν ὁ λόγος καὶ ἄλλους κρείττονας ἡμῶν τινας ἀντεισήγαγεν οὕτως ἀποχρωμένους ἡμῖν πρὸς πλήρωσιν τῆς ἑαυτῶν ἐνδείας, ὡς ἡμεῖς τοῖς ἀλόγοις φαινόμεθα χρώμενοι, θνητοὺς ἐκείνους ἔδει ὁμολογεῖν, καὶ φαίνεσθαι τὰ σώματα τῶν ἀνθρώπων εἰς τὴν ἐκείνων χρείαν ἀναλισκόμενα. Εἰ δὲ μηδὲν τῶν πρὸ ἀνθρώπου θνητόν (ἐπειδὴ καὶ αὐτὸς ἔσχατος ὢν τῶν λογικῶν γενῶν, καὶ διὰ τοῦτο ἀθάνατος εἰς σῶμα θνητὸν ἐκ περιστάσεως ἔρχεται, καὶ συγγενές τι τοῖς ἀλόγοις ἀναλαβὼν ὄργανον ἐπὶ γῆς πολιτεύεται), οὐδὲν ἂν εἴη τὸ ταῖς ἡμετέραις δυστυχίαις εἰς τὴν ἑαυτοῦ θοίνην ἀποχρησόμενον· οὐκοῦν οὐδὲ τὸ ἀτάκτως χρησόμενον ἡμῖν προθυμίᾳ πληρώσεως. Δίκη τοίνυν καὶ τάξις τοῖς πρὸ ἡμῶν ἀθανάτοις τοὺς ὅρους τῆς περὶ ἡμᾶς διοικήσεως νομοθετεῖ, ταῦτα μηχανᾶσθαι περὶ ἡμᾶς, ἃ τήν τε ἐνταῦθα κακίαν ἡμῶν ἐλαττοῖ, καὶ πρὸς αὐτοὺς ἐπιστρέφειν ἡμᾶς δύναται. Κήδονται γὰρ ἡμῶν, ὡς συγγενῶν ἐκπεσόντων. Ὅθεν αἰδὼς καὶ νέμεσις καὶ αἰσχύνη ἀποτρέπουσαι τῶν κακῶν, ἀνθρώπους μόνους ἐπιστρέφεσθαι λέγονται ὀρθῶς. Τὸ γὰρ λογικὸν ζῷον μόνον συναισθάνεσθαι τῆς δίκης πέφυκε.", "st": "11.12"}, {"sp": "N", "t": "Τοῖς μεγίστοις οὖν ὅροις διεστῶτας ἡμᾶς ἀπὸ τῶν ἀλόγων διεστώσῃ πάμπολυ καὶ τῇ διοικήσει χρῆσθαι προσήκει. Σύμμετρος γὰρ ταῖς οὐσίαις τῶν ὄντων καὶ ὁ τῆς προνοίας θεσμός· καὶ ὡς ἕκαστα ὑπέστη παρὰ τοῦ δημιουργοῦ θεοῦ, οὕτω καὶ προνοίας ἀξιοῦται. Φαίνεται δέ, ἐπὶ μὲν τῶν ἀνθρωπίνων ψυχῶν, ἑκάστην αὐτὸς ὑποστήσας· ἐπὶ δὲ τῶν ἀλόγων μόνα γένη, προτείνων τῇ διαπλαττούσῃ αὐτὰ φύσει, ὡς Πλάτωνι δοκεῖ, καὶ Τιμαίῳ τῷ Πυθαγορείῳ, οὐδὲν μὲν προσεχὲς τῶν θνητῶν δημιούργημα εἶναι τοῦ θεοῦ τιθεμένοις, τὰς δὲ ἀνθρωπίνας ψυχὰς γίνεσθαι ἐκ τοῦ αὐτοῦ κρατῆρος τοῖς τε ἐγκοσμίοις θεοῖς, καὶ τοῖς δαίμοσιν, ἢ τοῖς ἀγαυοῖς ἥρωσι· διὸ πρόνοια ἐπ' ἀνθρώπων ἐστὶ καθ' ἕνα ἕκαστον, πῶς ἀφίσταται τῶν ἐκεῖ· πῶς πρὸς τὰ τῇδε νεύει· πῶς ἐνταῦθα πολιτεύεται· πῶς ἂν ἐντεῦθεν ἀνακομισθείη ἐκεῖσε· ὧν οὐδὲν δεῖ περὶ τῆς ἀλόγου ζωῆς πραγματεύεσθαι. Οὔτε γὰρ ἦλθεν ἀδυνατήσασα ἐπισπέσθαι θεῷ· οὔτε ἐπὶ γῆς δύναται πολιτεύεσθαι, ὡς φυτὸν οὖσα οὐράνιον· οὔτε πρός τι ξύννομον ἄστρον ἀνάγεσθαι πέφυκε.", "st": "11.13"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν πρὸς τὸ παρὸν ἀπολελογήσθω ἡμῖν πρὸς τοὺς δυσχεραντικούς, καὶ πανταχόθεν τὸ ἀπρονόητον κατασκευάζοντας· πρὸς οὓς καὶ ταῦτα εἰπεῖν δίκαιον, ὅτι ἐκ μὲν τοῦ πράως τὰ δυσχερῆ φέρειν ὁ ἀνθρώπινος τρόπος εὐλόγιστος ἀναφαίνεται, καὶ πρὸς τὸ παρὸν ἐπελαφρύνων τὰ δυσχερῆ, καὶ πρὸς τὸ μέλλον ἰώμενος. Ὑμεῖς δὲ ἀγανακτοῦντες τί καὶ ὀνήσετε, εἰ μὴ μόνον προσθείητε τοῖς πόνοις τὸ μέγιστον τῶν κακῶν ἀσέβειαν, καὶ αὐτὰ δὲ τὰ χαλεπὰ τραχύτερα ἑαυτοῖς ἐξεργάσησθε τῷ παρὰ τὴν ἀξίαν πάσχειν αὐτὰ δοκεῖν; Ὁ γὰρ νοσῶν ἐὰν ἀγανακτῇ ὅτι νοσεῖ, δι' αὐτὸ τοῦτο μᾶλλον νοσήσει. Διὸ οὐδὲ χαλεπαίνειν δεῖ πρὸς τὴν ἀξίαν τῆς ἀποδόσεως γινομένης, ἵνα μὴ καὶ χειρόνων ἐν ἕξει γενώμεθα, διὰ τὴν ἐπὶ τοῖς παροῦσι βλάσφημον δυσφορίαν. Σκεψώμεθα δὲ αὐτὸ καὶ τῇδε· εἴ τις πενίαν λαβὼν πράως φέρει, πρὸς τῇ ἀπὸ τῆς πραότητος ἀλυπίᾳ, καὶ ἐξευρήσει τινὰ τοῦ βίου παραμυθίαν· τοῦτο μέν, τοῦ λογισμοῦ πόρον ἐξευρίσκοντος εὐλόγου διατροφῆς, τῷ μὴ συγκεχύσθαι τῇ λύπῃ· τοῦτο δέ, ἀγαμένων αὐτὸν τῶν πλησίον τῆς ἔμφρονος καρτερίας, καὶ συνεκποριζόντων, ὅση δύναμις, τὰ ἀναγκαῖα πρὸς τὸν βίον. Ὁ δὲ ἀγανακτῶν, καὶ γυναικείως πικραινόμενος, πρῶτον μὲν ἑκουσίας λύπας προσκτᾶται· ἔπειτα προσδεδεμένος τῷ τὴν πενίαν πενθεῖν, ἄπορος παντελῶς γίνεται, οὔτε παρ' ἑαυτοῦ τι σχολάζων εἰς πόρον συμβάλλεσθαι, οὔτε παρὰ τῶν πλησίον συντελούμενος, ὅσον μὴ ἐλέου χάριν αὐτῷ τις προσρίψειεν· ὃ πάλιν ἐκ τῆς διαθέσεως τοῦ διδόντος ἐπιτείνει τὴν λύπην τῷ εἰς τοῦτο χρείας καταστάντι.", "st": "11.14"}, {"sp": "N", "t": "Ἐκ πάντων οὖν τῶν εἰρημένων πράως φέρειν δεῖ τὰ συμβαίνοντα, καὶ ὅση δύναμις ἰᾶσθαι δεῖ, ταῖς ἀδιαστρόφοις ἐννοίαις τὰς αἰτίας αὐτῶν ἐκλογιζομένους, καὶ συνορῶντας, ὅτι προνοίας οὔσης, οὐκ ἀμελεῖται ὁ ἀγαθὸς νῦν γενόμενος, κἂν παλαιῶν μηνιμάτων ἐφέλκηται στίγματα. Κατ' αὐτὸ γὰρ τὸ κτᾶσθαι τὴν ἀρετὴν καὶ τὸ ἐπίπονον αὐτῶν διαφεύγει, καὶ τὴν ἴασιν ἐξευρίσκει, παρ' ἑαυτοῦ μὲν τὴν βοήθειαν τῆς ἀλυπίας εἰσφέρων, παρὰ δὲ τῆς προνοίας τὴν ἀπόλυσιν τῶν χαλεπῶν κομιζόμενος. Ἡ γὰρ ἡμετέρα κακία, καὶ κρίσις θεία τιμωρουμένη τὴν πονηρίαν, τὰ χαλεπὰ συνεφόρησεν· εἰκότως δὲ ταῦτα λύεται πάλιν ἀρετῇ τε ἡμετέρᾳ, καὶ νόμῳ προνοίας, ἀπολύοντι τῶν κακῶν τοὺς παρ' ἑαυτῶν πρὸς τὸ ἀγαθὸν ἐπιδεδωκότας.", "st": "11.15"}, {"sp": "N", "t": "Τοσαῦτα ἂν λάβοιμεν, καὶ ἐκ τούτων τῶν ἐπῶν δόγματα πρὸς ἀρετῆς στοιχείωσιν συντελοῦντα. Τοὺς γὰρ περὶ προνοίας, καὶ εἱμαρμένης, καὶ τοῦ ἐφ' ἡμῖν, ἀληθεστάτους λόγους περιέχοντα ἀναπέφηνε, δι' ὧν τὸ τῆς τῶν φαινομένων ἀνωμαλίας δύσκολον ἀπηύθυνεν ὁ λόγος, καὶ διὰ πάντων ἀπέδειξε τῶν κακῶν ἀναίτιον τὸν θεόν. Εἰ δέ τις ταῦτα τοῖς προτέροις ἐπισυνάψειεν, εἷς ἐκ πάντων ἀναφανήσεται λόγος, τὴν τῆς ψυχῆς ἀϊδιότητα βεβαιούμενος. Τὸ γὰρ δικαιοσύνην ἀσκεῖν, καὶ γενναίως ἀποθνήσκειν, καὶ περὶ τὰ χρήματα ἐλευθερίως διακεῖσθαι, τοῦ μὴ συναποθνήσκειν τῷ σώματι τὴν ψυχὴν μάλιστα χρῄζει πρὸς κατασκευήν, ὡς ἤδη εἴρηται. Τὸ δὲ τὰς δαιμονίας τύχας πράως φέρειν, καὶ ἰᾶσθαι δύνασθαι, τοῦ μὴ συγγεννᾶσθαι τῷ σώματι τὴν ψυχὴν νῦν ἐφάνη δεόμενον· ἐκ δὲ ἀμφοτέρων τὸ γενέσεως καὶ φθορᾶς κρείττονα εἶναι τὴν ψυχὴν ἀποδείκνυται, καὶ ἑτέραν οὐσίαν παρὰ τὸ θνητὸν σῶμα, αὐτὴν καθ' ἑαυτὴν οὖσαν ἀΐδιον. Οὐ γὰρ οἷόν τέ ἐστιν ἀπό τινος χρόνου προελθόν τι εἰς γένεσιν εἰς ἀεὶ διαμένειν, ὥσπερ οὐδὲ τὸ ἐξ ἀϊδίου τὴν ὑπόστασιν ἔχον ποτὲ φθορὰν ἀναδέξασθαι. Εἴπερ οὖν μετὰ τὴν τοῦ σώματος φθορὰν ἡ ἀνθρωπίνη ψυχὴ διαμένουσα δίκης καὶ κρίσεως τυγχάνει, καὶ τῶν ἐπιτηδευθέντων ἐν τῷ βίῳ τὰς πρὸς ἀξίαν ἀμοιβὰς ἀποδέχεται, οὐχ οἷόν τε δὲ εἰς ἀεὶ διαμένειν τὸ ἀπὸ χρόνου γενόμενον· δῆλον, ὡς καὶ πρὸ τούτου ἦν τὸν ἅπαντα χρόνον. Καὶ οὕτω τῶν ἀϊδίων γεννημάτων τοῦ δημιουργοῦ θεοῦ καὶ ἡ ἀνθρωπίνη ψυχὴ ἀνευρίσκεται, ὅθεν αὐτῇ καὶ τῆς θείας ὁμοιώσεως μέτεστιν. Ἐπεὶ δὲ καὶ τοῦτο μετρίας ὑπομνήσεως ἔτυχε, καιρὸς ἂν εἴη καὶ τὰ λοιπὰ ἐπισκέψασθαι.", "st": "11.16"}, {"sp": "SEC", "t": "XII · 21–24", "st": "12"}, {"sp": "N", "t": "<span class=\"lemma\">Πολλοὶ δ' ἀνθρώποισι λόγοι δειλοί τε καὶ ἐσθλοὶ<br>προσπίπτουσ', ὧν μήτ' ἐκπλήσσεο, μήτ' ἄρ' ἐάσῃς<br>εἴργεσθαι σαυτόν· ψεῦδος δ' ἤνπερ τι λέγηται,<br>πράως εἶκε.<\/span>", "st": "12.0"}, {"sp": "N", "t": "Ἡ ἀνθρωπίνη προαίρεσις μήτ' ἐν ἀρετῇ ἀεὶ ἑστῶσα, μήτ' ἐν κακίᾳ, καὶ τοὺς διὰ φωνῆς προϊόντας λόγους ἐπαμφοτερίζοντας ἀπεγέννησεν, ὡς ἐοικότας ταῖς ἐναντίαις αὐτῆς διαθέσεσι. Διὸ τῶν λόγων ἐγένοντο οἱ μὲν ἀληθεῖς, οἱ δὲ ψευδεῖς, οἱ δὲ ἀγαθοί, οἱ δὲ κακοί. Ἡ δὲ διαφορὰ αὕτη ἐπιστημονικῆς δεῖται διακρίσεως, ὅπως τοὺς μὲν ἀμείνονας ἐκλεξώμεθα, τοὺς δὲ χείρους ἀποβάλωμεν, καὶ μήτε μισολογίαν νοσήσωμεν παντελῆ, διὰ τὴν τῶν χειρόνων λόγων κατάγνωσιν, μήτε ἀδιακρίτως πάντας εἰσδεξώμεθα, διὰ τὴν τῶν ἀμεινόνων ἀποδοχήν. Ἕπεται γὰρ τῇ μὲν μισολογίᾳ τὸ καὶ τῶν ἀγαθῶν λόγων ἑαυτοὺς ἀποστερεῖν, τῇ δὲ ἀκρίτῳ φιλολογίᾳ, τὸ λανθάνειν βλαπτομένους ὑπὸ τῶν κεκακουργημένων λόγων. Φιλολογίαν οὖν ἀσκήσωμεν μετὰ κρίσεως τῆς ἀρίστης, ἵνα ἡ φιληκοΐα πᾶν ἕλκῃ τὸ γένος τῶν λόγων, ἡ δὲ κρίσις ἀπωθῆται τὸν χείρονα. Καὶ οὕτω τὸ Πυθαγορικὸν τηρήσομεν παράγγελμα, μήτε ἐκπληττόμενοι τοὺς πονηροὺς τῶν λόγων, καὶ δι' αὐτὸ τοῦτο, ὅτι λόγοι εἰσίν, ἀκρίτως αὐτοὺς εἰσδεχόμενοι· μήτε τῶν ἀγαθῶν εἰργόμενοι, διότι λόγοι ἦσαν ὁμοίως τοῖς χείροσι. Πρῶτον μὲν γὰρ οὐχί, ᾗ λόγοι, μεταδιώκοιντο, ἀλλ' ᾗ ἀληθεῖς· οὔθ' οἱ ἕτεροι καταγινώσκοιντο, ὡς λόγοι, ἀλλ' ὡς ψευδεῖς. Ἔπειτα κἀκεῖνο εὐθαρσῶς ἂν εἴποιμεν, ὡς μόνοι λόγοι εἰσὶν οἱ ἀληθεῖς. Μόνοι γὰρ τῆς λογικῆς οὐσίας τὸ ἀξίωμα τηροῦσι, καί εἰσι γεννήματα ψυχῆς πρὸς τὸ ἄριστον ἀνατεταμένης, καὶ τὸν οἰκεῖον κόσμον κεκτημένης· οἱ δὲ ψευδεῖς τῶν λόγων οὐδὲ λόγοι ὄντως εἰσί, πρὸς γὰρ κακίαν καὶ ψευδοδοξίαν φέροντες, καὶ τὴν εὐγένειαν τῶν λόγων ἠρνήσαντο, καί εἰσιν ἠλογημένης ψυχῆς καὶ πάθεσι συμπεφυρμένης φωναί.", "st": "12.1"}, {"sp": "N", "t": "Μήτε οὖν πάντας καταδέχου, φησίν, ἵνα μὴ καὶ τοὺς ψευδεῖς· μήτε πάντας ἀπόβαλλε, ἵνα μὴ καὶ τοὺς ἀληθεῖς. Ἑκάτερον γὰρ ἄτοπον, τούς τε ἀγαθοὺς μισῆσαι σὺν τοῖς χείροσι, καὶ τοὺς ψευδεῖς προσίεσθαι διὰ τοὺς ἀμείνους. Δεῖ δὴ τοὺς μὲν ἀγαθοὺς ἐπαινεῖν, καὶ εἰσδεξάμενον αὐτοὺς ἀσκεῖσθαι, καὶ ζητεῖν ὅπῃ καὶ ἐφ' ὅσον τῆς ἀληθείας ἐφάπτονται, πρὸς δὲ τοὺς ψευδεῖς τὴν ἀγωνιστικὴν δύναμιν κτήσασθαι, αὕτη δ' ἂν εἴη ἡ χορηγουμένη ἐκ τῆς λογικῆς ἐπιστήμης εἰς διάκρισιν ἀληθείας καὶ ψεύδους· δυναμένους δὲ καὶ ἀνατρέπειν τὰ ψεύδη, μήτε σφοδρῶς, μήτε ὑβριστικῶς τοῦτο ποιεῖν· ἀλλὰ σὺν πραότητι τὴν ἀλήθειαν διώκειν, καὶ μετὰ εὐμενῶν ἐλέγχων τὸ ψεῦδος ἀνατρέπειν, καὶ ὡς αὐτό φησι τὸ ἔπος, ψεῦδος δ' ἤνπερ τι λέγηται, πράως εἴκοντας, οὐ συγχωροῦντας οὕτως ἔχειν, ὡς λέγεται, ἀλλὰ ἀοργήτως ἀκούοντας. Οὐ γὰρ συγκατατίθεσθαι δεῖν λέγει τῷ ψεύδει τὸ πράως εἶκε, ἀλλ' ἀνεκτικῶς ἀκροᾶσθαι, καὶ μὴ ἐκπλήττεσθαι, εἰ ἄνθρωποι ὄντες τινὲς τῆς ἀληθείας ἀποπεπτώκασιν ἀλυσιτελῶς. Γόνιμος γὰρ ἡ ἀνθρώπου φύσις πολλῶν διαστρόφων δοξασμάτων, ὅταν μὴ ταῖς κοιναῖς ἐννοίαις ὀρθῶς ἕπηται. Οὐδὲν οὖν, φησὶν ὁ λόγος, θαυμαστόν, εἰ ἄνθρωπος μηδὲν τῶν ἀληθῶν μήτε μαθών, μήτε εὑρών, εἰς τοῦτο τῆς ἀπονοίας ἦλθε, καὶ ἔθετο δόξας ὑπεναντίας τῇ ἀληθείᾳ. Τοὐναντίον γὰρ ἂν ἦν θαυμαστόν, εἰ μήτε μανθάνειν μήτε ζητεῖν ἐθέλων τις, αὐτομάτως τῇ ἀληθείᾳ περιέτυχεν, ὥσπερ ἐκ τραγῳδίας θεῷ τινι ἀναφανέντι. Δεῖ οὖν συγγνωμονικῶς ἀκούειν τῶν ψευδομένων, καὶ πείρᾳ μανθάνειν οἵων ἡμεῖς ἐκαθάρθημεν κακῶν, τῇ μὲν κοινωνίᾳ τοῦ συγγενοῦς ὑποκείμενοι τοῖς αὐτοῖς πάθεσι, τῷ δὲ ἀλεξικάκῳ τῆς ἐπιστήμης ἐξ ἐναντίας αὐτῶν γενόμενοι. Μέγα δὲ συντελεῖ πρὸς πραότητα καὶ τὸ τῆς ἐπιστήμης θάρσος· ἡ γὰρ ἱκανῶς παρεσκευασμένη ψυχὴ πρὸς τὸ καταγωνίσασθαι τὰς ἐκτροπὰς τῆς ἀληθείας ἀθορύβως οἴσει τὰς ψευδεῖς δόξας, ὡς προεκλελογισμένη πάντα τὰ παρὰ τὸ ἀληθὲς ἐν αὐτῇ τῇ τοῦ ἀληθοῦς κατανοήσει. Τί οὖν ταράξει τοῦτον, ὡς ἄλυτον ὄν; τί δὲ ἰσχυροῦ φαντασίαν παρέξει τούτῳ, ὃς προκατηγώνισται πᾶν τὸ ψεῦδος; Οὐ μόνον οὖν ἐκ τῆς ἠθικῆς ἀρετῆς τὴν ἀταραξίαν ἕξει ὁ ἐπιστήμων, ἀλλὰ καὶ ἐκ τοῦ θαρσεῖν τοὺς τοιούτους ἀγῶνας.", "st": "12.2"}, {"sp": "N", "t": "Ταῦτα μὲν περὶ τῆς ἐπιστημονικῆς τῶν λόγων διακρίσεως. Περὶ δὲ τῆς διὰ πάντων ἀνεξαπατήτου ἕξεως, ἣν δεῖ κεκτῆσθαι τὸν ἐπιστήμονα, εὐθὺς ἐπισυνάπτει.", "st": "12.3"}, {"sp": "SEC", "t": "XIII · 24–26", "st": "13"}, {"sp": "N", "t": "<span class=\"lemma\">Ὃ δέ τοι ἐρέω, ἐπὶ παντὶ τελείσθω·<br>μηδεὶς μήτε λόγῳ σε παρείπῃ, μήτε τι ἔργῳ,<br>πρῆξαι, μηδ' εἰπεῖν, ὅ, τι τοι μὴ βέλτερόν ἐστι.<\/span>", "st": "13.0"}, {"sp": "N", "t": "Τοῦτο διὰ πάντων τείνει τὸ παράγγελμα, ἰσοδυναμοῦν τῷ ἄνω που εἰρημένῳ,", "st": "13.1"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Πρήξεις δ' αἰσχρόν ποτε μήτε μετ' ἄλλου,<br>μήτ' ἰδίῃ· πάντων δὲ μάλιστ' αἰσχύνεο σαυτόν.<\/span><\/span>", "st": "13.2"}, {"sp": "N", "t": "Ὁ γὰρ ἑαυτὸν αἰδεῖσθαι μεμαθηκώς, καὶ μήτε ἐν μονώσει, μήτε ἐν κοινωνίᾳ, τὴν τοῦ αἰσχροῦ πρᾶξιν ἀνεχόμενος, ἀλλὰ καὶ τὴν φαντασίαν αὐτὴν τοῦ τοιούτου παραιτούμενος διὰ τὸν εἴσω φύλακα λόγον, οὗτός ἐστιν ὁ δυνάμενος νῦν ἀκούειν, μηδεὶς μήτε λόγῳ σε παρείπῃ, μήτε τι ἔργῳ. Μόνος γὰρ ἀνεξαπάτητος, καὶ ὑπ' οὐδενὸς οὐδαμῶς εὐπαραλόγιστος, ὁ τὴν ἀξίαν ἑαυτοῦ γνοὺς ἄνθρωπος, καὶ οὔτε κολακείαις θωπευόμενος, οὔτε τοῖς ἐκδειμαίνουσι ταπεινούμενος, κἂν πολέμιοι ἢ φίλοι ὁποτεραοῦν τούτων προτείνωσιν. Ἐν γὰρ τῷ μηδεὶς πᾶν πρόσωπον κεῖται, καὶ πατήρ, καὶ τύραννος, καὶ φίλος, καὶ ἐχθρός. Οἱ δὲ τρόποι τῆς παραγωγῆς ἢ διὰ λόγων ἢ ἔργων γίνονται· λόγων μέν, θωπευόντων ἢ ἀπειλούντων, ἔργων δέ, δωρεὰς ἢ τιμωρίας προτεινόντων. Πρὸς πάντα δὴ ταῦτα τετειχισμένην δεῖ τὴν ψυχὴν ἔχειν τῷ ὀρθῷ λόγῳ, πρὸς τὸ ἀμείλικτον καὶ ἀδούλωτον ὑπὸ τῶν ὁπωσοῦν ἔξωθεν προσπιπτόντων ἡμῖν ἡδέων τε καὶ λυπηρῶν. Ὁ γὰρ ὀρθὸς ἐνυπάρχων λόγος, σωφροσύνην καὶ ἀνδρείαν ἑκατέρωθεν παραστήσας τῇ ψυχῇ τοὺς ἀδαμαντίνους φύλακας, ἀνεξαπατήτους ἡμᾶς διατηρήσει καὶ ἀπὸ τῆς τῶν προσηνῶν θωπείας, καὶ ἀπὸ τῆς τῶν φοβερῶν καταπλήξεως· οἷς ἐπιγίνεται δικαιοσύνη ἀκριβής, ἣν παρήγγειλεν ἄνω που ἀσκεῖν ἔργῳ τε λόγῳ τε. Οὕτω μὲν οὖν οὐδεὶς οὐδαμῶς ἡμᾶς ἀναπείσει ἢ λόγον προέσθαι, ἢ ἔργον διαπράξασθαι, ὃ μὴ τῷ ὀρθῷ λόγῳ ἐστὶ σύμφωνον. Εἰ γὰρ πάντων μάλιστ' αἰσχυνοίμεθ' ἑαυτούς, δῆλον ὡς οὐδεὶς ἡμῖν αἰδεσιμώτερος ἡμῶν αὐτῶν φανήσεται, οὐδὲ φοβερώτερος, ὡς προκαλέσασθαι παρὰ τὸ δέον εἰπεῖν τι ἢ πρᾶξαι. Ἐπιβλαβὲς γὰρ τῇ ψυχῇ ἑκάτερον. Τὸ δὲ ἐκείνῃ βλαβερόν, τοῦτο καὶ ἡμῖν ἀσύμφορον· ἐπείπερ ἡμεῖς ἡ ψυχή.", "st": "13.3"}, {"sp": "N", "t": "Ἀκριβῶς οὖν ἀκουστέον τοῦ ὅ, τι τοι μὴ βέλτερόν ἐστι· κατ' ἐκείνου φέροντας τὴν ἀντωνυμίαν τοι, ὃ κυρίως σὺ εἶ. Ἐὰν οὖν τὸ λεγόμενον, μηδεὶς μήτε δι' ἔργων, μήτε διὰ λόγων, παραγάγῃ σε τι ποιῆσαι ἢ εἰπεῖν, ὅ, τι μὴ συμφέρον ἐστί σοι· σὺ δὲ ἦσθα ἡ λογικὴ ψυχή· οὐκ ἀνέξῃ, ἐὰν εὖ φρονῇς, τοῦ παραβλάπτοντός σε, τὸν ὄντα λογικὴν οὐσίαν. Σὺ γὰρ εἶ ἡ ψυχή· τὸ δὲ σῶμα, σόν· τὰ δὲ ἐκτός, τοῦ σώματος. Ἐκ γὰρ τῆς διαστάσεως ταύτης καὶ τὸ ἀσύγχυτον τηρήσεις τῶν φύσεων καὶ τὴν ἀνθρωπίνην οὐσίαν ἥτις ἐστὶν εὑρήσεις, οὐδέποτε τὸ σῶμα, οὐδὲ τὰ ἐκτός, σεαυτὸν εἶναι τιθέμενος, οὐδ' ὑπεραγωνιῶν τούτων ὥσπερ σαυτοῦ, ἵνα μὴ πρὸς φιλοσωματίαν καὶ φιλοχρηματίαν καθελκυσθῇς. Ὅλως γὰρ ὅ ἐσμεν ἀγνοήσαντες, καὶ οὗ τὴν ἐπιμέλειαν ποιώμεθα συναγνοήσομεν, πάντων μᾶλλον ἐπιμελούμενοι, ἢ ἡμῶν αὐτῶν, ὧν δεῖ προηγουμένην ποιεῖσθαι τὴν ἐπιμέλειαν. Εἰ γὰρ τὸ χρώμενον τῷ σώματί ἐστιν ἡ ψυχή, τὸ δὲ σῶμα ὀργάνου τάξιν ἐπέχει πρὸς αὐτήν, τοῦ δὲ ὀργάνου χάριν τὰ ἄλλα, πρὸς βοήθειαν τῆς ῥεούσης αὐτοῦ φύσεως, ἐξευρημένα· δῆλον, ὡς τοῦ ἡγουμένου καὶ πρώτου προηγουμένην τε καὶ πρώτην δεῖ ποιεῖσθαι τὴν ἐπιμέλειαν· δευτέραν δέ, τὴν τοῦ δευτέρου. Ὅθεν οὐδὲ ὑγιείας ἀμελήσει ὁ σοφός· οὔτι προηγούμενον τὸ σῶμα δοξάζων, ἀλλὰ πρὸς τὴν τῆς ψυχῆς χρείαν αὐτὸ παιδαγωγῶν, ὅπως ἂν ταῖς ἐνεργείαις αὐτῆς ἀνεμποδίστως ὑπακούῃ· καὶ ἐκ τρίτου τῶν τρίτων ἐπιμελήσεται, οἰκονομῶν τὰ ἐκτὸς πρὸς τὴν τοῦ ὀργάνου σωτηρίαν. Πρώτης οὖν τῆς ψυχῆς, τάχα δὲ καὶ μόνης, ἐπιμελήσεται· εἴπερ ἡ τῶν μετ' αὐτὴν ἐπιμέλεια πρὸς τὴν ταύτης προκοπὴν τείνει.", "st": "13.4"}, {"sp": "N", "t": "Πᾶν δὲ τὸ παρὰ τὴν ἀρετήν, τοῦτο ἦν, ὅ, τι τοι μὴ βέλτερόν ἐστιν· ᾧ γὰρ συμφέρον ἡ ἀρετή, τούτῳ τὸ παρ' ἐκείνην ἀσύμφορον. Κύκλον οὖν περιβάλλεσθαι συμβουλεύει τῶν ἀρετῶν φυλακτικὸν ὁ μηδὲν πείθεσθαι δεῖν λέγων τῷ πειρωμένῳ τῆς ἀρετῆς ἀπάγειν, δι' οἵων ἂν ἔργων ἢ λόγων τῆς πρὸς τὸ χεῖρον ἐκτρεπούσης πειθοῦς προσαγάγῃ τὴν πεῖραν· οἷον, μὴ ὑποσχέσεις προσάγων τύραννος, ἢ ταύτας ἔργῳ βεβαιῶν· μὴ ἀπειλαῖς θορυβῶν, ἢ αἰκίαις βιαζόμενος· μὴ φίλιον πρόσωπον, τῇ οἰκειότητι τὴν ἀπάτην ἐπικρυπτόμενον, ἀπαγάγῃ σε τοῦ συμφέροντος τῇ ψυχῇ. Ἦν δὲ ἀλήθεια καὶ ἀρετὴ τὰ ταύτην ὠφελοῦντα μόνα. Ἀνεξαπάτητος δὲ ἔσῃ, εἰ τὴν οὐσίαν τὴν σαυτοῦ γνούς, ἥτις τέ ἐστι, καὶ ᾧ φύσει ἔοικε, τῆς πρὸς ἐκεῖνο ὁμοιώσεως ἀεὶ τὴν ἐπιμέλειαν ἔχοις· πᾶν δὲ τὸ τῆς ὁμοιώσεως ἀπάγον μεγίστην ἡγοῖο ζημίαν. Τοῦτο γὰρ ἦν, ὅ, τι τοι μὴ βέλτερόν ἐστι, τὸ τῆς θείας ὁμοιώσεως ἀπάγον· ἐπειδὴ καὶ βέλτερον ἡμῖν ἐστι τὸ πρὸς τὴν τοιαύτην ὁμοίωσιν φέρον.", "st": "13.5"}, {"sp": "N", "t": "Τί οὖν προσάξει τις ἱκανὸν ἀποστῆσαι ἡμᾶς τῆς πρὸς θεὸν ὁμοιώσεως καὶ φιλοσοφίας; χρημάτων δόσιν ἢ ἀφαίρεσιν; Ἀλλὰ μεμαθήκαμεν μετὰ τοῦ ὀρθοῦ λόγου καὶ προσίεσθαι ταῦτα καὶ ἀποτίθεσθαι· καὶ τὸ ἄστατον τῆς κτήσεως αὐτῶν ἡμᾶς οὐ λανθάνει. Τί γάρ; ἂν μὴ οὗτος αὐτὰ ἀφέληται, κλέπτης αὐτὰ οὐκ ἀφαιρήσεται; καὶ γενναίως αὐτῶν ὑπομενοῦμεν τὴν ἀποβολὴν ὑπὸ τοῦ μὴ ἔχοντος. Ναυάγιον αὐτὰ οὐ παραιρήσεται; πόσοι δὲ ἄλλοι τρόποι διαφθορὰν χρημάτων ἐπάγουσιν; Ὧν ἕνεκα καὶ τὸν ὑπὲρ ἀρετῆς λογιούμεθα λόγον, ἑκουσίαν πενίαν μετὰ τοῦ καλοῦ ἀνταλλαττόμενοι χρημάτων, καὶ μετ' εὐλογίστου αἰτίας αὐτὰ ἀποδυόμενοι, καὶ τοσούτου τὴν ἀρετὴν ὠνούμενοι, ὅσον ἂν ἡμᾶς βλάπτῃ ὁ ταύτης παρακινεῖν ἐπιχειρῶν.", "st": "13.6"}, {"sp": "N", "t": "Ἀλλὰ στρεβλώσεις προσοίσει, καὶ θάνατον. Πρόχειρον οὖν πρὸς ταῦτα ἀποκρίνεσθαι, ὡς οὐχ ἡμεῖς ταῦτα πεισόμεθα, ἐάν γε τὸ Ἡμεῖς τηρῶμεν· ἀλλὰ τὸ σῶμα ἔσται τὸ ὑβριζόμενον· τὸ σῶμα τὸ ἀποθνῆσκον, οὐδὲν παρὰ τὴν αὑτοῦ φύσιν πάσχον. Φύσει γάρ ἐστι θνητόν, καὶ τμητόν, καὶ μυρίοις ὑποκείμενον πάθεσιν, ἃ τυράννου μᾶλλον ἡ τυχοῦσα νόσος ἐπήγαγε. Τί οὖν φεύγομεν ἃ οὐκ ἔστιν ἐφ' ἡμῖν φεύγειν; Οὐ τηροῦμεν δὲ μᾶλλον, ἅ ἐστιν ἐφ' ἡμῖν τηρῆσαι; Τὸ γὰρ θνητὸν φύσει καταδεδικασμένον θανάτῳ οὐκ ἔστιν ὁτιοῦν ποιοῦντας ἐκσῶσαι τούτου· τὸ δὲ ἀθάνατον ἡμῶν (ὅπερ ἐστὶν ἡ ψυχὴ καὶ ἡμεῖς) δυνατὸν ἀρετῇ κοσμῆσαι μὴ μαλακισθέντας περὶ τὸν ἀπειλούμενον θάνατον. Ὃν εἰ μετ' εὐλόγου αἰτίας ὑπομείνωμεν, κοσμήσομεν τῇ ὀρθῇ προαιρέσει τὴν ἀνάγκην τῆς φύσεως. Ταῦτα δή ἐστι τὰ μεγάλα, ὧν ἂν ἄλλος ἄλλῳ προτείνειέν τι παθεῖν, ἢ ἀποτίσαι· τὰ δὲ εἴσω τῆς ψυχῆς ἀδούλωτα ἄλλῳ, καὶ ἐλεύθερα, ἐὰν ἡμεῖς ἐθελήσωμεν· ἐὰν μὴ τῇ πρὸς τὸ σῶμα, ἢ τὰ ἐκτός, ἀμέτρῳ προσπαθείᾳ τὴν ἐλευθερίαν ἡμῶν ἑκόντες δουλαγωγήσωμεν, ζωῆς ἐφημέρου καὶ χρημάτων τὸ ἀγαθὸν τῆς ψυχῆς ἀποδιδόμενοι. Ταῦτα ἡμῖν εἰσηγεῖται τὸ προκείμενον παράγγελμα ἐπὶ παντὶ τελεῖν, δι' ὧν τὸ μόνιμον καὶ ἀπαράγωγον τῆς ἀρετῆς ἐπισφραγίζεται. Ἀλλὰ ἐπὶ τὰ ἑξῆς μετίωμεν, πρὸς τὸ αὐτὸ δόγμα τὴν ἀναφορὰν ἔχοντα.", "st": "13.7"}, {"sp": "SEC", "t": "XIV · 27–29", "st": "14"}, {"sp": "N", "t": "<span class=\"lemma\">Βουλεύου δὲ πρὸ ἔργου, ὅπως μὴ μῶρα πέληται·<br>δειλοῦ τοι πρήσσειν τε λέγειν τ' ἀνόητα πρὸς ἀνδρός·<br>ἀλλὰ τάδ' ἐκτελέειν, ἅ σε μὴ μετέπειτ' ἀνιήσει.<\/span>", "st": "14.0"}, {"sp": "N", "t": "Ἡ εὐβουλία καὶ γεννᾷ τὰς ἀρετάς, καὶ τελειοῖ, καὶ συνέχει, μήτηρ ἅμα καὶ τιθήνη καὶ φύλαξ αὐτῶν γενομένη. Βουλευομένων γὰρ ἡμῶν ἐφ' ἡσυχίας ὅν τινα τρόπον χρὴ ζῆν, τὸ τῶν ἀρετῶν προαιρεῖται κάλλος. Ἑλομένη δὲ διαθλεῖν γενναίως πάντας τοὺς ὑπὲρ ἀρετῆς ἀγῶνας, καὶ συνεθισθεῖσα τῇ κτήσει τῶν καλῶν ἤδη, κἀν ταῖς τῶν περιστάσεων ταραχαῖς τηρεῖ τὴν γνώμην ἀκέραιον, οὐδὲν ὑπὸ τῶν ἔξωθεν θορυβούντων ἐκπληττομένη πρὸς τὸ μεταθέσθαι ἄλλον εὐδαίμονα εἶναι βίον, ἢ ἐκεῖνον, ὃν ἐφ' ἑαυτῆς ἐλογίσατο κάλλιστον. Ὅθεν τρία γίνεται τῆς εὐβουλίας τὰ ἔργα. Πρῶτον, ἐκλογὴ τοῦ ἀρίστου βίου· δεύτερον, ἄσκησις τοῦ προαιρεθέντος· τρίτον, τήρησις ἀμετάστατος τῶν μελετηθέντων ὀρθῶς. Τούτων δὲ τὸ μὲν πρῶτόν ἐστιν ὁ πρὸ ἔργου λόγος, ὁ τὰς ἀρχὰς τῶν πράξεων ὑποτιθέμενος. Τὸ δὲ μέσον, ὁ σὺν τῷ ἔργῳ λόγος, ὁ προσβιβάζων ἕκαστον τῶν πραττομένων ταῖς ἡγουμέναις ἀρχαῖς. Τὸ δὲ τρίτον, ὁ ἐπὶ τῷ ἔργῳ λόγος ἀναλογιζόμενος τὰ πεπραγμένα, καὶ κρίνων εἰ δεόντως πέπρακται.", "st": "14.1"}, {"sp": "N", "t": "Διὰ πάντων δὲ τὸ τῆς εὐβουλίας καλὸν ἐπανθεῖ, νῦν μὲν κυούσης τὰς ἀρετάς, νῦν δὲ ἐκτρεφούσης, καὶ φρουρούσης ἐκ τρίτου. Ὡς ἀρχήν τε καὶ μέσα καὶ τελευτὴν τῶν ἀγαθῶν ἐν ταύτῃ ἡμῖν κεῖσθαι, τήν τε ἀπαλλαγὴν τῶν κακῶν διὰ ταύτης μόνης ἡμῖν παραγίνεσθαι, καὶ τὴν τῶν ἀρετῶν τελείωσιν. Λογικῆς γὰρ τῆς φύσεως ἡμῶν οὔσης, καὶ διὰ τοῦτο βουλευτικῆς, οἰκείᾳ δὲ προαιρέσει πρὸς τὸ εὖ ἢ κακῶς βουλεύεσθαι προσαγομένης, ἡ μὲν κατὰ φύσιν ζωὴ σώζει τὴν οὐσίαν αὐτῆς, ἡ δὲ παρὰ τὸ δέον αἵρεσις διαφθείρει ἐφ' ὅσον οἷόν τε. Φθορὰ δὲ ἀθανάτου πράγματος κακία, ἧς ἀβουλία μήτηρ, ἣν ἐκφυγεῖν ὁ λόγος παραινεῖ ὅπως μὴ μῶρα πέληται.", "st": "14.2"}, {"sp": "N", "t": "Μῶρα δὲ τὰ ἄθλια καὶ κακά. Τὸ γὰρ λέγειν ἢ πράσσειν ἀνόητα δειλοῦ πρὸς ἀνδρός ἐστιν, ἀντὶ τοῦ, κακοδαίμονος ἴδιον ἀνθρώπου. Εἰ δὲ βουλεύοιο πρὸ ἔργου, οὔτε ἐρεῖς τι, οὔτε πράξεις, ἀνόητον, ἐφ' οἷς ἀνιᾶσθαι ἀνάγκη τοὺς τῇ ἀβουλίᾳ ὑπευθύνους. Τὸ γὰρ σαθρὸν τῆς αἱρέσεως τῇ μεταμελείᾳ ἐλέγχεται πείρᾳ δεῖξαν τὴν βλάβην, ὥσπερ αὖ τὸ τῆς εὐβουλίας γενναῖον πρὸς τὸ μόνιμον ἄγει τῆς ἐκλογῆς, ἐπ' αὐτῶν τῶν ἔργων τὴν ὠφέλειαν ἐπιδεικνύμενον· ὠφέλειαν δέ, οὐ τὴν τοῦ σώματος, οὐδὲ τὴν τῶν ἐκτός, ἀλλὰ τὴν ἡμῶν αὐτῶν, οἷς καὶ τὸ βουλεύεσθαι πρὸ ἔργου παραγγέλλεται, καὶ ταῦτα ἐκτελεῖν, ἃ μὴ ἀνιήσει ἡμᾶς· ἡμᾶς δὲ δῆλον ὅτι τὴν ψυχήν.", "st": "14.3"}, {"sp": "N", "t": "Τί γὰρ ὄφελος ἐπιορκίαις, ἢ φόνοις, ἢ ἄλλαις τισὶ κακοπραγίαις ληΐσασθαι χρήματα, καὶ πλουτεῖν τὰ ἔξω, πενόμενον τὴν ψυχὴν τῶν ἐπιβαλλόντων αὐτῇ καλῶν· καὶ πρὸς τοῦτο ἢ ἀναισθήτως ἔχειν, καὶ διὰ τοῦτο μᾶλλον ἐπιτείνειν τὸ κακόν, ἢ εἰς αἴσθησιν τῶν εἰργασμένων ὑπὸ τῆς συνειδήσεως ἑλκόμενον στρεβλοῦσθαι τὴν ψυχήν, καὶ δειμαίνειν τὰ ἐν ᾅδου κολαστήρια· καὶ μόνην ἴασιν ἐξευρίσκειν τὴν εἰς τὸ μὴ εἶναι καταφυγήν, ὅθεν αὐτῷ παρίσταται κακῷ τὸ κακὸν ἰᾶσθαι, φθορᾷ τῆς ψυχῆς τὴν κακίαν παραμυθουμένῳ, καὶ τὴν μετὰ θάνατον οὐδένειαν ἑαυτοῦ καταψηφίζεσθαι φυγῇ τῶν τῆς κρίσεως πόνων; Οὐ βούλεται γὰρ ὁ κακὸς ἀθάνατον εἶναι τὴν αὑτοῦ ψυχήν, ἵνα μὴ ὑπομείνῃ τιμωρούμενος. Καὶ φθάνει τὸν ἐκεῖ δικαστήν, θάνατον ἑαυτοῦ παντελῆ καταψηφιζόμενος, ὡς πρέπον τὴν πονηρὰν ψυχὴν μηδὲ εἶναι. Ἀλλ' οὗτος μέν, ὡς ἀβουλίᾳ πρὸς κακίαν ὑπενεχθείς, εἰκότως ἀμετρίᾳ τὴν καθ' ἑαυτοῦ ψῆφον ἐκφέρει· οἱ δὲ ἐν ᾅδου δικασταί, ἅτε πρὸς τὸν τῆς ἀληθείας κανόνα τὴν κρίσιν ποιούμενοι, οὐ κρίνουσι μὴ εἶναι δεῖν τὴν ψυχήν, ἀλλὰ πονηρὰν μὴ εἶναι, καὶ ὅπως ἂν μετριάσῃ τὸ κακὸν αὐτῆς πραγματεύονται, ἐπὶ σωτηρίᾳ τῆς φύσεως τὰς κολάσεις ἐπάγοντες, ἰατροῦ δίκην, τομαῖς τε καὶ καύσεσι τὰ χειρώνεια ἕλκη θεραπεύοντες· καὶ τῶν ἡμαρτημένων δίκας εἰσπράττοντες, μετανοίᾳ ψυχῆς τὴν πονηρίαν ἀφανίζειν πειρώμενοι· οὐκ αὐτὴν τὴν οὐσίαν ἐξιστάντες τοῦ εἶναι, ἀλλ' εἰς τὸ εἶναι μᾶλλον ἐπανάγοντες τῇ τῶν λυμαινομένων παθῶν ἐκκαθάρσει. Κινδυνεύει γὰρ εἰς τὸ μὴ εἶναι ὑποφέρεσθαι ἡ ἀνθρωπίνη ψυχὴ διὰ τῆς εἰς τὸ παρὰ φύσιν ἐκτροπῆς, τῇ δὲ εἰς τὸ κατὰ φύσιν ἀνακλήσει πρὸς τὴν οὐσίαν τὴν αὐτῆς ἐπανάγεται, καὶ ἀπολαμβάνει καθαρὸν τὸ εἶναι, ὃ τῇ συμμίξει τῶν παθῶν ἐκηραίνετο.", "st": "14.4"}, {"sp": "N", "t": "Διὸ πειρᾶσθαι δεῖ μάλιστα μὲν μὴ ἁμαρτάνειν, ἁμαρτόντας δὲ σπεύδειν ὡς ἐπὶ ἰατρικὴν τῆς πονηρίας τὴν δίκην, ἐπανορθουμένους τὴν ἀβουλίαν τῇ κρείττονι βοηθείᾳ. Ἐπεὶ γὰρ τοῦ εἶναι ἀγαθοὶ ἐκπεπτώκαμεν, τοῦ γίνεσθαι γοῦν ἀντιλαβώμεθα μεταμελείᾳ εὐγνώμονι τὴν θείαν ἐπανόρθωσιν εἰσδεχόμενοι. Ἡ δὲ μετάνοια αὕτη φιλοσοφίας ἀρχὴ γίνεται, καὶ τῶν ἀνοήτων ἔργων τε καὶ λόγων φυγή, καὶ τῆς ἀμεταμελήτου ζωῆς ἡ πρώτη παρασκευή.", "st": "14.5"}, {"sp": "N", "t": "Ὁ γὰρ καλῶς πρὸ τῶν πράξεων βουλευόμενος οὐ περιπίπτει λύπαις ἀκουσίαις, οὐδὲ λανθάνει τὰς ἀρχὰς καὶ τὰς ὑποθέσεις διδούς, ὧν τὰ συμπεράσματα καὶ τὰς ἐκβάσεις οὐκ ἀσμενίζει, ἀλλ' ἀεὶ τὸ παρὸν συντίθησι, τῶν ἄλλως ἐπισυμβαινόντων τὰς τύχας ἐκλογιζόμενος. Διὸ οὔτε προσδοκίᾳ τῶν λεγομένων ἀγαθῶν τὸ ὄντως ἀγαθὸν ἂν παρίδοι, οὔτε φόβῳ τῶν ἐναντίων τὴν τοῦ κακοῦ πρᾶξιν αἱρήσεται· ἑστώσῃ δὲ τῇ γνώμῃ πρὸς τοὺς θείους κανόνας τὸν ἑαυτοῦ βίον ἀπευθύνει.", "st": "14.6"}, {"sp": "N", "t": "Ἵνα δὲ γνῷς ὅτι δειλοῦ πρὸς ἀνδρός ἐστι πράσσειν τε καὶ λέγειν ἀνόητα, ὅρα Μήδειαν τὴν ἐν τῇ τραγῳδίᾳ τὰ καθ' αὑτὴν ὀδυρομένην· ἥτις ἀβουλήτως τοὺς οἰκειοτάτους προδοῦσα δι' ἔρωτα ἔκτοπον ἀνδρὶ ξένῳ ἑαυτὴν ἐνεχείρισεν· ἔπειτα ὀλιγωρουμένη ὑπὸ τούτου, ἀφόρητα πάσχειν οἴεται· καὶ ἐκ τῆς οἰήσεως ταύτης ἀκούεις οἷα βοᾷ·", "st": "14.7"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">[αἰαῖ· διά μου κεφαλᾶς φλὸξ οὐρανία<br>βαίη· τί δέ μοι ζῆν ἔτι κέρδος;]<\/span><\/span>", "st": "14.8"}, {"sp": "N", "t": "καὶ πρόεισιν εἰς ἔργα παράνομα· πρῶτον ἀνοήτως ἐπευχομένη μὴ γεγενῆσθαι τὰ γενόμενα, εἶτα μανικῶς κακοῖς ἰᾶσθαι τὰ κακὰ πειρωμένη τὴν τῆς ἀβουλίας ἀρχὴν ἐξαλείφειν οἴεται τέλει χείρονι, παιδοκτονίᾳ προπετεῖ τὴν ἄβουλον παιδοποιΐαν ἀρνουμένη. Εἰ δὲ βούλει, τὸν Ἀγαμέμνονα θέασαι τὸν Ὁμήρου, ὃς τῆς ἀμετρίας τοῦ θυμοῦ διδοὺς δίκας οἰμώζων ἀναφωνεῖ·", "st": "14.9"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">[οὐδέ μοι ἦτορ<br>ἔμπεδον, ἀλλ' ἀλαλύκτημαι, κραδίη δέ μοι ἔξω<br>στηθέων ἐκθρῴσκει, τρομέει δ' ὑπὸ φαίδιμα γυῖα.]<\/span><\/span>", "st": "14.10"}, {"sp": "N", "t": "Καὶ τὸ πυρῶδες τῶν ὀμμάτων, ὃ πάλαι ὑπὸ τῆς θυμικῆς διαθέσεως ἐξήπτετο, μεταπεσόντων αὐτῷ τῶν πραγμάτων, τοῖς τῶν δακρύων ὄμβροις κατέψυχε. Τοιοῦτος γὰρ πᾶς ἀνόητος βίος, τῇδε κἀκεῖσε τοῖς ἐναντίοις πάθεσι μεταπίπτων, ἐν ἡδοναῖς μέν ἐστι μισητός, ἐν δὲ λύπαις ἐλεεινός, καὶ θαρρῶν προπετής, καὶ δεδιὼς ταπεινός· καὶ ὅλως τοῦ τῆς εὐβουλίας γενναίου φρονήματος ἀμοιρῶν τῇ τύχῃ συμμεταβάλλει τὴν γνώμην.", "st": "14.11"}, {"sp": "N", "t": "Ἵνα οὖν μὴ τοιούτων δραμάτων ἀναπιμπλώμεθα, πράσσοντες καὶ λέγοντες ἀνόητα, τῷ ὀρθῷ λογισμῷ διὰ πάντων ἡγεμόνι χρησώμεθα, τὸ Σωκρατικὸν ἐκεῖνο πληροῦντες, „ὡς ἐγὼ οὐδενὶ οἷός τέ εἰμι πείθεσθαι τῶν ἐμῶν, πλὴν τῷ λόγῳ, ὃς ἄν μοι λογιζομένῳ ὀρθὸς φαίνηται.” Ἡμῶν δέ ἐστιν, ἀλλ' οὐχ ἡμεῖς, πάντα ὅσα πρὸς ὑπηρεσίαν τῇ λογικῇ οὐσίᾳ δέδοται, οἷον θυμός, ἐπιθυμία, αἴσθησις, αὐτὸ τὸ σῶμα, τὸ εἰς ὀργάνου χρείαν ταῖς δυνάμεσι ταύταις παρειλημμένον· ὧν οὐδενὶ χρὴ πείθεσθαι, πλήν, ὥς φησι, τῷ ὀρθῷ λόγῳ, τουτέστι τῷ λογικῷ κατὰ φύσιν διατεθέντι. Τοῦτο γὰρ καὶ διορᾶν δύναται ἃ λεκτέα τε καὶ πρακτέα. Λόγῳ δὲ ὀρθῷ πείθεσθαι καὶ Θεῷ, ταὐτόν ἐστι. Τὸ γὰρ λογικὸν γένος εὐμοιρῆσαν τῆς οἰκείας ἐλλάμψεως ταῦτα βούλεται ἃ ὁ θεῖος ὁρίζει νόμος· καὶ γίνεται σύμψηφος Θεῷ ἡ κατὰ Θεὸν διακειμένη ψυχή, καὶ πρὸς τὸ θεῖον καὶ τὸ λαμπρὸν ἀποβλέπουσα πράττει ἃ ἂν πράττῃ. Ἡ δὲ ἐναντίως διακειμένη πρὸς τὸ ἄθεον καὶ σκοτεινὸν εἰκῆ καὶ ὡς ἔτυχε φερομένη, ἅτε τῆς μόνης τῶν καλῶν στάθμης, νοῦ καὶ Θεοῦ, ἀποπεσοῦσα, πλανᾶται.", "st": "14.12"}, {"sp": "N", "t": "Τοσαῦτα μὲν καὶ τοιαῦτα τῆς εὐβουλίας τὰ ἀγαθά, καὶ τῆς ἐναντίας διαθέσεως τὰ κακά. Τὸ δὲ βουλεύεσθαι πρὸ ἔργου, πρὸς τοῖς ἄλλοις ἀγαθοῖς, καὶ τῆς οἰήσεως ἐκκόπτει τὰς ἀφορμάς, καὶ πρὸς ἐπιστήμης ἀνάληψιν παρακαλεῖ, καὶ τὸν ἥδιστον ἡμῖν προξενεῖ βίον, εἴπερ καὶ τὸν ἄριστον· δηλοῦται δὲ ταῦτα διὰ τῶν ἑξῆς.", "st": "14.13"}, {"sp": "SEC", "t": "XV · 30–31", "st": "15"}, {"sp": "N", "t": "<span class=\"lemma\">Πρῆσσε δὲ μηδὲν τῶν μὴ ἐπίστασαι, ἀλλὰ διδάσκευ<br>ὅσσα χρεών, καὶ τερπνότατον βίον ὧδε διάξεις.<\/span>", "st": "15.0"}, {"sp": "N", "t": "Τὸ μὲν μὴ ἐγχειρεῖν οἷς οὐκ ἴσμεν, ἀναμαρτήτους ἡμᾶς διαφυλάττει μόνον· τὸ δὲ διδάσκεσθαι τὰ πρὸς τὴν ἀρίστην ζωὴν συντείνοντα, πρὸς τῷ ἀναμαρτήτῳ, καὶ τὴν κατόρθωσιν ἐν ταῖς πράξεσιν ἡμῖν παρέχεται. Ἡ μὲν γὰρ σύνεσις τῆς ἀγνοίας τὴν ἐκ τῆς οἰήσεως ἐγειρομένην προπέτειαν ἐκκόπτει· ἡ δὲ τῆς ἐπιστήμης κτῆσις τὸ τῶν ἐνεργειῶν ἀπαρεμπόδιστον δίδωσιν. Ἀμφότερα δὲ καλά, καὶ τὸ εἰδέναι ὅτι οὐκ ἴσμεν, καὶ τὸ γνῶναι ἃ οὐκ ἴσμεν· οἷς ἕπεται βίος ὁ ἄριστος ἅμα καὶ ἥδιστος. Οὗτος δέ ἐστιν ὁ οἰήσεως μὲν καθαρεύων, ἐπιστήμης δὲ πλήρης· ἐπὶ μηδενὶ μὲν ἐπαιρόμενος ὧν οὐκ οἶδε, μανθάνειν δὲ ἐθέλων ὅσα ἄξια μαθήσεως.", "st": "15.1"}, {"sp": "N", "t": "Ἄξια δὲ ἐκεῖνα μόνα, ὅσα πρὸς τὴν θείαν ὁμοίωσιν ἡμᾶς ἀνάγει· ὅσα ποιεῖ βουλεύεσθαι πρὸ ἔργου, ὅπως μὴ μῶρα πέληται· ὅσα οὐκ ἐᾷ παράγεσθαι ὑπ' οὐδενὸς οὔτε λόγῳ, οὔτε ἔργῳ· ὅσα διακρίνειν ἱκανοὺς ποιεῖ τῶν προσπιπτόντων λόγων τὸ διάφορον· ὅσα τὰς δαιμονίας τύχας πράως φέρειν καὶ ἰᾶσθαι πείθει, καὶ τὴν θανάτου καὶ πενίας ἀφοβίαν διδάσκει, καὶ δικαιοσύνης ἄσκησιν, καὶ γαστρὸς καὶ τῶν περὶ τὴν γαστέρα τὴν ἐγκράτειαν· ὅσα τοὺς τῆς φιλίας νόμους εἰσηγεῖται, καὶ τὴν γονέων τιμήν· ὅσα τῶν κρειττόνων γενῶν τὸ σέβας ὑποδείκνυσι. Ταῦτα καὶ τὰ τοιαῦτά ἐστιν, ἃ διδάσκεσθαι χρῆναί φησιν ὁ παρὼν λόγος, οἷς ἕπεται βίος ὁ τερπνότατος.", "st": "15.2"}, {"sp": "N", "t": "Ὁ γὰρ ἀρετῇ διαπρέπων καὶ ἡδονὰς ἀμεταμελήτους καρποῦται μιμουμένας τὸ τῆς ἀρετῆς μόνιμον. Πέφυκε γὰρ πᾶσα ἡδονὴ ἐνεργείας ἡστινοσοῦν εἶναι παρακολούθημα. Οὐ γὰρ αὐτὴ καθ' ἑαυτὴν τὴν ὑπόστασιν ἔχει, ἀλλ' ἐπακολουθεῖ τάδε ποιοῦσιν ἡμῖν ἢ τάδε. Διὸ ταῖς μὲν φαυλοτέραις τῶν ἐνεργειῶν αἱ χείρους τῶν ἡδονῶν ἕπονται, ταῖς δὲ ἀμείνοσιν ἡδοναὶ συνεισέρχονται σπουδαῖαι· ὥστε μὴ μόνῳ τῷ καλῷ περιεῖναι τὸν σπουδαῖον τοῦ φαύλου, ἀλλὰ καὶ αὐτῇ τῇ ἡδονῇ νικᾶν, δι' ἣν μόνην δοκεῖ εἰς κακίαν ὁ φαῦλος ὑπάγεσθαι. Καὶ γὰρ ὅσῳ ἡ διάθεσις τῆς διαθέσεως ἀμείνων, τοσούτῳ καὶ ἡ ἡδονὴ τῆς ἡδονῆς αἱρετωτέρα. Ἐπεὶ οὖν ὁ κατ' ἀρετὴν βίος, τῆς θείας ὁμοιώσεως ἀντεχόμενος, τῷ ὄντι θεῖός ἐστιν, ὁ δὲ ἐν κακίᾳ, θηριώδης καὶ ἄθεος· δῆλον, ὡς ἡ μὲν τοῦ σπουδαίου ἡδονὴ τὴν θείαν εὐφροσύνην μιμεῖται νῷ καὶ Θεῷ συνεπομένη, ἡ δὲ τοῦ φαύλου ἡδονὴ λεγομένη (δεδόσθω γὰρ κοινὸν τὸ ὄνομα) πρὸς τὴν θηριώδη καὶ ἔμπληκτον ὁμοιοῦται κίνησιν. Ἡδοναὶ γὰρ καὶ λῦπαι μεθιστᾶσιν· ὧν ὁ μὲν ἀρυόμενος, ὅθεν τε δεῖ, καὶ ὁπότε, καὶ ὁπόσον, εὐδαιμονεῖ· ὁ δὲ τὰ μέτρα τούτων ἀγνοήσας, ἄθλιος.", "st": "15.3"}, {"sp": "N", "t": "Οὕτως οὖν ὁ μὲν οἰήσεως καθαρεύων βίος ἀναμάρτητός ἐστι μόνος· ὁ δὲ καὶ ἐπιστήμης πληρωθείς, κατωρθωμένος καὶ τέλειος· ὁ δ' αὐτὸς ἥδιστός τε ἅμα καὶ ἄριστος. Οὐκοῦν ἃ μὲν μὴ ἴσμεν οὐδέποτε πράξομεν· ἃ δὲ ἴσμεν, ὅτε δεῖ. Ἡ μὲν γὰρ ἄγνοια τὴν κακίαν εἰσηγεῖται, ἡ δὲ γνῶσις τὴν εὐκαιρίαν ζητεῖ. Πολλὰ γὰρ ὄντα σπουδαῖα τῇ μεταθέσει τοῦ καιροῦ γίνεται φαῦλα. Ἐν τάξει οὖν ἀκούσωμεν τοῦ παραγγέλματος, ἐκ μὲν τῆς ἐποχῆς τῶν πράξεων τὸ ἀναμάρτητον ἡμῖν εἰσηγουμένου, ἐκ δὲ τῆς προτροπῆς τοῦ μανθάνειν οὐ πάντα, ἀλλ' ὅσα δεῖ, πρὸς τὰς ἀρίστας πράξεις ἡμᾶς ἐπανάγοντος. Οὐ γὰρ ἐν τῷ μὴ ἁμαρτάνειν ἐστὶ τὸ κατορθοῦν, ἀλλ' ἐν τῷ τὰ δέοντα εἰδέναι· καὶ τὸ μὲν ἡ κάθαρσις τῆς οἰήσεως, τὸ δὲ ἡ τῆς ἐπιστήμης παρουσία, ἐργάζεται. Ἐν δὲ τῷ μὴ ἁμαρτάνειν, καὶ ἐν τῷ κατορθοῦν, ὅρα τί συμβήσεταί σοι· τερπνότατον βίον ὧδε διάξεις.", "st": "15.4"}, {"sp": "N", "t": "Τίς δὲ οὗτος, εἰ μὴ μόνος ὁ ἀπὸ τῆς ἀρετῆς τὸ ἡδὺ κεκτημένος, ᾧ συνδεδράμηκεν ἅμα τὸ ἀγαθόν, καὶ τὸ ἡδύ; Εἰ οὖν ποθοῦμεν τὸ καλόν, ποθοῦμεν δὲ καὶ τὸ ἡδύ· συνελθόντα τί ἂν εἴη; τοῦτο, ὅ φησιν, ὁ βίος τερπνότατος. Ὁ γὰρ τὸ ἡδὺ μετὰ τοῦ αἰσχροῦ ἑλόμενος, εἰ καὶ πρὸς ὀλίγον δελεασθείη τῷ ἥδοντι, διὰ γοῦν τὸ αἰσχρὸν εἰς μεταμέλειαν ἐπώδυνον ἔρχεται. Ὁ δὲ τὸ καλὸν μετὰ πόνου προτιμήσας, κἂν παραυτίκα τῷ ἀήθει βαρύνηται, ἀλλ' ἡ τοῦ καλοῦ σύζευξις ἐπελαφρύνει τὸν πόνον, καὶ τέλος πρὸς τῇ ἀρετῇ καὶ ἡδονὴν καθαρὰν καρποῦται. Εἰ μὲν γὰρ πράττοιτό τι μεθ' ἡδονῆς αἰσχρόν, ἡ μὲν ἡδονὴ παρῆλθε, τὸ δὲ αἰσχρὸν μένει· εἰ δὲ πράττοιτό τι μετὰ πόνου καλόν, ὁ μὲν πόνος παρῆλθε, τὸ δὲ καλὸν μένει. Ἐξ ὧν λυπηρότατον ἀνάγκη εἶναι τὸν κάκιστον βίον· τερπνότατον δέ, τὸν ἄριστον.", "st": "15.5"}, {"sp": "N", "t": "Καὶ ταῦτα μὲν περὶ τούτων. Ἐπεὶ δὲ καὶ ἡ τοῦ σώματος παιδαγωγία πρὸς τὴν τῆς ψυχῆς τελείωσιν τὴν ἀναφορὰν ἔχει, ὅρα ἑξῆς τί ἐπάγει·", "st": "15.6"}, {"sp": "SEC", "t": "XVI · 32–34", "st": "16"}, {"sp": "N", "t": "<span class=\"lemma\">Οὐδ' ὑγιείης τῆς περὶ σῶμ' ἀμέλειαν ἔχειν χρή·<br>ἀλλὰ ποτοῦ τε μέτρον καὶ σίτου γυμνασίων τε<br>ποιεῖσθαι· μέτρον δὲ λέγω τόδ', ὃ μή σ' ἀνιήσει.<\/span>", "st": "16.0"}, {"sp": "N", "t": "Τὸ θνητὸν σῶμα, πρὸς τὴν ἐπὶ γῆς διαγωγὴν ὄργανον ἡμῖν δοθέν, οὔτε πιαίνειν προσήκει ταῖς ἀμέτροις σωμασκίαις, οὔτε κατατρύχειν ἐνδείας ὑπερβολαῖς. Ἐμπόδιον γὰρ ἐπίσης ἑκάτερον, καὶ ἀναιρετικὸν τῆς χρείας αὐτοῦ προσγέγονε. Διὸ μετρίως θεραπεύειν αὐτό, καὶ μὴ περιορᾶν ἐξυβρίζον, ἢ ὑπὸ νοσημάτων ἐνοχλούμενον, ὁ λόγος παραινεῖ· ὅπως ἂν ἐν τῷ κατὰ φύσιν σωζόμενον ἀπαραποδίστως τῇ ἡγουμένῃ ψυχῇ τὰς ἐνεργείας αὐτοῦ παρέχηται, ταύτῃ δυνάμενον ἄγεσθαι, ᾗ ἂν ἐκείνη ἄγῃ.", "st": "16.1"}, {"sp": "N", "t": "Τὸ γὰρ χρώμενον ἡ ψυχή, τὸ δὲ ᾧ χρῆται, τὸ σῶμα, οὗ τὴν ἐπιμέλειαν ἔχειν δεῖ τὸν τεχνίτην. Οὐ γὰρ χρῆσθαι δεῖ μόνον ἐθέλειν αὐτῷ, ἀλλὰ καὶ ὅπως εὖ ἔχον ἡμῖν ὑπηρετῆται, τὴν ἐνδεχομένην ποιεῖσθαι πρόνοιαν. Ἐπεὶ δὲ ἡ φύσις αὐτοῦ ἐν γενέσει καὶ φθορᾷ συνεχεῖ καθέστηκε, καὶ πλήρωσις καὶ κένωσις αὐτὸ τιθηνοῦσι, νῦν μὲν τροφῆς τὸ ἀπορρέον ἀναπληρούσης, νῦν δὲ γυμνασίων τὸ πλεονάζον ὑπεξαιρούντων· μέτρον ἐπιστῆσαι δεῖ τῇ τῶν εἰσαγομένων πληρώσει, καὶ τῇ τῶν διαφορούντων κενώσει. Τὸ δὲ μέτρον ἐστὶν ὁ λόγος ὁ συναρμόζων τὴν τοῦ σώματος ἕξιν ταῖς διανοητικαῖς ἐνεργείαις τῆς ψυχῆς, καὶ διὰ τοῦτο τῆς τῷ φιλοσόφῳ πρεπούσης ὑγιείας ἐπιμελούμενος. Οὗτος οὖν γυμνάσια καὶ τροφὰς ἐκλέξεται, ἃ ἂν μὴ πιαίνῃ πρὸς ὑπερβολὴν τὸ σῶμα, μηδ' ὑπέρτερον αὐτὸ τῶν νοερῶν κινήσεων ἀπεργάζηται. Οὐ γὰρ σώματος ἁπλῶς ἐπιμελεῖται, ἀλλὰ σώματος διανοίᾳ ὑπηρετουμένου. Ὅθεν τὴν ἀθλητικὴν ἀγωγὴν παραιτήσεται, ὡς ἄνευ ψυχῆς σῶμα θεραπεύουσαν· καὶ πᾶσαν τὴν λεγομένην σωμασκίαν φεύξεται, ὡς ἐπανισταμένην τῷ νοερῷ φωτὶ τῆς ψυχῆς. Ὅση δὲ τῇ περὶ τὰ μαθήματα θεωρίᾳ καὶ τῇ περὶ τὰς καλὰς πράξεις αὐτουργίᾳ ὑπηρετεῖσθαι δύναται τῇ τοῦ σώματος εὐεξίᾳ, ταύτην περιποιήσει ἑαυτῷ ὁ τὸν τοῦ φρονεῖν βίον ἑλόμενος.", "st": "16.2"}, {"sp": "N", "t": "Πρὸς τοῦτον γὰρ εἴρηται τό, μέτρον δὲ λέγω τόδ', ὃ μή σ' ἀνιήσει. Σέ, φησί, τὸν ὄντα λογικὴν ψυχήν, μὴ βλαπτέτω τὸ μέτρον τῆς τοῦ σώματος ἐπιμελείας· σέ, τὸν τῶν προτέρων παραγγελμάτων φύλακα, τοιαῦτα σιτία, καὶ ποτά, καὶ γυμνάσια, ἐκλέγεσθαι χρή, ἃ τὸ σῶμα πειθήνιον πρὸς τὴν τῶν ἀρετῶν χρῆσιν ἀπεργάζεται, ἃ μὴ ἐκφέρει τὸ ἄλογον πρὸς ἀφηνίασιν τοῦ ἡγεμονοῦντος λόγου. Μετὰ πλείστης δὲ προσοχῆς ποιεῖσθαί σε δεῖ τὴν παραμέτρησιν τῆς ἐπιμελείας τοῦ σώματος, ὡς καὶ τῶν τούτου παραλόγων κινημάτων τὴν αἰτίαν ὑφέξοντα. Βρίθει γὰρ ὁ τῆς κακίας μετέχων ἵππος, οὐχ ἁπλῶς, ἀλλ' ὅτε μὴ καλῶς εἴη τεθραμμένος ὑπὸ τῶν ἡνιόχων.", "st": "16.3"}, {"sp": "N", "t": "Ἐν δὲ τῷ μέτρῳ, τῷ περὶ τὸ σῶμα, τὸ ποτὸν τοῦ σιτίου προέταξεν, ὅτι μᾶλλόν ἐστι δυσφύλακτον, καὶ εὐόλισθον εἰς κατάποσιν, καὶ παρακινητικὸν τῆς τοῦ σώματος εὐεξίας. Λάθοι γὰρ ἄν τις πολλαπλάσια τοῦ μέτρου πιὼν μᾶλλον ἢ φαγών. Τὰ δὲ γυμνάσια τρίτα τέτακται, ὡς ἐπανορθούμενα τὴν ἀπὸ τῆς τροφῆς πλήρωσιν, καὶ πάλιν πρὸς τὸ ὑγιεινῶς τρέφεσθαι παρασκευάζοντα. Κύκλῳ γὰρ οἷον ἀνταποδίδοται ταῦτα ἀλλήλοις, τροφὴ καὶ γυμνάσιον, καὶ γυμνάσιον καὶ τροφή. Χορηγία γὰρ τοῦ μὲν δύνασθαι γυμνάζεσθαι τὸ εὖ τεθράφθαι, τοῦ δὲ εὐεκτικῶς τρέφεσθαι τὸ γεγυμνάσθαι συμμέτρως. Μέτρον δὲ τούτων ἄλλο ἄλλῳ, πρὸς τὸ οἰκεῖον ἐπιτήδευμα τῆς τοῦ σώματος ἐπιμελείας ἑκάστῳ τεινούσης. Πᾶς γὰρ τῆς ἑαυτοῦ προαιρέσεως ὄργανον αὐτὸ ποιεῖσθαι σπουδάζει· ὁ μὲν παλαιστρικὸς τῶν περὶ πάλην κινημάτων· ὁ δὲ γεωργικὸς τῶν περὶ γεωργίαν πόνων· καὶ ἄλλος πρὸς ἄλλο ἕλκει καὶ μεθαρμόζεται τὴν τοῦ σώματος ὑπουργίαν.", "st": "16.4"}, {"sp": "N", "t": "Τί οὖν ὁ φιλόσοφος; Πρὸς τί βλέπων ἐθελήσει τὸ σῶμα παιδαγωγεῖν; καὶ τίνος ὄργανον αὐτὸ σπουδάσει ποιήσασθαι, ἢ δῆλον ὅτι φιλοσοφίας καὶ τῶν ταύτης ἔργων; Ὡς οὖν οἷόν τε φρονήσεως ὄργανον γενέσθαι τὸ σῶμα, οὕτως αὐτὸ διὰ πάντων θρέψει τε καὶ παιδεύσει, ψυχῆς μὲν προηγουμένως ἐπιμελούμενος, διὰ ταύτην δὲ καὶ τοῦ σώματος. Οὔτε γὰρ προτιμήσει αὐτὸ τῆς χρωμένης, οὔτε παντελῶς ἀμελήσει αὐτοῦ πάλιν διὰ τὴν χρωμένην· ἀλλ' ἐν τάξει τῇ πρεπούσῃ ὡς ὀργάνου ποιήσεται τὴν ἐπιμέλειαν, πρὸς τὴν τοῦ χρωμένου ἀρετὴν καὶ τὴν τοῦ σώματος ὑγίειαν ἀναφέρων. Διὸ οὐ πανταχόθεν αὐτὸ θρέψει, ἀλλ' ἀφ' ὧν δεῖ μόνων. Ἔστι γὰρ ἃ μὴ δεῖ προσφέρεσθαι, ὡς βαρύνοντα τὸ σῶμα, καὶ καθέλκοντα τὸ συμφυὲς πνεῦμα τῆς ψυχῆς πρὸς ὑλικωτέρας ἐμπαθείας· περὶ ὧν ὕστερον ὁ λόγος φησίν·", "st": "16.5"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Ἀλλ' εἴργου βρωτῶν, ὧν εἴπομεν, ἔν τε καθαρμοῖς,<br>ἔν τε λύσει ψυχῆς κρίνων.<\/span><\/span>", "st": "16.6"}, {"sp": "N", "t": "Τὰ τοιαῦτα οὖν παντελῶς παραιτήσεται· ὧν δὲ ἐξὸν προσφέρεσθαι τὴν ποσότητα καὶ τὸν καιρὸν μετρήσει, καί, ὥς φησιν Ἱπποκράτης, ὥρην, καὶ χώρην, καὶ ἡλικίην περιεργάσεται, καὶ πάντα ὅσα τοῦ τοιούτου τύπου· οὐκ ἀνεξετάστως ἐπιτρέπων ἐμπίπλασθαι ὧν ἐξὸν μεταλαμβάνειν, οὐδ' ἀκρίτως νέον καὶ πρεσβύτην ὁμοίως διαιτᾶσθαι, ἢ ὑγιεινὸν καὶ νοσώδη, ἢ ἀρχόμενον φιλοσοφίας καὶ εἰς ἄκρον αὐτῆς ἥκοντα.", "st": "16.7"}, {"sp": "N", "t": "Ταῦτα δὲ πάντα συνείληφε τὸ Πυθαγορικὸν μέτρον, τῇ προσθήκῃ τοῦ, ὃ μή σ' ἀνιήσει. Πάντα γὰρ εἰς τὴν φιλόσοφον εὐζωΐαν συντείνοντα πρὸς τὴν τοῦ σώματος ἐπιμέλειαν ἐπέτρεψε τῷ βραχεῖ τούτῳ ῥήματι· καὶ τοῖς προειρημένοις περὶ ὑγιείας ψυχῆς ἐπήγαγεν, οὐδ' ὑγιείης τῆς περὶ σῶμ' ἀμέλειαν ἔχειν χρή· ὡς ἐκεῖ μὲν τὴν τοῦ χρωμένου ἀρετὴν παραδίδοσθαι, ἐνταῦθα δὲ τὴν τοῦ ὀργάνου σωτηρίαν. Σύναψον οὖν ταῦτα ἐκείνοις, καὶ εὑρήσεις, ὅστις εἶ ᾧ παραγγέλλεται, τοιοῦτο δεῖν ποιεῖσθαι τὸ μέτρον τῆς περὶ τὸ σῶμα τάξεως, ὃ μή σ' ἀνιήσει, ὃ μὴ ἐμποδιεῖ τὴν φιλόσοφον πρόθεσιν, ἀλλ' ἐπωφελήσει τῇ συνεργίᾳ τὴν πρὸς ἀρετὴν ὁδεύουσαν ψυχήν. Ποτοῦ δὲ καὶ σίτου μέτρον εἶπε, τὰς ὑπερβολὰς καὶ τὰς ἐλλείψεις ἀπαγορεύων ὁ λόγος, τὸ δὲ μέσον καὶ σύμμετρον ἀσπαζόμενος· ὅθεν καὶ τὸ γαστρὸς κρατεῖν καὶ ὕπνου λαγνείης τε καὶ θυμοῦ εὐκόλως παραγίνεται. Τὸ γὰρ νῦν λεγόμενον μέτρον τὴν ἐν ἐκείνοις ἀμετρίαν κολάζει, καὶ ὑπεξαιρεῖται τὸ λυποῦν καὶ καθέλκον τὴν πρὸς νοῦν καὶ θεὸν ἐπειγομένην ψυχήν. Δεῖ γὰρ αὐτὴν ἀνιοῦσαν πρὸς νοῦν γαλήνην ἔχειν ἀπὸ τῶν παθητικῶν κινημάτων, καὶ τετάχθαι αὐτῇ τὰ κάτω καλῶς πρὸς τὸ ἀθόρυβον τῆς τῶν ἄνωθεν θεωρίας. Τοῦτο ἦν τὸ μέτρον, ὃ μή σ' ἀνιήσει· τοῦτο τὸ κρατοῦν γαστρὸς ἅμα, καὶ τὴν τοῦ ὀργάνου σωτηρίαν ποιούμενον, τὸ ἀρετὴν ψυχῆς ἐπιδεικνύμενον, καὶ τὴν τοῦ σώματος ἕξιν μὴ καταλῦον. Μέρος γὰρ ἀρετῆς ἐστι καὶ τὸ εἰδέναι σῴζειν τὸ ὄργανον, καὶ συναρμόζειν αὐτὸ πρὸς τὴν φιλόσοφον χρῆσιν.", "st": "16.8"}, {"sp": "N", "t": "Ἐπεὶ δὲ οὐ μόνον ἐν τροφαῖς καὶ γυμνασίοις ἐστὶν ἡ τοῦ σώματος θεραπεία, ἀλλὰ καὶ ἄλλων πολλῶν προσδεῖται, οἷον ἱματίων, ὑποδημάτων, σκευῶν παντοδαπῶν, καὶ τῆς ταῦτα ὑποδεχομένης οἰκίας, δεῖ δὲ καὶ ἐν τούτοις τοῦ μετρίου, ὃ τρυφήν τε καὶ ἀκαθαρσίαν ἐξορίζει τῆς ὅλης ἡμῶν διαίτης· εἰκότως ἐπήγαγεν·", "st": "16.9"}, {"sp": "SEC", "t": "XVII · 35–38", "st": "17"}, {"sp": "N", "t": "<span class=\"lemma\">εἰθίζου δὲ δίαιταν ἔχειν καθάρειον, ἄθρυπτον·<br>καὶ πεφύλαξό γε ταῦτα ποιεῖν ὁπόσα φθόνον ἴσχει.<br>μὴ δαπανᾶν παρὰ καιρόν, ὁποῖα καλῶν ἀδαήμων·<br>μηδ' ἀνελεύθερος ἴσθι· μέτρον δ' ἐπὶ πᾶσιν ἄριστον.<\/span>", "st": "17.0"}, {"sp": "N", "t": "Οὐ μόνον, φησίν, ἐν σιτίοις καὶ ποτοῖς τὸ μέτρον καλόν, ἀλλὰ καὶ ἐν τοῖς ἄλλοις ἅπασιν, ὡς τῶν δι' ὑπερβολὴν καὶ ἔλλειψιν ἁμαρτημάτων καθαρεῦον. Γένοιτο γὰρ ἂν ἐν πᾶσιν οἷς εἴπομεν ἀμετρία διπλῆ· ἡ μὲν πρὸς τὸ πολυτελὲς ἐξάγουσα, ἡ δὲ πρὸς τὸ ῥυπαρὸν συνωθοῦσα. Ἑκάτερον δὲ μεμπτὸν καὶ οὐ φιλόσοφον ἦθος, οὐδὲ στοχαζόμενον τῆς σωματικῆς εὐμετρίας. Ἐπιτεινομένη γὰρ καθαρειότης θρύψις καὶ βλακεία εὑρίσκεται· ἐπιτεινομένη δὲ λιτότης ἀκαθαρσία καὶ ῥύπος γίνεται. Ἵν' οὖν μήτε ἐκεῖνο πάθωμεν διὰ καθαρειότητα, μήτε τοῦτο διὰ λιτότητα, μέσοι βαίνωμεν, τὰς παρακειμένας ἑκατέρῳ κακίας ἐκκλίνοντες, καὶ τὸ ἕτερον τοῦ ἑτέρου σωφρονισμὸν ποιούμενοι· λιτὴν οὕτως ἐπιτηδεύοντες δίαιταν, ὡς μὴ ἀκάθαρτον, καὶ καθάρειον οὕτως, ὡς μὴ τρυφηλήν. Διὸ τὸ μέτρον προτιμήσωμεν ἐν πάσῃ τῇ περὶ τὸ σῶμα κατασκευῇ, ἱμάτιον ἐκλεγόμενοι καθάρειον, ἄθρυπτον· οἶκον ὁμοίως καθάρειον, ἄθρυπτον· καὶ πᾶν ὁτιοῦν τῶν περὶ τὸ σῶμα καθάρειον, ἄθρυπτον ἔχειν ἐθέλοντες. Πρέπει γάρ, λογικῆς ψυχῆς τοῦ σώματος ἡγουμένης, καὶ τὰ περὶ τὸ σῶμα πάντα συντετάχθαι πρὸς τὸν ἡγούμενον λόγον, ὅστις οὔτε τρυφῆς οὔτε ἀκαθαρσίας ἀνέξεται, τῇ κατ' αὐτὸν ἀξίᾳ πάντα λογιζόμενος δεῖν εἶναι σύμμετρα.", "st": "17.1"}, {"sp": "N", "t": "Ἵν' οὖν μὴ περιέλκοιτο πρὸς κτῆσιν τῶν πολυτελῶν, τὸ ἄθρυπτον ἐπιτηδεύει· ἵνα δὲ μὴ ῥύπῳ καὶ ὑλικῇ ἀμορφίᾳ συνοικοίη, τὸ καθάρειον ἐκλέγεται. Οἷον, ἱμάτιον οὐ λεπτὸν μέν, καθάρειον δέ· σκεύη οὐ χρυσᾶ, οὐδὲ ἀργυρᾶ, ἀλλ' ἐκ τῶν εὐπορίστων ὑλῶν καθάρεια· οἰκίαν οὐ πολυτελέσι λίθοις κατηνθισμένην, οὐδὲ περιττῶς εἰς κάλλος καὶ μέγεθος ἐξειργασμένην, ἀλλὰ σύμμετρον τῇ τοῦ σώματος χρείᾳ, καθάρειον δέ· καὶ ὅλως παρὰ πᾶσαν τὴν δίαιταν τὸ μὲν τρυφηλόν, ὡς ἔξω τῆς χρείας, ἀρνεῖται· τὸ δὲ καθάρειον, ὡς μάλιστα τὴν χρείαν ἀποπληροῦν, ἐγκρίνει. Καὶ γὰρ ἱμάτιον, καὶ οἶκος, καὶ σκεῦος ἅπαν, τότε τὴν αὑτοῦ χρείαν καλῶς παρέχεται, ὅταν σύμμετρον ᾖ καὶ καθάρειον. Τί γὰρ μεγάλου δεῖ πίνακος εἰς μικρὸν ὄψον; τί δὲ ῥυπαροῦ, μέλλοντος ἀφανιεῖν τὸ ὄψον; Οἴκου δὲ μεγάλου τί δεῖ τοῖς μέλλουσιν ἐν μιᾷ γωνίᾳ αὐτοῦ κεῖσθαι; τί δὲ ἀκαθάρτου, τὴν τῆς οἰκήσεως χρείαν οὐ παρέχοντος; Τὸ δὲ αὐτὸ καὶ ἐπὶ τῶν ἄλλων εὑρήσεις ἑκατέρωθεν ἄχρηστον ὄν, τὸ μὴ μετὰ τοῦ ἀτρύφου καθάρειον· ἅμα γὰρ ὑπερέβης τὸ μέτρον τῆς χρείας, καὶ εἰς τὸ ἄπειρον προῆλθες τῆς ἐπιθυμίας. Διὸ πάντα τὰ περὶ τὸν βίον μετρείσθω σοι ταῖς μεσότησι ταῖς διαφευγούσαις τὰς παρακειμένας κακίας.", "st": "17.2"}, {"sp": "N", "t": "Εἰθίζου δὲ δίαιταν ἔχειν, φησί, καθάρειον· εἶτα ὁρῶν τὴν εἰς τρυφὴν ἔκπτωσιν, προσέθηκεν ἄθρυπτον· καὶ εἰ ἄθρυπτον προειρήκει, εἶδεν ἂν καὶ τὴν εἰς ῥύπον ἀπόπτωσιν, καὶ ἐπήγαγε καθάρειον· ἀεὶ τοῦ πτώματος ἀνέχων τῇ τοῦ ἑτέρου πρὸς τὸ ἕτερον ἀντιθέσει, ἵν' ἐξ ἀμφοτέρων ἀνδρώδης ἡ δίαιτα ᾖ, καὶ λογικῷ ζῴῳ πρέπουσα.", "st": "17.3"}, {"sp": "N", "t": "Οὕτω δὲ τάξαντες τὸν βίον, καὶ ἄλλο τι ἑπόμενον μέγα ἀγαθὸν ἕξομεν. Τὸν γὰρ ἐπιφυόμενον τοῖς ὑπερβάλλουσι φθόνον διαφύγοιμεν ἄν, τῷ μηδὲν ἄγαν οὐ κινοῦντες καθ' ἡμῶν αὐτῶν τοὺς συμπολιτευομένους, ὥστε νῦν μὲν νεμεσᾶν, ὡς τρυφῶσιν ἡμῖν, νῦν δὲ μέμφεσθαι, ὡς ῥυπῶσι· καὶ ὁτὲ μὲν ὡς ἀσώτοις ἐγκαλεῖν, ὁτὲ δὲ ὡς μικρολόγοις. Πᾶσι γὰρ τοῖς τοιούτοις ἕπεται παρὰ τῶν συζώντων ἡ ἐπὶ τῇ ἀμετρίᾳ μέμψις. Τοῦτο γὰρ νῦν ὁ φθόνος δηλοῖ, ἵν' ᾖ τὸ λεγόμενον, πεφύλαξο τοιαῦτα ποιεῖν, ὁπόσα φθόνον ἴσχει, ἤγουν μέμψιν εὔλογον ἔχει παρὰ τῶν πολλῶν. Μεμπτὰ δέ, κατὰ τὸν λόγον καὶ τοὺς πολλούς, ἐν μὲν τῇ διαίτῃ τρυφὴ καὶ ῥύπος, ἐν δὲ τῇ δαπάνῃ χρημάτων ἀσωτία καὶ μικρολογία. Διὸ ἐλευθεριότης καὶ συμμετρία δεικνύτω διὰ τῶν ἐκτὸς πάντων τὴν ἔμφρονα τῆς ψυχῆς ἕξιν καὶ τὸ μέτρον τὸ ἐπὶ πᾶσιν ἄριστον. Δεῖ γάρ, ὅσον ἐφ' ἡμῖν, τῶν ἐπιφθόνων ἀπέχεσθαι τὸν ἡσυχίας ἐρῶντα, καὶ μὴ ἐρεθίζειν, ὥσπερ τι θηρίον, τὸν φθόνον, ἵν' ἀθορύβως ἐξῇ προκόπτειν ἐν τοῖς καλοῖς.", "st": "17.4"}, {"sp": "N", "t": "Ἀνεπίφθονον δὲ ζωὴν ἐπιτηδεύσομεν, λιτὴν καὶ ἄρρυπον δίαιταν ἔχοντες, καὶ τὸν τῆς ἀπειροκαλίας τῦφον ἐκκλίνοντες, ἐξ οὗ ἀποβλαστάνει δύο κακά, δαπάνη τε καὶ φειδὼ χρημάτων ἄκαιρος· ὧν τὸ μὲν εἰς ὑπερηφανίαν διαβάλλεται, τὸ δὲ εἰς μικροπρέπειαν. Ἑκάτερον δὲ τούτων ἡ ἐλευθεριότης ἐκφεύγει, ἀρετὴ περὶ χρημάτων δόσιν καὶ λῆψιν ὑπάρχουσα, καὶ τὸ δέον ἐν προσόδοις καὶ δαπάναις εὑρίσκουσα, καὶ πρὸς τὸν ὀρθὸν λόγον πάντα τὰ ἐκτὸς συντάττουσα. Τοσαῦτα καὶ περὶ τῆς τοῦ σώματος καὶ περὶ τῆς τῶν ἐκτὸς ἀρίστης χρήσεως πεφιλοσόφηται ἐν τοῖς Ἔπεσιν, ὅπως ἂν καὶ διὰ τούτων τὸ τῆς ἀρετῆς διαφαίνηται κάλλος· κεφάλαιον δὲ τῶν πάντων ποιεῖται τὸ ἑξῆς παράγγελμα.", "st": "17.5"}, {"sp": "SEC", "t": "XVIII · 39", "st": "18"}, {"sp": "N", "t": "<span class=\"lemma\">πρῆσσε δὲ ταῦθ' ἅ σε μὴ βλάψει, λόγισαι δὲ πρὸ ἔργου.<\/span>", "st": "18.0"}, {"sp": "N", "t": "Πολλάκις ἐχρήσατο τῷ τοιούτῳ λόγῳ, ὁτὲ μὲν εἰπών,", "st": "18.1"}, {"sp": "N", "t": "ἀλλὰ τάδ' ἐκτελέειν, ἅ σε μὴ μετέπειτ' ἀνιήσει·", "st": "18.2"}, {"sp": "N", "t": "ὁτὲ δέ,", "st": "18.3"}, {"sp": "N", "t": "μέτρον δὲ λέγω τόδ', ὃ μή σ' ἀνιήσει·", "st": "18.4"}, {"sp": "N", "t": "καί,", "st": "18.5"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">μηδεὶς μήτε λόγῳ σε παρείπῃ, μήτε τι ἔργῳ<br>πρῆξαι, μηδ' εἰπεῖν, ὅ τι τοι μὴ βέλτερόν ἐστι.<\/span><\/span>", "st": "18.6"}, {"sp": "N", "t": "Τούτων οὖν ἁπάντων σύνοψιν ἐνταῦθα καὶ μίαν συγκεφαλαίωσιν ὁ λόγος ποιεῖται, ἀπαγορεύων μὲν τῶν βλαβερῶν τὴν παραδοχήν, τῶν δὲ ἐπωφελῶν εἰσηγούμενος τὴν ἐνέργειαν· γίνεσθαι δὲ καλῶς τὴν τούτων διάκρισιν ἐν τῷ λογίζεσθαι πρὸ ἔργου τί πρακτέον, καὶ τί μὴ πρακτέον. Ὁ γὰρ τῆς εὐβουλίας καιρὸς ἐν τῷ ἀπρολήπτῳ τῶν πράξεων παραγίνεται. Κἀνταῦθα δὲ πάλιν τοῦ ἅ σε μὴ βλάψει οὕτως ἀκουσόμεθα, ὡς καὶ τοῦ, ἅ σε μὴ μετέπειτ' ἀνιήσει· τὸ σὲ κατὰ τοῦ ὄντως ἀνθρώπου καὶ τῆς λογικῆς οὐσίας τάττοντες, καὶ κατὰ τοῦ φιλοσοφεῖν προῃρημένου, καὶ τὴν πρὸς θεὸν ὁμοίωσιν κτήσασθαι σπεύδοντος. Τοῦτον δὲ βλάπτει πᾶν τὸ παρὰ τὸν ὀρθὸν λόγον, πᾶν τὸ παρὰ τὸν θεῖον νόμον, πᾶν τὸ τὴν πρὸς θεὸν ὁμοίωσιν ἐμποδίζον. Πέφυκε δὲ τὰ τοιαῦτα ἡμῖν ἐπιτίθεσθαι ἐν τῇ κοινωνίᾳ τῶν συζώντων, καὶ τῇ διοικήσει τοῦ τε συνεζευγμένου σώματος, καὶ τῶν πρὸς βοήθειαν ἐξευρημένων τὴν τούτου· ἃ δὴ χρήματα καλεῖν ἔθος, ὡς πρὸς τὴν χρείαν ἐκκείμενα. Διευλαβεῖσθαι οὖν χρῆναί φησιν ὁ λόγος τὸν ἐρωτικὸν τῶν θείων ἀγαθῶν, μήποτε ἀναπεισθῇ πρᾶξαί τι ὃ μὴ βέλτερον αὐτῷ, καὶ ὅπως μὴ χαρίσηται τῷ σώματι, ἐξ ὧν αὐτὸς ἀνιάσεται, μηδὲ προσδέξηταί τι βλάπτον τὴν φιλόσοφον ὁρμήν, ἐφ' ᾧ μικρὸν ὕστερον μεταμελήσεται. Ταῦτα γὰρ πάντα τῷ προλογισμῷ διωθεῖσθαι ἡμᾶς προσήκει, ἵν' ὁ ἐπιλογισμὸς τῶν εἰργασμένων ἡμῖν ἡδίστην ἔχῃ τὴν ἀνάμνησιν, ἣν ἑξῆς ποιεῖσθαι παρακελεύεται.", "st": "18.7"}, {"sp": "SEC", "t": "XIX · 40–44", "st": "19"}, {"sp": "N", "t": "<span class=\"lemma\">Μηδ' ὕπνον μαλακοῖσιν ἐπ' ὄμμασι προσδέξασθαι,<br>πρὶν τῶν ἡμερινῶν ἔργων λογίσασθαι ἕκαστον·<br>πῇ παρέβην; τί δ' ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη;<br>ἀρξάμενος δ' ἀπὸ πρώτου ἐπέξιθι· καὶ μετέπειτα<br>δειλὰ μὲν ἐκπρήξας ἐπιπλήσσεο, χρηστὰ δέ, τέρπευ.<\/span>", "st": "19.0"}, {"sp": "N", "t": "Ἐνταῦθα γενόμενος τοῦ λόγου, τῶν ὅλων παραγγελμάτων ἄθροισόν μοι τὴν γνώμην, ἵνα τὸ εἴσω τῆς ψυχῆς δικαστήριον πρὸς ταῦτα, ὡς πρὸς θείους νόμους, ἀποβλέπον, ποιῇ τῶν εὖ ἢ κακῶς πεπραγμένων τὴν ἐπίκρισιν. Πόθεν γὰρ ὁ ἐπιλογισμὸς ἕξει δειλὰ μὲν εἰργασμένους ἡμᾶς ἐπικόπτειν, χρηστὰ δὲ πράξαντας ἐπαινεῖν, εἰ μὴ ὁ προλογισμὸς νόμους τινὰς λάβοι, καθ' οὓς προσήκει τὴν ζωὴν συντάττειν, καὶ πρὸς τούτους τὸ τῆς συνειδήσεως ταμιεῖον, ὡς πρός τινα σκοπόν, ἀπευθύνοι τὸν ὅλον ἡμῶν βίον; Ὁσημέραι δὲ ποιεῖσθαι τὴν τοιαύτην κρίσιν εἰσηγεῖται, ἵνα τῷ συνεχεῖ τῆς μνήμης τὸ τῆς κρίσεως ἀπλανὲς διασῴζηται· πρὸς ἑσπέραν δέ, καὶ εἰς ὕπνον τρεπομένων, ὅπως ἂν εἰς τὸ πέρας τῶν μεθημερινῶν πράξεων τὸ τῆς συνειδήσεως καθίζοιμεν δικαστήριον, ἐπικοίτιον ᾆσμα θεῷ τὴν τῶν διαθέσεων ἀνάκρισιν ποιούμενοι, πῇ παρέβην; τί δ' ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη; Οὕτω γὰρ παραμετρήσομεν τὴν ἑαυτῶν ζωὴν τοῖς παραδεδομένοις κανόσι, τῷ νομοθέτῃ νῷ τὸν κριτὴν λόγον ἐπισυνάπτοντες.", "st": "19.1"}, {"sp": "N", "t": "Τί οὖν ὁ νομοθέτης λέγει; Τιμᾶν τοὺς φύσει κρείττονας, κατὰ τὴν οὐσιώδη αὐτῶν τάξιν. Γονέων καὶ συγγενῶν πλεῖστον ποιεῖσθαι λόγον. Τοὺς ἀγαθοὺς ἄνδρας ἀσπάζεσθαι καὶ φιλεῖν. Τῶν σωματικῶν δυνάμεων ὑπερέχειν. Ἑαυτὸν αἰδεῖσθαι πανταχοῦ. Δικαιοσύνης ἐπιμελεῖσθαι. Χρημάτων καὶ τῆς ἐφημέρου ζωῆς προεγνωκέναι τὸ εὔφθαρτον. Τὸν ἀπὸ τῆς θείας κρίσεως ἀπονεμηθέντα κλῆρον ἀσπάζεσθαι. Θεοπρεπεῖ δὲ χρῆσθαι φρονήματι, καὶ πρὸς τὸ βέλτιον μεθιστάναι τὴν γνώμην. Φιλολογίαν ἀσκεῖν τῶν ὄντως λόγων. Ἀνεξαπάτητον εἶναι, καὶ ἀδούλωτον πρὸς τὴν τῆς ἀρετῆς τήρησιν. Εὐβουλίᾳ πρὸ τῶν ἔργων χρῆσθαι, ἐξ ἧς τὸ ἀμεταμέλητον ἐν τοῖς ἔργοις παραγίνεται. Οἰήσεως καθαρεύειν. Τὸν ἐπιστημονικὸν μεταδιώκειν βίον. Τὸ σῶμα καὶ τὰ ἐκτὸς πρὸς τὴν τῆς ἀρετῆς ἐνέργειαν μεταρρυθμίζειν.", "st": "19.2"}, {"sp": "N", "t": "Ταῦτα ὁ νομοθέτης νοῦς διαθεσμοθετεῖ ταῖς ψυχαῖς· ὁ δὲ ὑποδεξάμενος αὐτὰ λογισμὸς δικαστὴς ἄγρυπνος ἑαυτοῦ γίνεται, θαμὰ λέγων πρὸς ἑαυτόν, πῇ παρέβην; τί δ' ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη; καὶ ἐν τάξει τὴν μνήμην ἀναλαμβάνων ἀρετῆς εἵνεκα. Εἶτα εὑρὼν ἑαυτὸν συμφώνως τοῖς προκειμένοις ὅροις διημερεύσαντα, τῆς θείας εὐφροσύνης τοῖς καρποῖς ἀναδεῖ· παρὰ μέλος δέ τι πράξαντα φωράσας, ὥσπερ τισὶ φαρμάκοις, ταῖς ἐκ τῆς μετανοίας νουθετήσεσιν ἐπιστύφει. Διὸ τὸν ὕπνον ἀποκρούσασθαι δεῖν φησι τῇ προθυμίᾳ τοῦ λογισμοῦ. Ἀνέξεται δὲ τὸ σῶμα, μὴ κατασυρόμενον ὑπὸ τῆς τοῦ δαρθάνειν ἀνάγκης, διὰ τὴν σώφρονα δίαιταν, δι' ἣν καὶ τὰ ἀναγκαῖα πάθη τῇ τοῦ λογισμοῦ ἡγεμονίᾳ συντάττεται. Μὴ προσδέξασθαι γάρ φησι τὸν ὕπνον, πρὶν τῶν ἡμερινῶν ἔργων λογίσασθαι ἕκαστον.", "st": "19.3"}, {"sp": "N", "t": "Καὶ τίς ὁ λογισμός; πῇ παρέβην; τί δ' ἔρεξα; τί μοι δέον οὐκ ἐτελέσθη; Διχῶς γὰρ ἁμαρτάνομεν· ἢ τὸ μὴ δέον ποιήσαντες, ὃ διὰ τοῦ παρέβην δηλοῦται· ἢ τὸ δέον μὴ ποιήσαντες, ὡς ἐπ' αὐτῆς κεῖται τῆς λέξεως. Ἄλλο γὰρ ἀργία τοῦ καλοῦ, καὶ ἄλλο ἐνέργεια τοῦ αἰσχροῦ· καὶ τὸ μὲν τῇ παραλείψει κακίζεται, τὸ δὲ τῇ παραδοχῇ. Οἷον, εὔχεσθαι δεῖ, καὶ βλασφημεῖν οὐ δεῖ· τρέφειν γονέας δεῖ, προπηλακίζειν δὲ οὐ δεῖ. Ὁ οὖν τὰ πρότερα μὴ ποιῶν τὰ δέοντα οὐ ποιεῖ, ὁ δὲ τὰ δεύτερα ποιῶν τὰ μὴ δέοντα ποιεῖ· εἰ καὶ ἀμφότερα τρόπον τινὰ πρὸς τὴν ἴσην παρανομίαν ἔρχεται.", "st": "19.4"}, {"sp": "N", "t": "Τὴν δὲ ἀναμέτρησιν τῶν ἡμερινῶν ἔργων παραινεῖ ποιεῖσθαι ἀπὸ πρώτου ἕως τελευταίου ἐν τάξει, μηδὲν παραλείποντα τῶν μέσων· ὃ διὰ τοῦ ἐπέξιθι νοεῖται. Πολλάκις γὰρ ἡ μετάθεσις παραλογίζεται τὴν κρίσιν, καὶ εὐαπολόγητον ποιεῖ τὸ κακῶς εἰργασμένον τῇ ἀταξίᾳ τῆς μνήμης. Καὶ ἄλλως δὲ ἡ τῆς καθημερινῆς ζωῆς ἀνάμνησις μελέτη γίνεται τῆς τῶν προβεβιωμένων ἀναπολήσεως, καὶ τῆς ἀθανασίας ἡμῶν συναίσθησις.", "st": "19.5"}, {"sp": "N", "t": "Καὶ τὸ θαυμαστόν, λογίσασθαι ἕκαστον εἰπὼν οὐκέτι ἐπήγαγε, τί κατώρθωσα; τί μοι τῶν δεόντων πέπρακται; ἀλλ' εἰς τὸ ἀτυφότερον τὴν μνήμην μεθήρμοσε, τῶν ἡμαρτημένων τὴν κρίσιν ποιούμενος· καὶ δικαστὴν ἐπέστησε τὸν δικαιότατον ἅμα καὶ οἰκειότατον, τὸ συνειδὸς αὐτό, καὶ τὸν ὀρθὸν λόγον, καὶ αὑτὸν ἑαυτῷ, ὃν πάντων μάλιστα αἰδεῖσθαι προεπαιδεύθημεν· τί γὰρ οὕτω δύναται νουθετῆσαι ἄλλος ἄλλον, ὡς αὐτὸς ἑαυτόν; Τὸ γὰρ αὐτεξούσιον, τῇ ἐλευθερίᾳ τῆς φύσεως ἀποχρώμενον, ἀποσείεται τὰς παρὰ τῶν ἄλλων συμβουλάς, ὅταν μὴ ἐθέλῃ πείθεσθαι· ὁ δὲ οἴκοθεν λογισμὸς αὐτὸς ἑαυτοῦ κατακούειν ἀνάγκην ἔχει. Τοῦτον ἐπίτροπον ἡμῖν ὁ θεὸς ἐπέστησε· τοῦτον παιδαγωγὸν καὶ διδάσκαλον. Τοῦτον καὶ νῦν δικαστὴν ὁ λόγος τῶν ἡμερινῶν ἔργων ποιεῖται, καὶ παρ' αὐτοῦ τὴν κρίσιν ἐκδέχεται, ἵν' αὐτὸς ἑαυτὸν ψηφίσηται ἀποδοχῆς ἢ ἐπιπλήξεως ἄξιον. Ὅταν γάρ, ὡς ἐν γραμματείῳ, τῇ μνήμῃ ἀναγνῷ τὰ πεπραγμένα, τότε κρίνει πρὸς τὸ παράδειγμα ἀποβλέπων τὸν νόμον, καὶ ψηφίζεται τιμῆς ἢ ἀτιμίας ἑαυτὸν ἄξιον. Ἡ δὲ τοιαύτη καθ' ἡμέραν παρακολούθησις θεοειδὲς ἄγαλμα τὸν χρώμενον ἀποτελεῖ, προσθήκαις καὶ ἀφαιρέσεσι πρὸς τὸ τῆς ἀρετῆς κάλλος παιδαγωγοῦσα, καὶ ὡς οἷόν τε ἄνθρωπον ἀγαθὸν ἀποτελοῦσα. Εἰς τοῦτο γὰρ κατέληξεν ὁ λόγος, μέλλων μεταβαίνειν ἐπὶ τὰ θεοποιὰ παραγγέλματα.", "st": "19.6"}, {"sp": "SEC", "t": "XX · 45–48", "st": "20"}, {"sp": "N", "t": "<span class=\"lemma\">Ταῦτα πόνει, ταῦτ' ἐκμελέτα· τούτων χρὴ ἐρᾶν σε·<br>ταῦτά σε τῆς θείης ἀρετῆς εἰς ἴχνια θήσει·<br>ναὶ μὰ τὸν ἁμετέρᾳ ψυχᾷ παραδόντα τετρακτύν,<br>παγὰν ἀενάου φύσεως.<\/span>", "st": "20.0"}, {"sp": "N", "t": "Ταῦτ' ἦν, ἃ καὶ ἐν Προοιμίοις ἐλέγομεν, ὅτι ἡ μὲν πρακτικὴ φιλοσοφία διὰ τῆς τῶν ἀρετῶν κτήσεως τὸν ἄνθρωπον ἀγαθὸν ἀποτελεῖ, ἡ δὲ θεωρητικὴ εἰς ὁμοιότητα Θεοῦ καθίστησι, νοῦ καὶ ἀληθείας ἐλλάμψει· προηγεῖσθαι δέ, ὡς πρὸς ἡμᾶς, τὰ ἐλάττονα τῶν μειζόνων ἐξ ἀνάγκης. Ῥᾷον γὰρ ἐπιμετρῆσαι τὸν ἀνθρώπινον βίον τῇ εὐλογίστῳ χρήσει, τοῦ παντελῶς μεταφῦναι· ὃ γένοιτ' ἂν διὰ τῆς πρὸς θεωρίαν παντελοῦς ἐπιστροφῆς.", "st": "20.1"}, {"sp": "N", "t": "Καὶ ἄλλως δὲ ἀδύνατον ἀθορύβως κτήσασθαι τὴν ἀλήθειαν, μὴ τῶν ἀλόγων δυνάμεων ἡμῖν ταῖς ἠθικαῖς ἀρεταῖς κατὰ νοῦν τεταγμένων. Μέση γὰρ οὖσα ἡ λογικὴ ψυχὴ νοῦ καὶ ἀλογίας, τότε μόνον ἀπερισπάστως δύναται συνεῖναι τῷ πρὸ αὐτῆς νῷ, ὅταν καθαρὰ γενομένη τῆς τῶν μετ' αὐτὴν προσπαθείας, καθαρῶς ἐφάπτηται ἐκείνων. Ἔσται δὲ καθαρά, εἰ μηδὲν τῇ ἀλογίᾳ, μηδὲ τῷ θνητῷ σώματι συνεκφέροιτο, ὡς ἄλλη δὲ ἄλλων ἐπιμελοῖτο, τοσοῦτον αὐτοῖς ἀπονέμουσα φροντίδος, ὅσον ὁ θεῖος κελεύει νόμος, ἐξάγειν ἑαυτὸν πειρᾶσθαι μὴ συγχωρῶν, ἀλλὰ περιμένειν ἕως ἂν ὁ θεὸς αὐτὸς ἀπολύσῃ ἡμᾶς. Διττῆς οὖν ἀρετῆς τῇ τοιαύτῃ ψυχῇ δεήσει· πολιτικῆς μὲν πρὸς τὰ κάτω, τὴν ἀλογίαν ταττούσης· θεωρητικῆς δὲ πρὸς τὰ ἄνω, τὴν τῶν κρειττόνων συνουσίαν προξενούσης.", "st": "20.2"}, {"sp": "N", "t": "Τῶν δὲ διπλῶν τούτων ἀρετῶν μεθόριον ἔγκεινται οἱ τοιοῦτοι στίχοι· τὸ μέν, ταῦτα πόνει, ταῦτ' ἐκμελέτα, τούτων χρὴ ἐρᾶν σε, ὡς οἰκεῖον συμπέρασμα τῆς πολιτικῆς ἀρετῆς· τὸ δέ, ταῦτά σε τῆς θείης ἀρετῆς εἰς ἴχνια θήσει, ὡς ἀρχὴ καλλίστη τῆς θεωρητικῆς ἐπιστήμης. Τὸν γὰρ ἀπαλλαγέντα τῆς θηριώδους ζωῆς, καὶ τῆς ἀμετρίας τῶν παθῶν, ὅση δύναμις, καθαρεύσαντα, καὶ διὰ τοῦτο οἷον ἐκ θηρίου γενόμενον ἄνθρωπον, τὰ ἑξῆς ἐπαγγέλλεται θεὸν ἐξ ἀνθρώπου ποιήσειν, ἐφ' ὅσον οἷόν τε ἀνθρώπῳ θεὸν γενέσθαι. Ὅτι δὲ τοῦτο τῆς θεωρητικῆς ἀληθείας τὸ τέλος, δι' αὐτῶν δηλοῦται τῶν Ἐπῶν· ἐν οἷς πρὸς τῷ τέλει τὸ κάλλιστον καὶ ἀκρότατον συμπέρασμα ἐπάγει·", "st": "20.3"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Ἢν δ' ἀπολείψας σῶμα ἐς αἰθέρ' ἐλεύθερον ἔλθῃς,<br>ἔσσεαι ἀθάνατος θεός, ἄμβροτος, οὐκ ἔτι θνητός.<\/span><\/span>", "st": "20.4"}, {"sp": "N", "t": "Τυγχάνειν δὲ τῆς ἀποκαταστάσεως ἡμᾶς (ταὐτὸν δὲ εἰπεῖν τῆς ἀποθεώσεως) διὰ τῆς προασκηθείσης ἀρετῆς, καὶ τῆς ἐπὶ ταύτῃ γνωσθείσης ἀληθείας, οὗτος ὁ ἱερὸς ἀποφαίνεται λόγος, ὡς εἰσόμεθα μικρὸν ὕστερον.", "st": "20.5"}, {"sp": "N", "t": "Νῦν δὲ ἐπὶ τὰ προκείμενα ἔπη πάλιν ἐπανελθόντες ἐπισκεψώμεθα εἴ τι βούλεται ὁ πόνος, καὶ ἡ μελέτη, καὶ ὁ ἔρως ἐπὶ ταῖς προλαβούσαις ὑποθήκαις, ἢ τὸ πρὸς τὴν τῆς ἀρετῆς ἄσκησιν ὅλην ἐπιστρέψαι τὴν ψυχήν. Τριδύναμος δέ πώς ἐστι, καὶ αὐτὴ καθ' αὑτὴν λογικὴ οὖσα· τὸ μέν τι ἔχουσα, ᾧ μανθάνομεν, ὃ ταῦτα ἐκμελετᾶν νῦν προστάττεται· τὸ δέ τι, ᾧ τὰ γνωσθέντα κρατοῦμεν, ὃ ταῦτα πονεῖν παραγγέλλεται· τὸ δέ τι, ᾧ στέργομεν τὰ γνωσθέντα καὶ κρατηθέντα, ὃ τούτων ἐρᾶν νουθετεῖται. Ἵνα οὖν πάσας τὰς δυνάμεις τῆς λογικῆς ψυχῆς συντεταμένας ἔχωμεν πρὸς τὰ τῶν ἀρετῶν παραγγέλματα, ἐκ μὲν τοῦ νοεῖν πεφυκότος τὴν μελέτην ἀπαιτεῖ· ἐκ δὲ τοῦ τηροῦντος τὰ νοηθέντα, τὸν πόνον· ἐκ δὲ τοῦ φιλοκάλου, τὸν ἔρωτα· ἵν' ἐξ ἀπάντων ἡ κτῆσις τῶν ὄντως ἀγαθῶν ἡμῖν παραγίνηται μετὰ τῆς ἀπαραβάτου τηρήσεως, καὶ συμφυοῦς ἡμῖν πρὸς ἐκεῖνα στοργῆς· οἷς ἕπεται ἡ θεία ἐλπίς, τὸ τῆς ἀληθείας ἐπεισάγουσα φέγγος, ὡς αὐτὸς ὑπισχνεῖται λέγων, ταῦτά σε τῆς θείης ἀρετῆς εἰς ἴχνια θήσει, τουτέστι, ταῦτά σε ὁμοιώσει τῷ Θεῷ διὰ τῆς τῶν ὄντων ἐπιστημονικῆς γνώσεως. Τὸ γὰρ τὰς αἰτίας ἐκλογίσασθαι τῶν ὄντων, τὰς ἐν τῷ δημιουργῷ θεῷ πρώτως κειμένας, πρὸς τὴν ἀκρότητα ἄγει θεογνωσίας, ᾗ συνεισέρχεται καὶ ἡ πρὸς Θεὸν ὁμοίωσις. Τὴν δὲ ὁμοίωσιν ταύτην θείαν ἀρετὴν ὁ λόγος καλεῖ, ὡς ἐπὶ ἀνθρωπίνην τὴν πρὸ ταύτης καλῶς ἐποχουμένην. Εἰς ἔρωτα οὖν φιλόσοφον καὶ φιλόκαλον ἀποπερατούσθω τὰ πρῶτα ἔπη· τούτου δὲ ἡγουμένου, ἡ τῆς ἀληθείας γνῶσις ἑπέσθω πρὸς ὁμοίωσιν τῆς θείας ἀρετῆς ἀνάγουσα, ὡς ἐν τοῖς ἑξῆς ἔπεσι δηλοῦται.", "st": "20.6"}, {"sp": "N", "t": "Τὸ δὲ ἀναγκαῖον τῆς συναφῆς τούτων καὶ ὅρκῳ πιστοῦται. Τὸ γὰρ καλῶς κτηθεῖσαν τὴν ἀνθρωπίνην ἀρετὴν πρὸς τὴν θείαν ὁδεύειν ὁμοίωσιν, εὖ μάλα διατεταμένως ὄμνυσιν ὁ τὸ Σέβου ὅρκον ἐν ἀρχῇ παραγγείλας. Τὴν γὰρ ἀποχὴν τοῦ ὀμνύναι προστάττει περὶ τῶν ἐνδεχομένων, καὶ ἄδηλον τῆς ἐκβάσεως ἐχόντων τὸ πέρας. Ταῦτα γὰρ καὶ μικρά, καὶ μεταπίπτοντα· διὸ οὔτε ἄξιον ἐπ' αὐτοῖς ὀμνύναι, οὔτ' ἀσφαλές· οὐ γὰρ ἐφ' ἡμῖν εἰς πέρας αὐτὰ ἀγαγεῖν. Περὶ δὲ τῶν παρόντων, ἀναγκαίως τε συνημμένων, καὶ μεγίστων ὄντων, ἀσφαλὲς τὸ ὀμνύναι, καὶ πρέπον. Οὔτε γὰρ τὸ μεταπῖπτον τῶν πραγμάτων ἡμᾶς ἄν ποτε σφήλειε (δέδεται γὰρ πρὸς ἄλληλα θεσμῷ Ἀδραστείας, περὶ ὧν ὁ ὅρκος νυνὶ γίνεται), οὔτε τὸ ταπεινὸν αὐτῶν καὶ χαμαιπετὲς τοῦ θείου τὴν ἐπιμαρτυρίαν ἀρνεῖται· ἀλήθεια γὰρ καὶ ἀρετὴ οὐ μόνον ἐστὶν ἐν ἀνθρώποις, ἀλλὰ καὶ ἐν θεοῖς τὰ μέγιστα. Ἔπειτα καὶ ὁ ὅρκος αὐτῷ γίνεται δόγμα, ὅτι τὸν διδάσκαλον τῆς ἀληθείας οὕτω δέοι τιμᾶν, ὡς καὶ ὀμνύναι αὐτόν, εἴ που δέοι πρὸς βεβαίωσιν τῶν δογμάτων· καὶ μὴ μόνον τὸ Αὐτὸς ἔφα περὶ αὐτοῦ λέγειν, ἀλλὰ καὶ ταῦτα οὕτως ἔχειν νὴ τὸν αὐτόν.", "st": "20.7"}, {"sp": "N", "t": "Ὁμοῦ δὲ περὶ τῆς τῶν καλλίστων ἕξεων συναφῆς ὀμνύων θεολογεῖ, καὶ τὴν τετράδα, πηγὴν τῆς ἀϊδίου διακοσμήσεως, ἀποφαίνεται τὴν αὐτὴν οὖσαν τῷ δημιουργῷ Θεῷ. Πῶς δὲ τετρὰς ὁ θεός; οὕτως ἐκ τοῦ εἰς Πυθαγόραν ἀναφερομένου Ἱεροῦ Λόγου σαφῶς εὑρήσεις, ἐν ᾧ ἀριθμὸς ἀριθμῶν ὁ θεὸς ὑμνεῖται. Εἰ γὰρ τὰ ὄντα πάντα ταῖς ἀϊδίοις αὐτοῦ βουλήσεσιν ὑφέστηκε, δῆλον ὅτι καὶ ὁ ἀριθμὸς ὁ ἐν ἑκάστῳ εἴδει τῶν ὄντων τῆς ἐκείνων αἰτίας ἤρτηται, καὶ ὁ πρῶτος ἀριθμὸς ἐκεῖ πού ἐστιν· ἐκεῖθεν γὰρ ἐνταῦθα. Τοῦ δὲ ἀριθμοῦ τὸ πεπερασμένον διάστημα ἡ δεκάς. Ὁ γὰρ ἐπὶ πλέον ἀριθμεῖν ἐθέλων ἀνακάμπτει πάλιν ἐπὶ τὸ ἕν, καὶ δύο, καὶ τρία· καὶ δευτέραν ἀριθμεῖ δεκάδα πρὸς τὴν τῆς εἰκοσάδος συμπλήρωσιν· καὶ τρίτην ὁμοίως, ἵνα τριάκοντα εἴπῃ· καὶ τοῦτο ἑξῆς, ἕως ἂν δεκάτην ἀριθμήσας δεκάδα εἰς ἑκατὸν προέλθῃ. Καὶ πάλιν ἑκατὸν δέκα τὸν αὐτὸν τρόπον ἀριθμεῖ. Καὶ οὕτω μέχρις ἀπείρου τῷ τῆς δεκάδος διαστήματι ἀνακυκλουμένῳ προχωρεῖν δύναται.", "st": "20.8"}, {"sp": "N", "t": "Τῆς δὲ δεκάδος δύναμις ἡ τετράς. Πρὸ γὰρ τῆς κατὰ διέξοδον τελειότητος τῆς ἐν τῇ δεκάδι, ἡνωμένη τις τελειότης ἐν τῇ τετράδι θεωρεῖται. Κατὰ γὰρ σύνθεσιν τὴν ἀπὸ μονάδος ἕως τετράδος, δεκὰς τὸ πᾶν ἄθροισμα γίνεται. Α' γάρ, καὶ β', καὶ γ', καὶ δ', τὴν δεκάδα πληροῖ. Καὶ ἔστι μεσότης ἀριθμητικὴ μονάδος καὶ ἑβδομάδος ἡ τετράς. Τῷ ἴσῳ γὰρ ἀριθμῷ πως ὑπερέχει, καὶ ὑπερέχεται, τριάδι μὲν ἑβδομάδος λειπομένη, τριάδι δὲ μονάδα ὑπερβάλλουσα. Μονάδος γὰρ καὶ ἑβδομάδος τὰ ἰδιώματα κάλλιστά εἰσι καὶ ἄριστα. Ἡ μὲν γὰρ μονάς, ὡς ἀρχὴ παντὸς ἀριθμοῦ, τὰς πάντων δυνάμεις ἐν ἑαυτῇ συνέχει· ἡ δὲ ἑβδομάς, ὡς ἀμήτωρ καὶ παρθένος, τὴν τῆς μονάδος ἀξίαν δευτέρως ἔχει. Οὔτε γὰρ γεννᾶται ἐξ ἀριθμοῦ τινος τῶν ἐντὸς δεκάδος· ὡς ὁ δ' ἐκ τοῦ δὶς β', καὶ ὁ ἓξ ἐκ τοῦ δὶς γ', καὶ ὁ η' ἐκ τοῦ δὶς δ', καὶ ὁ θ' ἐκ τοῦ τρὶς γ', καὶ ὁ ι' ἐκ τοῦ δὶς ε'. Οὔτε γεννᾷ τινα τῶν ἐντὸς δεκάδος· ὡς ὁ δύο τὸν τέσσαρα, καὶ ὁ γ' τὸν ἓξ καὶ τὸν θ', καὶ ὁ ε' τὸν ι'. Τῆς δὲ ἀγεννήτου μονάδος καὶ τῆς ἀμήτορος ἑβδομάδος ἡ τετρὰς μέση κειμένη, τὰς τῶν γεννώντων καὶ γεννωμένων δυνάμεις ἅμα καὶ συνείληφε καὶ συνέχει, μόνη τῶν ἐντὸς δεκάδος καὶ γεννωμένη ὑπό τινος ἀριθμοῦ, καὶ γεννῶσά τινα. Ἡ γὰρ δυὰς ἑαυτὴν διπλασιάσασα τὴν τετράδα γεννᾷ· ἡ δὲ τετρὰς δὶς γενομένη τὸν ὀκτὼ ἀποτελεῖ. Καὶ στερεοῦ πρώτη ἔμφασις ἐν τῇ τετράδι εὑρίσκεται. Τὸ γὰρ σημεῖον ἀνάλογόν ἐστι μονάδι, ἡ δὲ γραμμὴ δυάδι, ἀπό τινος γὰρ ἐπί τι· καὶ τριάδι προσήκει ἡ ἐπιφάνεια, στοιχειωδέστατον γὰρ τῶν εὐθυγράμμων τὸ τρίγωνον. Τὸ στερεὸν δὲ οἰκεῖον τῇ τετράδι. Ἡ γὰρ πρώτη πυραμὶς ἐν τῇ τετράδι θεωρεῖται· τριγώνου μὲν βάσεως ὑποτεθείσης, τοῦ τρία· κορυφῆς δὲ αὐτῇ ἐπιτεθείσης, τοῦ ἑνός. Καὶ κριτικαὶ δὲ δυνάμεις ἐν τοῖς οὖσι τέσσαρες, νοῦς, ἐπιστήμη, δόξα καὶ αἴσθησις. Κρίνεται γὰρ πάντα τὰ ὄντα ἢ νῷ, ἢ ἐπιστήμῃ, ἢ δόξῃ, ἢ αἰσθήσει. Καὶ ἁπλῶς, τὰ ὄντα πάντα ἡ τετρὰς ἀνεδήσατο, στοιχείων ἀριθμόν, ὡρῶν τοῦ ἔτους, ἡλικιῶν, συνοικισμῶν. Καὶ οὐκ ἔστιν εἰπεῖν, ὃ μὴ τῆς τετρακτύος, ὡς ῥίζης καὶ ἀρχῆς, ἤρτηται. Ἔστι γάρ, ὡς ἔφαμεν, δημιουργὸς τῶν ὅλων καὶ αἰτία ἡ τετράς, θεὸς νοητός, αἴτιος τοῦ οὐρανίου καὶ αἰσθητοῦ θεοῦ.", "st": "20.9"}, {"sp": "N", "t": "Παραδέδοται δὲ ἡ τούτου γνῶσις τοῖς Πυθαγορείοις δι' αὐτοῦ τοῦ Πυθαγόρου, ὃν καὶ νῦν ἐπόμνυται ὁ τῶν Ἐπῶν τούτων συγγραφεύς, ὅτι τῆς ἀρετῆς ἡ τελείωσις πρὸς τὴν τῆς ἀληθείας ἔλλαμψιν ἡμᾶς ἀνάξει. Ὥστε καὶ κατὰ τοῦτο εἴποι ἄν τις ἰδίᾳ μὲν τηρεῖσθαι τὸ Σέβου ὅρκον ἐπὶ τῶν ἀεὶ ὡσαύτως ἐχόντων θεῶν· ἰδίᾳ δὲ νῦν ὄμνυσθαι κατὰ τοῦ παραδόντος ἡμῖν τὴν τετρακτὺν διδασκάλου, ὃς οὐκ ἦν τῶν ἀθανάτων θεῶν, οὐδὲ τῶν φύσει ἡρώων, ἀλλ' ἄνθρωπος ὁμοιώσει θεοῦ κοσμηθείς, καὶ πρὸς τοὺς ἀφ' ἑαυτοῦ θείαν ἀποσώζων εἰκόνα. Ὅθεν καὶ ἔνορκον αὐτὸν ἐπὶ τῶν οὕτω μεγάλων ποιεῖται, λεληθότως ἐπεμβάλλων τὸ περὶ Πυθαγόραν τῶν ἀκροατῶν σέβας, καὶ τὴν ἀξίαν αὐτοῦ δεικνὺς δι' ὧν παραδέδωκε μαθημάτων. Μέγιστον δὲ τούτων ἡ τῆς δημιουργικῆς τετρακτύος γνῶσις.", "st": "20.10"}, {"sp": "N", "t": "Ἀλλ' ἐπεὶ τὰ μὲν πρῶτα ἐπιτέτμηται, τὰ δὲ δεύτερα ἐν ὑποσχέσει κεῖται βεβαίᾳ καὶ ἀψευδεῖ ἐλπίδι, ὅ τε τῆς τετρακτύος ἱεροφάντης ἔγνωσται, καί τίς αὕτη ἡ τετρακτύς, ὅσον τοῖς παροῦσι προσήκει λόγοις, ὑπομνήσεως ἔτυχε· φέρε καὶ ἐφ' ἃ προελθεῖν ὁ λόγος παρακαλεῖ μετίωμεν· πρῶτον μὲν μεθ' οἵας ὁρμῆς καὶ παρασκευῆς, καὶ συνεργείας τῶν Κρειττόνων, ἐλθεῖν ἐπὶ ταῦτα προσήκει προϋποδείξαντες.", "st": "20.11"}, {"sp": "SEC", "t": "XXI · 48–49", "st": "21"}, {"sp": "N", "t": "<span class=\"lemma\">ἀλλ' ἔρχευ ἐπ' ἔργον<br>θεοῖσιν ἐπευξάμενος τελέσαι.<\/span>", "st": "21.0"}, {"sp": "N", "t": "Πάντα τὰ πρὸς τὴν κτῆσιν τῶν ἀγαθῶν συντελοῦντα διὰ βραχέων ὑπέγραψεν ὁ λόγος, τὸ τῆς ψυχῆς αὐτοκίνητον καὶ τὴν τοῦ θεοῦ συνέργειαν. Εἰ γὰρ καὶ ἐφ' ἡμῖν ἡ αἵρεσις τῶν καλῶν, ἀλλὰ καὶ αὐτὸ τὸ ἐφ' ἡμῖν θεόθεν ἔχοντες, τῆς παρ' ἐκείνου συνεργείας καὶ τελειώσεως τῶν αἱρεθέντων πάντως που χρῄζομεν. Ἔοικε γὰρ τὸ μὲν παρ' ἡμῶν σπουδαζόμενον ἐκτεινομένῃ χειρὶ πρὸς λῆψιν τῶν καλῶν, τὸ δὲ παρὰ θεοῦ συντελούμενον χορηγία εἶναι καὶ πηγὴ τῆς δόσεως τῶν ἀγαθῶν· καὶ τὸ μὲν ἐξευρίσκειν πεφυκέναι τὰ καλά, τὸ δὲ ἐκφαίνειν τῷ ζητοῦντι ὀρθῶς· ἡ δὲ εὐχὴ μεθόριον εἶναι τῆς τε παρ' ἡμῶν ζητήσεως καὶ τῆς παρὰ τοῦ θεοῦ δόσεως, εὖ ἐχομένη τῆς αἰτίας ἡμῶν, τῆς εἴς τε τὸ εἶναι προαγούσης ἡμᾶς, καὶ πρὸς τὸ εὖ εἶναι τελειούσης. Πῶς δ' ἂν λάβοι τις τὸ εὖ, μὴ διδόντος θεοῦ; Πῶς δ' ἂν δοίη τῷ πρὸς τὰς ὁρμὰς αὐτεξουσίῳ μὴ αἰτοῦντι ὁ διδόναι πεφυκὼς θεός; Ἵν' οὖν μήτε λόγῳ μόνῳ τὴν εὐχὴν ποιώμεθα, ἀλλὰ καὶ ἔργῳ ταύτην κρατύνωμεν, μήτε τῇ ἑαυτῶν ἐνεργείᾳ μόνῃ θαρρῶμεν, ἀλλὰ καὶ τῆς θεόθεν συνεργείας ἐχώμεθα, καί, ὡς εἶδος ἐπὶ ὕλῃ, τὴν εὐχὴν τῷ ἔργῳ συνάπτωμεν· καὶ τὸ ὅλον τοῦτο, ὅπως ἃ ἐργαζόμεθα καὶ εὐχώμεθα, καὶ ἃ εὐχόμεθα ἐνεργῶμεν· συνάψας εἶπεν, ἀλλ' ἔρχευ ἐπ' ἔργον θεοῖσιν ἐπευξάμενος τελέσαι. Οὔτε γὰρ μόνον προθυμεῖσθαι δεῖ τὰ καλά, ὡς ἐφ' ἑαυτοῖς ὂν κατορθῶσαι, καὶ χωρὶς τῆς τοῦ θεοῦ συνεργείας· οὔτε ψιλοῖς τῆς εὐχῆς τοῖς λόγοις ἀρκεῖσθαι, μηδὲν πρὸς τὴν κτῆσιν τῶν αἰτηθέντων συνεισφέροντας. Οὕτω γὰρ ἢ ἄθεον ἀρετὴν (εἰ οἷόν τε τοῦτο εἰπεῖν) ἐπιτηδεύσομεν, ἢ ἀνενέργητον εὐχήν· ὧν τὸ μὲν ἄθεον ὂν προαναιρεῖ τῆς ἀρετῆς τὴν οὐσίαν, τὸ δὲ ἀργὸν ἐκλύει τῆς εὐχῆς τὸ δραστήριον. Πῶς γὰρ ἔσται τι καλόν, ὃ μὴ πρὸς κανόνα τὸν θεῖον πράττεται; πῶς δὲ τὸ πρὸς τοῦτον πραττόμενον οὐ τῆς ἐκείνου συνεργείας πάντως δεῖται πρὸς ὑπόστασιν; Ἔστι γὰρ ἡ ἀρετὴ εἰκὼν θεοῦ ἐν ψυχῇ λογικῇ· εἰκὼν δὲ πᾶσα τοῦ παραδείγματος δεῖται πρὸς γένεσιν, καὶ οὐκ ἀρκεῖ τῷ κτωμένῳ, ἐὰν μὴ καὶ ἐκεῖσε βλέπῃ, οὗ πρὸς ὁμοίωσιν τὸ καλὸν κτήσεται. Σπεύδοντας οὖν πρὸς τὴν ἐνεργὸν ἀρετὴν εὔχεσθαι προσήκει, καὶ εὐχομένους τὴν κτῆσιν ταύτης ἐργάζεσθαι· τοῦτο δ' ἦν, τὸ πρὸς τὸ θεῖον καὶ λαμπρὸν βλέποντας πράττειν, καὶ πρὸς φιλοσοφίαν ἑαυτοὺς συντείνειν, μετὰ τοῦ εὖ ἔχεσθαι τῆς πρώτης αἰτίας τῶν ἀγαθῶν. Ἡ γὰρ πηγὴ τῆς ἀεννάου φύσεως ἡ τετρακτὺς ἐκείνη οὐ μόνον τοῦ εἶναι τοῖς πᾶσιν, ἀλλὰ καὶ τοῦ εὖ εἶναι, αἰώνιος αἰτία καθέστηκε, τὸ οἰκεῖον ἀγαθὸν διὰ παντὸς ἐφαπλώσασα τοῦ κόσμου, οἷον φῶς ἀκήρατον καὶ νοερόν. Ἡ δὲ ταύτης εὖ ἐχομένη ψυχή, καί, ὡς ὄμμα πρὸς ὀξυωπίαν ἑαυτὴν διασμήξασα, ἔκ τε τῆς ἐπιμελείας τῶν καλῶν πρὸς τὴν εὐχὴν ἀνεγείρεται· καὶ πάλιν ἀπὸ τῆς εὐκτικῆς πληρώσεως τὴν σπουδὴν ἐπιτείνει, λόγοις ἔργα συνάπτουσα, καὶ ἔργα σπουδαῖα θείαις διαλέξεσι βεβαιουμένη. Καὶ τὰ μὲν εὑρίσκουσα, τὰ δὲ ἐλλαμπομένη, σπουδάζει τε ἃ εὔχεται, καὶ εὔχεται ἃ σπουδάζει. Τοιαύτη μὲν ἡ τῆς σπουδῆς καὶ τῆς εὐχῆς ἕνωσις. Τί δὲ τὰ δι' ἀμφοτέρων τούτων κατορθούμενα, ἑξῆς ἀκούωμεν.", "st": "21.1"}, {"sp": "SEC", "t": "XXII · 49–51", "st": "22"}, {"sp": "N", "t": "<span class=\"lemma\">τούτων δὲ κρατήσας,<br>γνώσεαι ἀθανάτων τε θεῶν θνητῶν τ' ἀνθρώπων<br>σύστασιν, ᾗ τε ἕκαστα διέρχεται ᾗ τε κρατεῖται·<\/span>", "st": "22.0"}, {"sp": "N", "t": "Πρῶτον μὲν θεογνωσίαν καὶ θεολογικὴν ἐπιστήμην παρέσεσθαι τοῖς οὕτως ἀχθεῖσι προλέγει, καὶ πάντων τῶν ἀπὸ τῆς ἱερᾶς τετρακτύος ὑποστάντων τὴν ἐπίγνωσιν, μετὰ τῆς κατὰ γένος αὐτῶν διακρίσεως, καὶ τῆς εἰς ἕνα κόσμον ἑνώσεως. Τὴν μὲν γὰρ σύνταξιν αὐτῶν ἐνταῦθα τὸ τῆς συστάσεως ὄνομα δηλοῖ· τὸ δ' ᾗ διέρχεται, τὴν κατ' εἶδος διαφοράν· καὶ τὸ ᾗ κρατεῖται, τὴν κατὰ γένος κοινωνίαν. Φύσει γὰρ διεστῶτα τῶν λογικῶν οὐσιῶν τὰ γένη κατὰ ταύτην τὴν διάστασιν εἰς μίαν κοινωνίαν συνέρχεται. Τῷ γὰρ εἶναι τὰ μὲν πρῶτα, τὰ δὲ μέσα, τὰ δὲ ἔσχατα, διακέκριται ἅμα καὶ ἥνωται. Οὔτε γὰρ τὰ πρῶτα ἂν γένοιτο μέσα, ἢ ἔσχατα· οὔτε τὰ μέσα πρῶτα, ἢ ἔσχατα· οὔτε τὰ ἔσχατα μέσα, ἢ πρῶτα· ἀλλ' ἐν τοῖς δημιουργικοῖς ὅροις ἀϊδίως μένει κατὰ γένος διακεκριμένα. Καὶ οὕτω μὲν τὸ ᾗ ἕκαστα διέρχεται νοοῦμεν. Τὸ δὲ ᾗ ἕκαστα κρατεῖται, πάλιν αὖ τῇδε θεωρήσομεν. Τὸ πᾶν τόδε οὐκ ἂν εἴη τέλειον, μὴ πρῶτα καὶ μέσα καὶ ἔσχατα μέρη ἐν ἑαυτῷ κεκτημένον, ὡς ἀρχὴν καὶ μέσα καὶ τελευτὴν τοῦ ὅλου συστήματος. Καὶ τὰ πρῶτα οὐκ ἂν εἴη πρῶτα, μὴ μέσων καὶ ἐσχάτων αὐτοῖς ἑπομένων, οὐδὲ τὰ μέσα τοῦτ' ἂν εἴη, ὃ λέγεται, μὴ ἄκρων ἑκατέρωθεν αὐτοῖς παρακειμένων· ἀλλ' οὐδὲ τὰ ἔσχατα εἴη ἂν ἔσχατα, μὴ πρώτων καὶ μέσων προηγουμένων. Συνεισάγει οὖν ἄλληλα πρὸς τὴν τοῦ παντὸς τελειότητα. Καὶ τοῦτ' ἦν, τὸ κρατεῖσθαι αὐτὰ ὑπ' ἀλλήλων· ὡς μὲν ἑτεροειδῆ, διαφέροντα· ὡς δὲ ἑνὸς κόσμου μέρη, συνεισιόντα· καὶ αὐτῷ τῷ διεστάναι ἅμα καὶ ἡνῶσθαι τῆς θείας διακοσμήσεως τὴν ὅλην σύστασιν καὶ σύνταξιν πληροῦντα· ἣν γνώσεαι, φησίν, εἰ ἐγκρατὴς γένοιο τῶν προειρημένων καλῶν.", "st": "22.1"}, {"sp": "N", "t": "Τῶν δὲ ἄκρων γενῶν τῇ μνήμῃ συνεισέρχεται τὰ μέσα· ἀθανάτων γάρ φησι θεῶν θνητῶν τ' ἀνθρώπων σύστασιν. Τὰ δὲ πρῶτα τοῖς ἐσχάτοις διὰ τῶν μέσων συνάπτεται, καὶ τὰ ἔσχατα πρὸς τὰ πρῶτα τῇ μεσότητι τῶν ἀγαθῶν Ἡρώων ἀνατείνεται. Τοιαύτη δὲ καὶ ἡ τάξις τῶν λογικῶν γενῶν ἡ ἐν προοιμίοις παραδέδοται, ὥστ' εἶναι πρῶτοι μὲν ἐν τῷδε τῷ κόσμῳ οἱ ἀθάνατοι θεοί· ἔπειθ' Ἥρωες ἀγαυοί· καὶ τελευταῖοι Δαίμονες καταχθόνιοι, οὓς νῦν θνητοὺς ἀνθρώπους καλεῖ. Πῶς δὲ ἕκαστον τούτων δεῖ νοεῖν ἤδη ἐν προοιμίοις εἴρηται· τὸ δὲ γνῶσιν τούτων προσλαβεῖν ἐπιστημονικήν, ὧν ἐκ παραδόσεως τὴν τιμὴν προειλήφαμεν, πρακτικὴν ἀρετὴν ἀληθείᾳ θεωρητικῇ κοσμοῦσιν ἐγγίνεται, ἢ καὶ ἀπὸ τῆς ἀνθρωπίνης εὐεξίας ἐπὶ τὴν θείαν ἀρετὴν μεθισταμένοις. Τὸ γὰρ οὕτω γνῶναι τὰ ὄντα, ὡς παρ' αὐτοῦ τοῦ θεοῦ ὑπέστη, ὁμοίωμα ἦν θεῖον κτήσασθαι. Ἐπειδὴ δὲ μετὰ τὴν ἀσώματον διακόσμησιν ἡ σωματικὴ φύσις ὑπόκειται, τὸν ἐμφανῆ τοῦτον συμπληροῦσα κόσμον, καὶ πρὸς τὴν τῶν λογικῶν οὐσιῶν ἡγεμονίαν συντεταγμένη, ἑξῆς τὸ τῆς φυσιολογικῆς ἐπιστήμης ἀγαθὸν ἐπακολουθήσειν μηνύει τοῖς ἐν τάξει προϊοῦσιν ἐπὶ τὰς γνώσεις.", "st": "22.2"}, {"sp": "SEC", "t": "XXIII · 52–53", "st": "23"}, {"sp": "N", "t": "<span class=\"lemma\">γνώσῃ δ', ᾗ θέμις ἐστί, φύσιν περὶ παντὸς ὁμοίην,<br>ὥστε σε μήτε ἄελπτ' ἐλπίζειν, μήτε τι λήθειν.<\/span>", "st": "23.0"}, {"sp": "N", "t": "Πρὸς τὴν θείαν εὐμετρίαν ἡ φύσις τὸν ἐμφανῆ κόσμον ἀποτυπουμένη, δι' ἀναλογίας τε αὐτὸν ἑαυτῷ πανταχοῦ διαφόρως ὡμοίωσε, καὶ τὸ θεῖον κάλλος ἐνεικονίσατο δι' ὅλων τῶν ἐγκοσμίων εἰδῶν ἄλλως καὶ ἄλλως· ὥστε οὐρανῷ μὲν ἀποδοῦναι τὸ ἀεικίνητον, γῇ δὲ τὸ μόνιμον, ἑκάτερον δὲ τούτων θείας ὁμοιώσεως ἴχνος ἀποφέρεσθαι. Καὶ τῷ μὲν οὐρανίῳ σώματι τὸ πέριξ τοῦ παντὸς ἀπένειμε, τῷ δὲ περιγείῳ τὸ κέντρον. Ἐν δὲ σφαίρᾳ ἄλλως μὲν τὸ κέντρον ἀρχή, ἄλλως δὲ ὁ τοῦ περιέχοντος ὅρος. Ὅθεν τὰ ἄνω μὲν ἄστροις πεποίκιλται, καὶ τοῖς μετ' ἐκεῖνα ζῴοις νοεροῖς· γῆ δὲ φυτοῖς ἐκοσμήθη, καὶ ζῴοις αἰσθήσει μόνῃ χρωμένοις. Μεσότης δὲ τῶν οὕτω διεστηκότων ὁ ἄνθρωπος ἐνορᾶται, ἀμφίβιός τις ὤν, καὶ ἔσχατος μὲν τῶν ἄνω, πρῶτος δὲ τῶν κάτω. Διὸ ποτὲ μὲν τοῖς ἀθανάτοις συμφέρεται, καὶ τῇ πρὸς νοῦν ἐπιστροφῇ τὴν οἰκείαν λῆξιν ἀπολαμβάνει· ποτὲ δὲ τοῖς θνητοῖς εἴδεσι συναγελάζεται, καὶ τῇ τῶν θείων νόμων ἐκβάσει τῆς προσηκούσης αὐτῷ ἀξίας ἀποπίπτει. Ὡς γὰρ ἔσχατος τῶν λογικῶν γενῶν, οὔτε ἀεὶ καὶ ὡσαύτως πέφυκε νοεῖν (οὕτω γὰρ οὐκ ἂν ἦν ἄνθρωπος, ἀλλὰ φύσει θεός), οὔτε ἀεὶ νοεῖν δύναται, εἰ καὶ μὴ ὡσαύτως· τοῦτο γὰρ αὐτὸν εἰς τὴν ἀγγέλων καθίστησι τάξιν. Νῦν δέ ἐστιν ἄνθρωπος ὁμοιώσει μὲν πρὸς τὸ βέλτιον ἀχθῆναι δυνάμενος, φύσει δὲ ὑποβεβηκὼς τῶν ἀθανάτων θεῶν, καὶ τῶν ἀγαυῶν ἡρώων, ὡς ἐγκοσμίων πρώτων καὶ μέσων γενῶν. Ὥσπερ γὰρ τούτων ὑπέβη τῷ μὴ ἀεὶ νοεῖν, ἀλλ' ἐν ἀγνοίᾳ ποτὲ καὶ λήθῃ γίνεσθαι τῆς ἑαυτοῦ οὐσίας, καὶ τῆς θεόθεν κατιούσης εἰς αὐτὸν ἐλλάμψεως· οὕτω τῷ μὴ μένειν ἀεὶ ἐν τῇ ἀγνοίᾳ ὑπερέχει ζῴων ἀλόγων καὶ φυτῶν, καὶ ὅλης τῆς περιγείου καὶ θνητῆς φύσεως ἀναβέβηκε κατ' οὐσίαν, ὡς ἐπιστρέφειν πρὸς τὸν θεὸν πεφυκώς, καὶ ἀναμνήσει τὴν λήθην ἀφανίζειν, καὶ διδασκαλίᾳ προσλαμβάνειν ἃ ἀπέβαλε, καὶ τὴν ἄνωθεν φυγὴν τῇ ἀντιστρόφῳ φυγῇ ἰᾶσθαι.", "st": "23.1"}, {"sp": "N", "t": "Προσήκει οὖν τῇ ἀνθρωπίνῃ οὐσίᾳ τοιαύτῃ οὔσῃ, γνῶναι τὴν σύστασιν τῶν ἀθανάτων θεῶν θνητῶν τ' ἀνθρώπων· τουτέστι, τῶν λογικῶν γενῶν τὴν διάταξιν· γνῶναι δὲ καὶ τὴν φύσιν, τὴν περὶ παντὸς ὁμοίην· τουτέστι, τὴν σωματικὴν οὐσίαν, τὴν ἄνωθεν μέχρι τῶν τελευταίων δι' ἀναλογίας καὶ ἐμφάσεως θείας κοσμηθεῖσαν· γνῶναι δὲ ταῦτα πάντα ᾗ θέμις ἐστί, τοῦτ' ἔστι, νόμῳ ὡς διάκεινται, καὶ οὕτως ὡς ὑπέστη παρὰ τοῦ θεοῦ, καὶ ὃν τρόπον τοῖς ἐκείνου νόμοις ἐστὶ διατεταγμένα, εἴτε σώματα, εἴτε ἀσώματα. Κατὰ κοινοῦ γὰρ ἐπ' ἀμφοτέρων τῶν ποιήσεων τὸ ᾗ θέμις ἐστίν, ἀκουστέον. Οὐ γὰρ ἀλογίστοις προθυμίαις εἴκοντας μεταφέρειν δεῖ τὴν ἀξίαν τῶν πραγμάτων πρὸς τὸ ἡμῖν δοκοῦν· ἀλλὰ τοῖς τῆς ἀληθείας ὅροις ἑπομένους γινώσκειν τὰ ὄντα πάντα, ᾗ θέμις ἐστί, καὶ ὡς ὁ τῆς δημιουργίας θεσμὸς ὥρισεν ἕκαστα.", "st": "23.2"}, {"sp": "N", "t": "Ἐκ δὲ τούτων τῶν δύο γνώσεων, τῆς τε περὶ τὴν ἀσώματον ποίησιν τοῦ θεοῦ, καὶ τῆς περὶ τὴν σωματικήν, κάλλιστον ἐπανθεῖ πόρισμα, τὸ μήτε ἄελπτ' ἐλπίζειν, μήτε τι λήθειν. Ἐκ γὰρ τοῦ λανθάνειν ἡμᾶς τὴν οὐσίαν τῶν πραγμάτων ἀπογίνεται καὶ τὸ ἄελπτ' ἐλπίζειν, καὶ τὸ ἀδύνατα περινοεῖν. Οἷον, εἴ τις ἄνθρωπος ὢν τῶν ἀθανάτων θεῶν ἐλπίζει γενέσθαι, ἢ τῶν ἀγαυῶν ἡρώων· οὗτος οὐκ οἶδε τοὺς ὅρους τῆς φύσεως, οὔτε τῶν ὄντων πρῶτα καὶ μέσα καὶ ἔσχατα διεστείλατο. Καὶ πάλιν, εἴ τις τὴν ἑαυτοῦ ψυχὴν συναποθνῄσκειν οἴεται τῷ θνητῷ σώματι, ἀγνοίᾳ τῆς προσούσης ἀθανασίας τῇ ἡμετέρᾳ ψυχῇ, προσδοκᾷ ἃ μὴ δεῖ, μηδὲ οἷά τε γενέσθαι. Ὁμοίως δὲ καὶ ὁ θηρίου μεταμφιάσασθαι σῶμα ἐλπίζων, καὶ ζῷον ἄλογον γενέσθαι διὰ κακίαν, ἢ καὶ φυτὸν δι' ἀργίαν αἰσθήσεως· καὶ οὗτος, ἀντιστρόφως τοῖς εἰς τὰ ἄνω γένη μεταβάλλουσι τὴν τοῦ ἀνθρώπου οὐσίαν, πρὸς τὰ κάτω αὐτὴν συνωθεῖ, πεπλανημένος καὶ μὴ νοῶν τὸ ἀμετάβλητον τοῦ κατ' οὐσίαν ὑπάρχοντος εἴδους τῇ ἀνθρωπίνῃ ψυχῇ. Ἀεὶ γὰρ μένουσα ἄνθρωπος, τῇ τῆς ἀρετῆς καὶ κακίας ἀνὰ μέρος κτήσει, θηρίον λέγεται ἢ θεὸς γίνεσθαι· φύσει δὲ οὐδέτερον, ἀλλὰ σχέσει τῆς πρὸς ἑκάτερον ὁμοιώσεως. Καὶ ὅλως ὁ τὴν προσοῦσαν ἀξίαν ἑκάστῳ τῶν ὄντων μὴ εἰδώς, ἀλλ' εἴτε ὑπερβάλλων αὐτῆς ἢ ἐλλείπων, τὴν ἄγνοιαν ταύτην ἀφορμὴν τῆς ὑποκένου δόξης καὶ ἀέλπτου ἐλπίδος πεποίηται. Ὁ δὲ ἐν τοῖς δημιουργικοῖς μέτροις ἕκαστα ἀφορίζων, καὶ γιγνώσκων τὰ ὄντα, ᾗ γέγονε, καὶ παραμετρῶν τῷ θεῷ τὴν ἑαυτοῦ γνῶσιν· οὗτος τὸ Ἕπου θεῷ μάλιστα τηρεῖ, καὶ τὸ Ἄριστον μέτρον οἶδε, καὶ τῆς ἀνεξαπατήτου ἐλπίδος τυγχάνει.", "st": "23.3"}, {"sp": "SEC", "t": "XXIV · 54–60", "st": "24"}, {"sp": "N", "t": "<span class=\"lemma\">γνώσῃ δ' ἀνθρώπους αὐθαίρετα πήματ' ἔχοντας<br>τλήμονας, οἵ τ' ἀγαθῶν πέλας ὄντων οὔτ' ἐσορῶσιν<br>οὔτε κλύουσι· λύσιν δὲ κακῶν παῦροι συνίσασι.<br>τοίη μοῖρα βροτῶν βλάπτει φρένας· ὡς δὲ κύλινδροι<br>ἄλλοτ' ἐπ' ἄλλα φέρονται, ἀπείρονα πήματ' ἔχοντες.<br>λυγρὴ γὰρ συνοπαδὸς ἔρις βλάπτουσα λέληθε<br>σύμφυτος, ἣν οὐ δεῖ προάγειν, εἴκοντα δὲ φεύγειν.<\/span>", "st": "24.0"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Τῆς τῶν ἀσωμάτων καὶ σωματικῶν γενῶν καλῶς γνωσθείσης διατάξεως, ἕπεται καὶ τὴν ἀνθρώπου οὐσίαν ἀκριβῶς γνωρίζεσθαι, οἵα τε οὖσα τυγχάνει, καὶ οἵων δεκτικὴ παθημάτων· καὶ ὅτι ἐν μεθορίῳ ἐστὶ τῶν τε ἀπτώτων εἰς κακίαν, καὶ τῶν πρὸς ἀρετὴν οὐ πεφυκότων ἀνάγεσθαι· διὸ καὶ ἐπαμφοτερίζει ταῖς σχέσεσιν, ὁτὲ μὲν ἐκεῖ ζῶσα τὴν νοερὰν εὐζωΐαν, ὁτὲ δὲ ἐνταῦθα τὴν αἰσθητικὴν ἐμπάθειαν προςλαμβάνουσα. Ἔνθεν καὶ λέγεται ὀρθῶς ὑπὸ Ἡρακλείτου, ὅτι ζῶμεν τὸν ἐκείνων θάνατον, τεθνήκαμεν δὲ τὸν ἐκείνων βίον. Κάτεισι γὰρ καὶ ἀποπίπτει τῆς εὐδαίμονος χώρας ὁ ἄνθρωπος, ὡς Ἐμπεδοκλῆς φησιν ὁ Πυθαγόρειος,<br>φυγὰς θεόθεν καὶ ἀλήτης,<br>νείκεϊ μαινομένῳ πίσυνος.<br>Ἄνεισι δέ, καὶ τὴν ἀρχαίαν ἕξιν ἀπολαμβάνει, εἰ φύγοι τὰ περὶ γῆν καὶ τὸν ἀτερπέα χῶρον, ὡς ὁ αὐτὸς λέγει,<br>ἔνθα φόνος τε κότος τε καὶ ἄλλων ἔθνεα κηρῶν·<br>εἰς ὃν οἱ ἐμπεσόντες<br>Ἄτης ἂν λειμῶνα κατὰ σκότος ἠλάσκουσι.<br>Ἡ δὲ ἔφεσις τοῦ φεύγοντος τὸν τῆς Ἄτης λειμῶνα πρὸς τὸν τῆς ἀληθείας ἐπείγεται λειμῶνα· ὃν ἀπολιπών, τῇ ὁρμῇ τῆς πτεροῤῥυήσεως εἰς γήινον ἔρχεται σῶμα, ὀλβίου αἰῶνος ἀμερθείς.<\/span><\/span>", "st": "24.1"}, {"sp": "N", "t": "Τούτοις δὲ καὶ ὁ Πλάτων ἐστὶ σύμφωνος, περὶ μὲν τῆς καθόδου ταυτὶ λέγων· ὅταν δὲ ἀδυνατήσασα ἐπισπέσθαι μὴ ἴδῃ, καί τινι συντυχίᾳ χρησαμένη πτεροῤῥυήσῃ τε καὶ ἐπὶ τὴν γῆν πέσῃ, τότε νόμος αὐτὴν εἰς ζῷον θνητὸν εἰσοικίζεσθαι. Περὶ δὲ τῆς ἀνόδου ταῦτα· ὅτι τὸν ὕστερον προςφύντα ὄχλον ἐκ γῆς, καὶ ὕδατος, καὶ ἀέρος, καὶ πυρός, θορυβώδη καὶ ἄλογον ὄντα, λόγῳ κρατήσας ὁ ἄνθρωπος, εἰς τὸ τῆς προτέρας καὶ ἀρίστης ἀφικνεῖται εἶδος ἕξεως· ὅτε καὶ εἰς τὸ σύννομον ἄστρον ἀνάγεται ὑγιὴς καὶ ὁλόκληρος γενόμενος. Ὑγιὴς μὲν τῇ τῶν παθῶν, ὡς νοσημάτων, ἀπαλλαγῇ, ὃ διὰ τῆς πολιτικῆς ἀρετῆς παραγίνεται· ὁλόκληρος δέ, τῇ νοῦ καὶ ἐπιστήμης, ὡς οἰκείων μερῶν, ἀναλήψει, ὃ διὰ τῆς θεωρητικῆς ἀληθείας κατορθοῦσθαι πέφυκε. Καὶ πάλιν, ὡς δέοι τῇ ἐντεῦθεν φυγῇ τὴν ἀπὸ τῶν κρειττόνων γενομένην ἀπόστασιν ἐξιάσασθαι, σαφῶς παρίστησι, φυγὴν τῶν τῇδε κακῶν τὴν φιλοσοφίαν ὁριζόμενος. Συμπεφυκέναι γὰρ τὰ πάθη μόνοις τοῖς θνητοῖς ἀποφαίνεται διὰ τούτων· ἀλλ' οὐδὲ ἀπολέσθαι τὰ κακὰ δυνατόν, οὔτε ἐν θεοῖς εἶναι, περὶ δὲ τόνδε τὸν τόπον καὶ τὴν θνητὴν φύσιν περιπολεῖ ἐξ ἀνάγκης. Τοῖς γὰρ ἐν γενέσει καὶ φθορᾷ πάντως που καὶ τὸ παρὰ φύσιν διατεθῆναι δύνασθαι παρέπεται· ὅπερ ἦν τῶν κακῶν ἀρχή. Πῶς δὲ δεῖ ταῦτα φεύγειν ἐπάγει· διὸ δεῖ ἐνθένδε ἐκεῖσε φεύγειν· φυγὴ δὲ ὁμοίωσις θεῷ κατὰ τὸ δυνατὸν ἀνθρώπῳ· ὁμοίωσις δέ, δίκαιον καὶ ὅσιον μετὰ φρονήσεως γενέσθαι.", "st": "24.2"}, {"sp": "N", "t": "Τὸν γὰρ ἀποδρᾶναι βουλόμενον τὰ κακὰ τὴν θνητὴν φύσιν πρῶτον ἀποστραφῆναι δεῖ· οὐ γὰρ οἷόν τε ταύτῃ συμπεφυρμένους μὴ καὶ τῶν ἑπομένων αὐτῇ κακῶν ἐξ ἀνάγκης ἀναπίμπλασθαι. Ὥσπερ οὖν ἡ θεόθεν φυγὴ καὶ ἡ πτεροῤῥύησις τῶν κουφιζόντων ἡμᾶς πρὸς τὰ ἄνω πτερῶν εἰς τὸν τῶν θνητῶν ἤνεγκε τόπον, οἷς τὰ κακὰ συνεισέρχεται· οὕτω καὶ ἡ τῆς θνητῆς προσπαθείας ἀποβολή, καὶ ἡ τῶν ἀρετῶν, οἷον πτερῶν τινων, ἔκφυσις πρὸς τὸν τῶν κακῶν καθαρὸν τόπον, πρὸς τὴν θείαν εὐζωΐαν, ἡμᾶς ἀνάξει. Μέση γὰρ οὖσα ἡ τοῦ ἀνθρώπου οὐσία τῶν τε ἀεὶ νοούντων τὸν θεὸν καὶ τῶν μηδέποτε νοεῖν πεφυκότων ἄνεισί τε πρὸς ἐκεῖνα, καὶ κάτεισι πρὸς ταῦτα, νοῦ κτήσει καὶ ἀποβολῇ πρὸς τὴν θείαν ὁμοίωσιν καὶ τὴν θήρειον διὰ τὸ τῆς φύσεως ἀμφίβιον ἀνὰ μέρος ἐπειγομένη.", "st": "24.3"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Ταῦτ' οὖν ὁ περὶ τῆς ἀνθρωπίνης ἐγνωκὼς οὐσίας οἶδε πῶς αὐθαίρετα πήματ' ἔχουσιν οἱ ἄνθρωποι, καὶ πῶς τλήμονες καὶ τάλανες ταῖς ἑαυτῶν αἱρέσεσι γίνονται. Ποτὲ μὲν γάρ, ἔτι δυνάμενοι μένειν ἐκεῖ, προπετείᾳ ὁρμῆς εἰς γένεσιν κατασύρονται· ποτὲ δέ, δυνάμενοι θᾶσσον ἐντεῦθεν ἀπολύεσθαι, αὐτοὶ ἑαυτοὺς ταῖς ἀμετρίαις τῶν παθῶν καταπλέκουσι. Καὶ τοῦτο ἦν τὸ τῶν ἀγαθῶν πέλας ὄντων μήτε ὁρᾶν μήτε ἀκούειν· ἵνα ἀγαθὰ μὲν ἀρετὴ καὶ ἀλήθεια νῦν λέγηται· τὸ δὲ μὴ ὁρᾶν πέλας ὄντα, τὸ μὴ δι' ἑαυτοῦ ἀνακινεῖσθαι πρὸς εὕρεσιν τῶν καλῶν· καὶ τὸ μὴ ἀκούειν, τὸ ταῖς παρ' ἄλλων διδασκαλίαις μὴ ὑπήκοον γίνεσθαι. Διπλῆ γὰρ ἡ τῆς ἐπιστήμης ἀνάληψις· ἢ διὰ μαθήσεως, ὡς δι' ἀκοῆς· ἢ δι' εὑρέσεως, ὡς δι' ὁράσεως. Αὐθαίρετα οὖν πήματα ἔχειν λέγονται οἱ μήτε μανθάνειν παρ' ἄλλων μήτε εὑρίσκειν δι' ἑαυτῶν ἐθέλοντες, ὡς τῆς συναισθήσεως τῶν ἀγαθῶν ἀμοιροῦντες, καὶ διὰ τοῦτο πάντη ἀχρεῖοι.<br>Ὃς γὰρ ἂν μήτ' αὐτὸς νοέῃ, μήτ' ἄλλου λέγοντος<br>ἐν θυμῷ βάλληται, ἐκεῖνος δ' αὖτ' ἀχρήϊος ἀνήρ.<br>Οἱ δὲ περὶ τῶν ἀγαθῶν μανθάνειν τε καὶ εὑρίσκειν ἔργον πεποιημένοι, οὗτοί εἰσιν οἱ τῶν κακῶν τὴν λύσιν συνιέντες, καὶ φυγῇ τῶν τῇδε πόνων εἰς τὸν ἐλεύθερον αἰθέρα μετοικιζόμενοι. Ὀλίγοι δέ εἰσιν οἱ τοιοῦτοι. Οἱ γὰρ πλεῖστοι κακοί, καὶ τῆς θνητῆς προςπαθείας ἥττους, καὶ φρενοβλαβεῖς ὑπὸ τῆς εἰς γῆν νεύσεως γενόμενοι· ὡς καὶ τοῦτο παρ' ἑαυτῶν τὸ κακὸν ἔχειν, διὰ τὸ βουληθῆναι φυγεῖν ἀπὸ θεοῦ, καὶ ἀπομερίσαι αὑτοὺς τῆς τούτου ὁμιλίας, ἧς εὐτύχουν ἐν αὐγῇ καθαρᾷ διάγοντες. Τὸν γὰρ ἀπὸ θεοῦ χωρισμὸν ἡ βλάπτουσα τὰς φρένας μοῖρα νῦν δηλοῖ. Οὐ γάρ ἐστιν ἢ μὴ ἀνοηταίνειν τὸν τοῦ θεοῦ γενόμενον ἔρημον, ἢ μὴ ἔρημον εἶναι θεοῦ τὸν εἰς ἄνοιαν ἐκπεσόντα. Τὸν γὰρ ἀνόητον ἀνάγκη καὶ ἄθεον εἶναι, καὶ τὸν ἄθεον ἀνόητον.<\/span><\/span>", "st": "24.4"}, {"sp": "N", "t": "Ἀμφότεροι δέ, ὡς μὴ πρὸς τὸν ἔρωτα τῶν καλῶν ἐγηγερμένοι, ἀπείρονα πήματ' ἔχουσιν, οἷον κύλινδροι ταῖς καταγώγοις πράξεσιν ἄλλοτε ἄλλοις κακοῖς συμφερόμενοι, καὶ μὴ ἔχοντες ὅ τι χρήσονται ἑαυτοῖς, διὰ τὸ πάσαις ταῖς τύχαις ἀπαιδεύτως προςφέρεσθαι· νῦν μὲν ἐξυβρίζοντες ἐν πλούτῳ, νῦν δὲ ἐν πενίᾳ κακουργοῦντες, καὶ πρὸς λῃστείαν μὲν ὑπὸ ῥώμης σώματος ἐκφερόμενοι, πρὸς δὲ βλασφημίαν ὑπὸ ἀσθενείας καὶ νοσημάτων· τήν τε ἀπαιδίαν ὀδυρόμενοι, καὶ τὴν πολυπαιδίαν ἀφορμὴν πολέμων καὶ αἰσχροκερδείας ποιούμενοι. Καὶ ἁπλῶς εἰπεῖν, οὐκ ἔστι τι τῶν ἐν τῷ βίῳ, ὃ μὴ πρὸς ἀφορμὴν κακοῦ τοῖς ἀνοήτοις γίνεται, πανταχόθεν στενοχωρουμένοις ὑπὸ τῆς αὐθαιρέτου κακίας, καὶ τοῦ μὴ ἀναβλέπειν πρὸς τὸ θεῖον φῶς, μηδ' ἐπαΐειν ἐθέλειν τῶν ὄντως ἀγαθῶν· ἀλλὰ καταδεδυκότας εἰς τὴν θνητὴν προσπάθειαν ὡς ἐν κλύδωνι τῷ βίῳ φέρεσθαι. Τούτων δὲ λύσις μία ἡ πρὸς θεὸν ἐπιστροφή, ἣν ἐξευρίσκουσιν οἱ τὸ ὄμμα τῆς ψυχῆς καὶ τὸ οὖς πρὸς τὴν τῶν ἀγαθῶν ἀνάληψιν ἐπεγείροντες, καὶ τὸ παρεπόμενον τῇ οὐσίᾳ ἡμῶν κακὸν τῇ ἀναγωγικῇ δυνάμει θεραπεύοντες.", "st": "24.5"}, {"sp": "N", "t": "Ἦν δὲ συμφυὲς ἅμα καὶ ἐπίκτητον ἡμῖν κακὸν ἡ τοῦ αὐτεξουσίου παρὰ φύσιν κίνησις, καθ' ἣν ἐρίζειν τε καὶ ἐναντιοῦσθαι τοῖς θείοις νόμοις πειρώμεθα, οὐδὲ ἐπαισθανόμενοι ὅσον ἑαυτοὺς βλάπτομεν διὰ τοῦ δοκεῖν ἀντιτείνειν θεῷ· ἀλλὰ μόνον τοῦτο τυφλῶς ὁρῶντες, ὅτι ἐδυνήθημεν ἀφηνιάσαι τῶν ἐκείνου θεσμῶν. Καὶ τοῦτο ἦν τὸ πολλῷ τῷ αὐτεξουσίῳ χρήσασθαι καὶ ἀμέτρῳ, τὸ τολμᾶν ἀφίστασθαι θεοῦ, καὶ τὴν λυγρὰν ἔριν πρὸς αὐτὸν ἀναδέχεσθαι, καθ' ἣν ἐρίζομεν τρόπον τινὰ καὶ φιλονεικοῦμεν, ἐκείνου λέγοντος, Μὴ ποιήσῃς τόδε, τοῦτο αὐτὸ μάλιστα ποιεῖν ἐθέλειν· καὶ πάλιν αὖ, εἰ ἐκεῖνος λέγοι, Ποίησον τόδε, αὐτὸ τοῦτο μὴ ποιεῖν· ἵνα ἑκατέρωθεν τῆς ἀθλιότητος ἑαυτοὺς πληρώσωσιν οἱ τὸν θεῖον νόμον ἐκβαίνοντες, τῷ τε μὴ ποιεῖν τὰ προστεταγμένα, καὶ τῷ ποιεῖν τὰ ἀπηγορευμένα.", "st": "24.6"}, {"sp": "N", "t": "Τί οὖν πρὸς τὴν λυγρὰν ταύτην ἔριν, τὴν συνοπαδὸν ἅμα καὶ σύμφυτον λεγομένην, ἐξευρήσομεν, τὴν ἐκ τοῦ ἐφ' ἡμῖν παρὰ φύσιν διατεθέντος ἐγειρομένην, καὶ διὰ τοῦτο, ὡς οἰκεῖον κακόν, λεληθότως βλάπτειν πεφυκυῖαν; Τί πρὸς ταύτην ἀντιτιθέναι δεῖ; τί τοῦ μαινομένου νείκους ἄκος ἐξευρεῖν; τί τῆς καταγωγοῦ δυνάμεως ἔργμα, ἢ τὸ πονεῖν ταῦτα, καὶ ἐκμελετᾶν, καὶ ἐν ἔρωτι τίθεσθαι, ἅπερ τῆς θείας ἀρετῆς ἡμᾶς εἰς ἴχνια θήσει; Ταῦτα γὰρ ἦν ἡ λύσις τῶν κακῶν, ἣν οἱ παῦροι συνίσασι· ταῦτα ἡ τῶν πέλας ὄντων ἀγαθῶν ἀκοὴ καὶ ὄψις· ταῦτα ἡ τῶν αὐθαιρέτων πημάτων ἀπαλλαγή· ταῦτα τῆς ἀπειρίας τῶν παθῶν ἡ τομή. Ταῦτα οὖν καὶ τῆς ἀθέου ἔριδος ἀποφυγὴ γένοιτ' ἄν, καὶ σωτηρία ψυχῆς, καὶ ἀποκάθαρσις τοῦ μαινομένου νείκους, καὶ ἀνάκλησις τῆς θεόθεν φυγῆς. Τὴν γὰρ καταγωγὸν ῥοπὴν τῇ ἀναγωγῷ δυνάμει μόνως ἂν ἰασαίμεθα, εἰ μὴ περαιτέρω προάγοιμεν αὐτήν, μηδ' ἐπὶ κακοῖς κακὰ συντιθείημεν, ἀλλ' ἐπιπειθεῖς γενόμενοι τῷ ὀρθῷ λόγῳ φεύγοιμεν τὴν λυγρὰν ἔριν τῇ ἀγαθῇ ἔριδι, οὐ φιλονεικοῦντες ἀπειθεῖν τῷ θεῷ, ἀλλὰ φιλονεικοῦντες ὅτι μάλιστα αὐτῷ πείθεσθαι· ἣν οὐδὲ ἔριν δεῖ καλεῖν, ἀλλὰ θεοπειθῆ ὑπακοήν, καὶ ἐπιστροφὴν πρὸς τὸν θεῖον νόμον, καὶ ἑκούσιον ὑπόταξιν, τὰς ἀφορμὰς περικόπτουσαν τῆς ἀνοήτου ἀπειθείας.", "st": "24.7"}, {"sp": "N", "t": "Ταῦτα γὰρ οἶμαι πάντα διὰ τῶν προκειμένων ἐπῶν δηλοῦσθαι· τὸ μὲν τῆς αὐτεξουσίου πονηρίας διὰ τοῦ γνώσῃ δ' ἀνθρώπους αὐθαίρετα πήματ' ἔχοντας, οὓς τλήμονας δεῖ καλεῖν καὶ ἀθλίους, ὅτι πρὸς αὐτοπροαίρετον κακίαν εἱλκύσθησαν· τὸ δὲ μηδαμῶς τούτους ἐπαΐειν τῶν καλῶν ἐθέλειν, διὰ τοῦ λέγειν, οἵ τ' ἀγαθῶν πέλας ὄντων οὔτ' ἐσορῶσιν οὔτε κλύουσι· καὶ ὅτι δυνατὸν ἀπολυθῆναι τῶν αὐθαιρέτων κακῶν δηλοῖ τὸ λύσιν δὲ κακῶν παῦροι συνίσασιν, ὃ μεταξὺ παρεμβέβληται, ἵνα τῶν ἐφ' ἡμῖν δείξῃ τὴν λύσιν ὑπάρχουσαν, καὶ τὸν δεσμὸν ἐκ τοῦ ἑκουσίου ἠρτῆσθαι μηνύσῃ. Εἶτα ἐπισυνάπτει τὴν τυφλότητος καὶ κωφότητος ταῖς εἰς κακίαν ἐκπεσούσαις ψυχαῖς αἰτίαν, τοίη μοῖρα βροτῶν βλάπτει φρένας. Εἰς γὰρ ἄνοιαν καὶ ἀπροβούλευτον αἵρεσιν ὁ ἀπὸ τῶν κρειττόνων χωρισμὸς ἄγει, ὃν διὰ τῆς λυγρᾶς μοίρας ἠνίξατο, τῆς ποιούσης ἡμᾶς ἔξω τοῦ θείου χοροῦ τῇ πρὸς τὸ μερικὸν καὶ θνητὸν ζῷον νεύσει. Καὶ τὰ ἑπόμενα τῇ ἀβουλίᾳ παραδείκνυσι, καὶ πῶς ἑκούσια ἅμα καὶ ἀκούσια τὰ πλημμελήματα ἐκδιδάσκει, τῇ κατ' ἐπιπέδου κυλινδρικῇ κινήσει ἐοικέναι φήσας τὸν τῶν ἀνοήτων βίον, ὃς κύκλῳ ἅμα καὶ ἐπ' εὐθείας τότε κινεῖται· κύκλῳ μὲν δι' ἑαυτόν· ἐπ' εὐθείας δέ, διὰ τὴν πτῶσιν. Ὡς γὰρ ὁ κύλινδρος οὐ κατακρατεῖ τῆς περὶ τὸν ἄξονα κυκλικῆς περιαγωγῆς ἀπὸ τῆς ὀρθότητος πλαγιασθείς, οὕτως οὐδὲ ψυχὴ τῆς τεύξεως τῶν ὄντως ἀγαθῶν τυγχάνει, τοῦ ὀρθοῦ λόγου καὶ τῆς πρὸς θεὸν συστάσεως ἀποπεσοῦσα· πλανᾶται δὲ περὶ τὰ δοκοῦντα ἀγαθά, καὶ ἐκφέρεται ἀπ' εὐθείας ταῖς αἰσθητικαῖς προςπαθείαις κυλιομένη· ὃ διὰ τοῦ ἄλλοτ' ἐπ' ἄλλα φέρονται ἀπείρονα πήματ' ἔχοντες παρέστησεν.", "st": "24.8"}, {"sp": "N", "t": "Ἐπειδὴ δὲ τῆς τὰς φρένας βλαπτούσης μοίρας, καὶ τοῦ χωρισμοῦ τοῦ ἀπὸ τῶν θείων, αἴτιον ἦν τὸ αὐτεξούσιον κίνημα παρὰ φύσιν διατεθέν· πῶς δεῖ καὶ τοῦτο κατευνάζειν, καὶ πρὸς θεὸν ἐπιστρέφειν, διὰ τῶν ἑξῆς δύο στίχων ἐδίδαξε· τὴν μὲν αὐτεξούσιον βλάβην οὕτω καταμηνύσας, λυγρὴ γὰρ συνοπαδὸς ἔρις βλάπτουσα λέληθε σύμφυτος, τὴν δὲ αὐτεξούσιον ἴασιν, ἣν οὐ δεῖ προςάγειν, εἴκοντα δὲ φεύγειν. Συνορῶν δέ, ὅτι προηγουμένως τῆς παρὰ τοῦ θεοῦ ἐπικουρίας χρῄζομεν πρὸς ἀποφυγὴν μὲν τῶν κακῶν, ἀνάκτησιν δὲ τῶν ἀγαθῶν, ὥσπερ τινὰ εὐχὴν ἐπήγαγε, καὶ βοηθείας αἴτησιν, τὴν πρὸς τὸν Δί' ἐπιστροφήν.", "st": "24.9"}, {"sp": "SEC", "t": "XXV · 61–66", "st": "25"}, {"sp": "N", "t": "<span class=\"lemma\">Ζεῦ πάτερ, ἦ πολλῶν κε κακῶν λύσειας ἅπαντας,<br>εἰ πᾶσιν δείξαις, οἵῳ τῷ δαίμονι χρῶνται.<br>ἀλλὰ σὺ θάρσει, ἐπεὶ θεῖον γένος ἐστὶ βροτοῖσιν,<br>οἷς ἱερὰ προφέρουσα φύσις δείκνυσιν ἕκαστα.<br>ὧν εἴ σοί τι μέτεστι, κρατήσεις ὧν σε κελεύω,<br>ἐξακέσας ψυχὴν δὲ πόνων ἀπὸ τῶνδε σαώσεις.<\/span>", "st": "25.0"}, {"sp": "N", "t": "Τὸν ποιητὴν καὶ πατέρα τοῦδε τοῦ Παντὸς ἔθος ἦν τοῖς Πυθαγορείοις τῷ τοῦ Διὸς καὶ Ζηνὸς ὀνόματι σεμνύνειν. Δι' ὃν γὰρ τὸ εἶναι καὶ τὸ ζῆν τοῖς πᾶσιν ὑπάρχει, τοῦτον δίκαιον ἀπὸ τῆς ἐνεργείας ὀνομάζεσθαι. Κύριον γὰρ ὄντως ὄνομα θεοῦ, τὸ ταῖς ἐνεργείαις αὐτοῦ καὶ ταῖς ποιήσεσι μάλιστα πρέπον· τὰ δὲ ἐφ' ἡμῶν δοκοῦντα κύρια εἶναι τύχη καὶ προαίρεσις τίθεται μᾶλλον, ἢ ἡ τῆς οὐσίας οἰκειότης ἐξευρίσκει, ὡς ἔστιν ἐπὶ πολλῶν ἰδεῖν ὀνομάτων ἀλλοτρίως τισὶ κειμένων· οἷον, εἰ ὁ πονηρὸς τὸν τρόπον Ἀγάθων καλοῖτο, καὶ εἰ ὁ ἄθεος τὴν γνώμην Εὐσέβιος. Τὰ γὰρ τοιαῦτα οὐδὲν μετέχει τῆς τῶν ὀνομάτων ὀρθότητος, ὅτι μηδὲν τῆς οὐσίας ἢ τῆς ἐνεργείας παρίστησι τῶν πραγμάτων ἐκείνων, οἷς κεῖται ὀνόματα. Τὴν οὖν ὄντως ὀρθότητα τῶν ὀνομάτων ἐν τοῖς ἀϊδίοις τῶν πραγμάτων χρὴ ζητεῖν· καὶ τούτων ἐν τοῖς θείοις· καὶ τῶν θείων ἐν τοῖς ἀρίστοις. Ὅθεν καὶ τὸ τοῦ Διὸς ὄνομα σύμβολόν ἐστι καὶ εἰκὼν ἐν φωνῇ δημιουργικῆς οὐσίας, τῷ τοὺς πρώτους θεμένους τοῖς πράγμασι τὰ ὀνόματα, διὰ σοφίας ὑπερβολήν, ὥσπερ τινὰς ἀγαλματοποιοὺς ἀρίστους, διὰ τῶν ὀνομάτων, ὡς δι' εἰκόνων, ἐμφανίσαι αὐτῶν τὰς δυνάμεις. Τὰ γὰρ ἐν τῇ φωνῇ ὀνόματα σύμβολα τῶν ἐν τῇ ψυχῇ νοήσεων ἀπειργάζοντο, τὰς δὲ νοήσεις αὐτὰς γνωστικὰς εἰκόνας τῶν νοηθέντων πραγμάτων ἐποιοῦντο. Τῇ γὰρ πρὸς τὰ νοητὰ ἐπιστροφῇ θεωρίας πλησθέντες, κἀκεῖθεν ἐγκύμονες γενόμενοι νοερῶν ὠδίνων, εἰς φωνὰς ἤδη προϊόντες τοιαῦτα ἐτίθεντο τοῖς οὖσι τὰ ὀνόματα, ἃ δι' αὐτῆς τῆς φωνῆς, καὶ τῶν εἰς τὴν ταύτης ἐκφώνησιν παραληφθέντων στοιχείων, ὡς οἷόν τε ἦν, ἀπετύπου τῶν ὀνομαζομένων τὰ εἴδη, καὶ ἐπέστρεφε πρὸς αὐτὰς τὰς οὐσίας τοὺς ὀρθῶς αὐτῶν κατακούοντας· ὥστε γίνεσθαι τὸ πέρας τῆς ἐκείνων θεωρίας ἀρχὴν ἡμῖν πρὸς εὕρεσιν τῆς τῶν πραγμάτων νοήσεως. Οὕτω μὲν οὖν ὁ δημιουργὸς αὐτοῖς πάλαι μὲν τετρακτύς, νῦν δὲ Ζεὺς πατήρ, δι' ἃς εἴπομεν αἰτίας, ὠνόμασται.", "st": "25.1"}, {"sp": "N", "t": "<span class=\"sm-q\"><span class=\"sm-qi\">Ὃ δὲ αἰτεῖ παρ' αὐτοῦ τῆς παρούσης εὐχῆς ὁ λόγος, τοῦτο ἤδη τοῖς πᾶσιν ἐφήπλωται δι' ἀγαθότητα· παρ' ἡμῖν δέ ἐστι τὸ λαβεῖν τὸ ἀεὶ παρ' ἐκείνου διδόμενον. Καὶ γὰρ ἐν τοῖς προτέροις ἐλέγετο,<br>ἔρχευ ἐπ' ἔργον<br>θεοῖσιν ἐπευξάμενος,<br>ὡς ἐκείνων μὲν ἀεὶ διδόντων τὰ ἀγαθά, ἡμῶν δὲ τότε αὐτὰ δεχομένων, ὅταν ἑαυτοὺς πρὸς τὴν θείαν δόσιν συντείνωμεν· τὸ γὰρ αὐτεξούσιον οὐκ ἂν λάβοι τὰ ὄντως ἀγαθά, μὴ βουλόμενον λαβεῖν. Ταῦτα δέ ἐστιν ἀλήθεια καὶ ἀρετή, ἀπὸ τῆς δημιουργικῆς αἰτίας ἀεὶ καὶ ὡσαύτως πᾶσιν ἐλλαμπόμενα. Καὶ νῦν δὲ ὁ λόγος ὡς ἀναγκαῖον πρὸς τὴν τῶν κακῶν λύσιν ἀπαιτεῖ τὴν ἑαυτῶν οὐσίαν ἡμᾶς ἰδεῖν· τοῦτο γὰρ ἦν τὸ οἵῳ τῷ δαίμονι χρῶνται· ἀντὶ τοῦ, οἵᾳ ψυχῇ. Τῇ δὲ τοιαύτῃ εἰς ἑαυτοὺς ἐπιστροφῇ διορίζεται ἐξ ἀνάγκης ἕπεσθαι καὶ τὴν ἀποφυγὴν τῶν κακῶν, καὶ τὴν ἔκφανσιν τῶν πρὸς εὐδαιμονίαν ὑπὸ τοῦ θεοῦ προτεινομένων. Ἐξ ὑποθέσεως οὖν πρόεισιν ὁ λόγος, ὅτι εἰ πάντες ἴδοιεν ὅ εἰσι, καὶ οἵῳ τῷ δαίμονι χρῶνται, πάντες ἀπολυθεῖεν ἂν τῶν κακῶν. Τοῦτο δὲ ἀδύνατον. Οὐ γὰρ οἷόν τε πάντας ὁμοῦ φιλοσοφῆσαι, καὶ ὑποδέξασθαι τὰ παρὰ τοῦ θεοῦ ἀεὶ προςφερόμενα ἀγαθὰ πρὸς εὐζωΐας τελειότητα. Τί οὖν τὸ λειπόμενον, ἢ τούτους μόνους χρῆναι θαῤῥεῖν τοὺς προσιόντας τῇ ἀναφαινούσῃ τὰ οἰκεῖα ἡμῖν ἀγαθὰ ἐπιστήμῃ; μόνους γὰρ τούτους ἀπολυθήσεσθαι τῶν παραπεπηγότων κακῶν τῇ θνητῇ φύσει· ἐπειδὴ καὶ μόνοι πρὸς τὴν θεωρίαν τῶν ὄντως ἀγαθῶν ἐπεστράφησαν, οὓς ἄξιον καὶ εἰς τὸ θεῖον γένος ἐγγράφειν, ὡς ὑπὸ τῆς ἱερᾶς φύσεως, τουτέστι φιλοσοφίας, διδαχθέντας, καὶ ἀσκηθέντας τὰ δέοντα. Τῆς δὲ κοινωνίας τῶν θείων ἀνδρῶν εἴ τι μέτεστιν ἡμῖν δηλώσομεν ἀντεχόμενοι τῶν σπουδαίων ἔργων καὶ τῶν ἐπιστημονικῶν γνώσεων· οἷς μόνοις ἡ τοῦ ἀνθρώπου ψυχὴ θεραπεύεται, καὶ τῶν τῇδε ἐλευθεροῦται πόνων εἰς τὴν θείαν λῆξιν μεθισταμένη.<\/span><\/span>", "st": "25.2"}, {"sp": "N", "t": "Συνελόντι οὖν εἰπεῖν, ὁ νοῦς τῶν προκειμένων ἐπῶν ἐστι τοιοῦτος· οἱ γνόντες ἑαυτοὺς ἀπολύονται τῆς θνητῆς ἐμπαθείας. Διὰ τί οὖν οὐ πάντες ἀπολύονται, πάντες ἀφορμὰς ἔχοντες ἐμφύτους πρὸς ἐπίγνωσιν τῆς ἑαυτῶν οὐσίας; Ὅτι οἱ πλεῖστοι, ὡς ἔφην, αὐθαίρετα πήματ' ἔχοντές εἰσιν, οἳ τῶν ἀγαθῶν πέλας ὄντων οὔτ' ἐσορῶσιν οὔτε κλύουσιν. Ὀλίγοι δέ εἰσιν οἱ τὴν τῶν κακῶν λύσιν συνιέντες ἐκ τοῦ γνῶναι οἵῳ τῷ δαίμονι χρῶνται· οὗτοι δέ εἰσιν οἱ φιλοσοφίᾳ καθαιρόμενοι τῶν τῆς ἀλογίας παθῶν, καὶ ἐκ τῶν τῇδε τόπων, ὥσπερ ἐκ δεσμωτηρίων, ἐλευθερούμενοι.", "st": "25.3"}, {"sp": "N", "t": "Πῶς οὖν φησι πρὸς τὸν Δία· ἦ πολλῶν κε κακῶν λύσειας ἅπαντας, εἰ πᾶσιν δείξαις οἵῳ τῷ δαίμονι χρῶνται; Ἆρα ὡς ἐπ' ἐκείνῳ ὂν καὶ ἄκοντας ἐπιστρέψαι πρὸς τὴν ἀλήθειαν ἅπαντας, ἀμελείᾳ δὲ ἢ ἐπιβουλῇ τοῦτο μὴ ποιοῦντος, ἵν' ἐν τοῖς δεσμοῖς κατέχοιντο; Ἦ ταῦτα μὲν οὐδ' ὅσιον ἐπινοεῖν. Ἐκεῖνο δὲ μᾶλλον ὁ λόγος ἐπιδείκνυται, ὅτι ἐπὶ τὸν θεόν, ὡς πρὸς πατέρα, ἐπιστραφῆναι δεῖ τὸν πρὸς εὐζωΐαν ἐπειγόμενον. Ἔστι γὰρ ὁ θεὸς δημιουργὸς μὲν πάντων, τῶν δὲ ἀγαθῶν καὶ πατήρ. Ὁ γοῦν τὴν λύσιν τῶν κακῶν συνιείς, καὶ τῶν αὐθαιρέτων πημάτων ἐλευθερούμενος, καὶ τὴν λυγρὰν ἔριν περικόπτων τῇ ἑκουσίῳ φυγῇ, οὗτος πρὸς τὴν ἐκ τοῦ θεοῦ καθήκουσαν ἀΐδιον βοήθειαν ἐπιστρεφόμενος, ἀναβοᾷ τὸ Ζεῦ πάτερ, τῷ ἤδη προειργάσθαι τὰ παιδὸς ἄξια τὸν θεὸν πατέρα καλῶν· καὶ ἐννοεῖ, τὸ ἐφ' ἑαυτοῦ συμβαῖνον ὡς εἰ γένοιτο ἐπὶ πάντων, πάντες ὁμοίως ἂν αὐτῷ κακῶν ἀπολυθεῖεν. Εἶθ' εὑρὼν τοῦτο μὴ προβαῖνον, οὐ διὰ τὸν θεόν, ἀλλὰ διὰ τοὺς πλείστους αὐθαίρετα πήματ' ἔχοντας, λέγει πρὸς ἑαυτόν, ἀλλὰ σὺ θάρσει, ὡς τὴν ὁδὸν ἐξευρηκὼς τῆς ἀπολύσεως τῶν κακῶν. Αὕτη δὲ ἦν ἡ διὰ τῆς ἱερᾶς φιλοσοφίας ἐπιστροφὴ πρὸς τὰ δεικνύμενα ὑπὸ τοῦ θεοῦ, ἃ οἱ πολλοὶ οὐχ ὁρῶσι, διὰ τὸ μὴ ὀρθῶς χρῆσθαι ταῖς κοιναῖς ἐννοίαις, ἃς προσέφυσεν ὁ δημιουργὸς τῷ λογικῷ γένει πρὸς ἐπίγνωσιν ἑαυτοῦ.", "st": "25.4"}, {"sp": "N", "t": "Ἐπεὶ οὖν τὸ δεῖξαί τινι ὁτιοῦν δύο προσώπων ἐνεργείας εἰς ταὐτὸν συνδραμούσας ἐμφαίνει (πῶς γὰρ ἂν δείξαις τυφλῷ, κἂν μυριάκις προσφέρῃς ὃ βούλει δεῖξαι, ἢ πῶς ἂν τῷ ὁρῶντι δείξαις μηδὲν προσάγων;), ἀμφότερα οὖν παρεῖναι δεῖ· τό τε παρὰ τοῦ δεικνύντος προσαγόμενον ἀγαθόν, καὶ τὸ παρὰ τοῦ ᾧ δείκνυται διορατικὸν ὄμμα· ἵνα ἐκεῖθεν μὲν τὸ ὁρατόν, ἐντεῦθεν δὲ ἡ ὅρασις, συνδράμῃ πρὸς τὴν τῆς δείξεως συμπλήρωσιν. Τούτων δὲ οὕτως ἐχόντων, λάβωμεν ὑπόθεσιν πάντας ἅμα ἀπολυθῆναι ἂν τῶν κακῶν, εἰ πᾶσι δείξειεν ὁ δημιουργὸς καὶ ἐμφανίσειε τὴν τῆς ἑαυτῶν οὐσίας ἐπίγνωσιν, καὶ οἵῳ τῷ δαίμονι χρῶνται. Ἀλλὰ μὴν οὐ πάντες ἅμα ἀπολύονται τῶν κακῶν. Οὐκ ἄρα πᾶσι δείκνυσιν, ἀλλὰ μόνοις ἐκείνοις τοῖς πρὸς ἀπόλυσιν τῶν κακῶν οἴκοθεν ὡρμημένοις, καὶ τὸ παρ' ἑαυτῶν ὄμμα πρὸς θέαν τοῦ δεικνυμένου καὶ ὑποδοχὴν ἀνατείνασιν. Οὐκ ἄρα αὐτὸς αἴτιος τοῦ μὴ πᾶσι δεῖξαι, ἀλλ' οἱ τῶν ἀγαθῶν πέλας ὄντων οὔτ' ἐσορῶντες οὔτε κλύοντες, καὶ διὰ τοῦτ' αὐθαίρετα πήματ' ἔχειν λεγόμενοι. Αἰτία οὖν τοῦ ἑλομένου· θεὸς δὲ κακῶν ἀναίτιος, προλάμπων μὲν ἀεὶ τὰ ἀγαθὰ πᾶσιν, ὅσον ἐφ' ἑαυτῷ, οὐ δεικνὺς δὲ ἀεὶ πᾶσιν, τῷ τὸ θεωρὸν ὄμμα τῶν προτεινομένων ἀγαθῶν ἐν τοῖς πλείστοις μεμυκέναι, καὶ κάτω νεύειν ἀσχολίᾳ τῇ πρὸς τὰ χείρονα.", "st": "25.5"}, {"sp": "N", "t": "Ἡ δὲ τοιαύτη τῶν προκειμένων ἐπῶν ἐξήγησις καὶ πρὸς τὴν ἀλήθειαν αὐτὴν συμφωνεῖ, καὶ πρὸς τὴν τῶν ὑπερκειμένων ἐπῶν διάνοιαν. Εἰ γὰρ ἐπὶ τῷ θεῷ ἐστιν ἑλκύσαι πρὸς τὴν ἀλήθειαν τοὺς ἀνθρώπους καὶ ἄκοντας, τί αὐθαίρετα πήματ' ἔχειν αὐτοῖς ἐπεγκαλοῦμεν; τί δὲ συμβουλεύομεν ὡς τὴν ἔριν οὐ δεῖ προσάγειν, εἴκοντα δὲ φεύγειν; ἢ τί τὰ συμβαίνοντα πράως φέρειν, καὶ ἰᾶσθαι σπουδάζειν, ἐπιτάττομεν; ὅλως γὰρ ἡ διὰ μαθήσεως πρὸς ἀρετὴν ὁδὸς ἀποκέκλεισται τοῖς τὸ ἐφ' ἡμῖν ἀναιροῦσιν. Οὐ γὰρ ἂν ἔδει πονεῖν, οὐδὲ ἐν μελέτῃ καὶ ἔρωτι τίθεσθαι τὰ καλά, εἰ τοῦ θεοῦ ἴδιον ἦν σῴζειν ἡμᾶς ἀπὸ κακίας, καὶ τῶν ἀρετῶν πλήρεις ποιεῖν μηδὲν παρ' ἑαυτῶν συνεισφέροντας. Ἀλλ' οὕτως ἂν ἡ αἰτία τῆς τῶν πολλῶν πονηρίας θεοῦ ἦν ἔγκλημα. Εἰ δὲ ἀναίτιος κακῶν ὁ θεός, ὥσπερ καὶ λέγεται καὶ ἔστι, δῆλον ὡς παρ' ἡμᾶς ἡ τῶν ἀγαθῶν ἀπόστασις, ὅτι πέλας ὄντων αὐτῶν, καὶ ἐν ἡμῖν κατὰ τὰς φυσικὰς ἐννοίας κειμένων, οὔτ' ἐσορῶμεν οὔτε κλύομεν. Αἰτία δὲ τῆς ἀβλεψίας ταύτης καὶ ἀνηκοΐας ἡ λυγρὰ ἔρις, αὐθαίρετος οὖσα βλάβη, ἣν οὐ δεῖ προάγειν ἐπὶ πλεῖον, εἴκοντα δὲ φεύγειν ἀπ' αὐτῆς, καὶ τὴν τῶν κακῶν λύσιν συνιέναι, καὶ τὴν εἰς θεὸν ἐπιστροφὴν ἐξευρίσκειν. Οὕτω γὰρ ἡ παρὰ τοῦ θεοῦ ἔλλαμψις, τῆς παρ' ἡμῶν ὁράσεως αὐτῇ συντρεχούσης, δεῖξις γίνεται. Ἔργα δὲ τῆς δείξεως, ψυχῆς ἄκεσις, καὶ σωτηρία ἀπὸ τῶν τῇδε πόνων, καὶ συναίσθησις τῶν θείων ἀγαθῶν, καὶ κοινωνία τῆς πατρικῆς πολιτείας.", "st": "25.6"}, {"sp": "N", "t": "Τοσαῦτα περὶ ἀρετῆς καὶ ἀληθείας προειπών, καὶ τὰ μὲν τῆς ἀρετῆς παραγγέλματα εἰς τὸν νυκτερινὸν σύλλογον περατώσας, τὰς δὲ τῆς ἀληθείας ἐλπίδας ἕως τῆς ἀκέσεως καὶ σωτηρίας τῆς ψυχῆς ὁρίσας, ἐπάγει τὰ περὶ τῆς τοῦ αὐγοειδοῦς καθαρότητος πτερωτικῆς, τρίτον τι φιλοσοφίας γένος ἐπισυνάπτων τοῖς προειρημένοις.", "st": "25.7"}, {"sp": "SEC", "t": "XXVI · 67–69", "st": "26"}, {"sp": "N", "t": "<span class=\"lemma\">Ἀλλ' εἴργου βρωτῶν, ὧν εἴπομεν, ἔν τε καθαρμοῖς,<br>ἔν τε λύσει ψυχῆς κρίνων, καὶ φράζευ ἕκαστα,<br>ἡνίοχον γνώμην στήσας καθύπερθεν ἀρίστην.<\/span>", "st": "26.0"}, {"sp": "N", "t": "Ἡ λογικὴ οὐσία συμφυὲς ἔχουσα σῶμα παρὰ τοῦ δημιουργοῦ εἰς τὸ εἶναι παρῆλθεν, ὡς μήτε τὸ σῶμα εἶναι αὐτήν, μήτε ἄνευ σώματος· ἀλλ' αὐτὴν μὲν ἀσώματον, ἀποπερατοῦσθαι δὲ εἰς σῶμα τὸ ὅλον αὐτῆς εἶδος. Οἷον γὰρ ἐπὶ τῶν ἄστρων, τὸ μὲν ἄνω αὐτῶν ἀσώματος οὐσία, τὸ δὲ κάτω, σωματική· καὶ ἔστιν ἥλιος τὸ ὅλον τὸ ἐξ ἀσωμάτου καὶ σώματος, οὐ ποτὲ διεστώτων, εἶτα συνελθόντων (οὕτω γὰρ ἂν καὶ διέστη πάλιν), ἀλλ' ἅμα συνδεδημιουργημένων, καὶ ἐν τάξει συμπεφυκότων, ὡς τὸ μὲν ἡγούμενον εἶναι, τὸ δὲ ἑπόμενον. Οὕτως ἔχει καὶ ἐπὶ τῶν ἐφεξῆς λογικῶν γενῶν, τοῦ τε ἡρωϊκοῦ καὶ τοῦ ἀνθρωπίνου· καὶ ἔστιν ἕκαστος ἥρως ψυχὴ λογικὴ μετὰ φωτεινοῦ σώματος· καὶ ὁ ἄνθρωπος ὁμοίως ψυχὴ λογικὴ μετὰ συμφυοῦς ἀθανάτου σώματος. Καὶ τοῦτο τῶν Πυθαγορείων ἦν δόγμα, ὃ δὴ Πλάτων ὕστερον ἐξέφηνεν, ἀπεικάσας ξυμφύτῳ δυνάμει ὑποπτέρου ζεύγους τε καὶ ἡνιόχου πᾶσαν θείαν τε καὶ ἀνθρωπίνην ψυχήν.", "st": "26.1"}, {"sp": "N", "t": "Δεῖ οὖν πρὸς μὲν τελείωσιν τῆς ψυχῆς ἀληθείας ἡμῖν καὶ ἀρετῆς· πρὸς δὲ κάθαρσιν τοῦ αὐγοειδοῦς ἡμῶν σώματος, τῆς τῶν ὑλικῶν μολυσμῶν ἀποθέσεως, καὶ τῶν ἱερῶν καθαρμῶν παραλήψεως, καὶ τῆς ἐπεγειρούσης ἡμᾶς πρὸς τὴν ἐντεῦθεν ἀνάπτησιν θεοσυνδέτου ἀλκῆς. Περὶ ὧν οἱ προκείμενοι στίχοι διδάσκουσι, τὰ μὲν περιττὰ μολύσματα τῆς ὕλης περικόπτοντες διὰ τοῦ «εἴργου βρωτῶν ὧν εἴπομεν»· τὴν δὲ ἱερὰν κάθαρσιν καὶ τὴν θεοσύνδετον ἀλκὴν ἐντιθέντες δι' ὧν ἠνίξαντο οὑτωσὶ λέγοντες, «ἔν τε καθαρμοῖς, ἔν τε λύσει ψυχῆς κρίνων»· καὶ τὸ ὅλον εἶδος τῆς ἀνθρωπίνης οὐσίας ὁλόκληρον ἡμῖν ἀποδεδώκασι δι' ὧν ἐπήγαγον, «ἡνίοχον γνώμην στήσας καθύπερθεν ἀρίστην». Τοῦτο γὰρ καὶ τὴν ὅλην οὐσίαν τοῦ ἀνθρώπου παρέστησε, καὶ τὴν τάξιν τῶν ἐν αὐτῇ μερῶν διεστείλατο, ὅτι τὸ μὲν κριτικόν, ὡς ἡνιοχοῦν· τὸ δὲ ἑπόμενον, ὡς ἡνιοχούμενον.", "st": "26.2"}, {"sp": "N", "t": "Ταῦτα γάρ ἐστιν ἐκ τῶν προκειμένων ἐπῶν διδαχθῆναι τὸν τῶν Πυθαγορείων συμβόλων μὴ ἀνήκοον, ὅτι δεῖ σὺν τῇ ἀσκήσει τῆς ἀρετῆς καὶ τῇ ἀναλήψει τῆς ἀληθείας καὶ καθαρότητος ἐπιμέλειαν ποιεῖσθαι τῆς περὶ τὸ αὐγοειδὲς ἡμῶν σῶμα, ὃ καὶ ψυχῆς λεπτὸν ὄχημα οἱ χρησμοὶ καλοῦσι. Διατείνει δὲ αὕτη ἡ κάθαρσις ἕως σιτίων καὶ ποτῶν, καὶ τῆς ὅλης διαίτης τοῦ θνητοῦ ἡμῶν σώματος, ἐν ᾧ τὸ αὐγοειδὲς ἔγκειται προσπνέον τῷ ἀψύχῳ σώματι ζωήν, καὶ τὴν ἁρμονίαν αὐτοῦ συνέχον. Ζωὴ γάρ τίς ἐστι τὸ ἄϋλον σῶμα, καὶ ζωῆς ἐνύλου γεννητικόν, δι' ἧς τὸ θνητὸν ἡμῶν ζῷον συμπληροῦται, ἐκ τῆς ἀλόγου ζωῆς καὶ τοῦ ὑλικοῦ σώματος συγκείμενον, εἴδωλον ὂν τοῦ ἀνθρώπου, ὃς ἐκ λογικῆς οὐσίας καὶ σώματος ἀΰλου συνέστηκεν.", "st": "26.3"}, {"sp": "N", "t": "Ἐπεὶ οὖν ἡμεῖς ὁ ἄνθρωπος, ἄνθρωπος δὲ διὰ ταῦτα· προσήκει διὰ πάντων μὲν καθήρασθαι καὶ τελειωθῆναι, τὸν δὲ ἐπιβάλλοντα τρόπον ἐφ' ἑκάστης φύσεως τηρῆσαι. Ἔστι γὰρ ἄλλη ἄλλου κάθαρσις. Οἷον, ψυχῆς λογικῆς, κατὰ μὲν τὸ λογικόν, κάθαρσις ἐπιστημονικὴ ἀλήθεια· κατὰ δὲ τὸ δοξαστικόν, ἡ βουλευτικὴ ἀρετή. Θεωρεῖν γὰρ τὰ ἄνω πεφυκότες, καὶ τάττειν τὰ κάτω, ἀληθείας μὲν πρὸς ἐκεῖνα, πολιτικῆς δὲ ἀρετῆς πρὸς ταῦτα δεησόμεθα, ὅπως ἂν τῶν μὲν ἀϊδίων θεωρητικοὶ γινώμεθα, τῶν δὲ ἐνδεχομένων πρακτικοί. Κατ' ἀμφότερα δὲ τοῖς θείοις ὅροις ἐμμένοντες τὸν τῆς ἀλογίας ἂν ἀποφύγοιμεν κλύδωνα. Ἀπὸ ταύτης γὰρ δεῖ καθήρασθαι τὴν λογικὴν ἡμῶν οὐσίαν, ἐπειδὴ καὶ ταύτῃ προσῆλθεν ἐν τῇ εἰς γένεσιν νεύσει. Ἀλλὰ δὴ καὶ τῷ αὐγοειδεῖ ἡμῶν σώματι προσέφυ σῶμα θνητὸν ὄν, καθαρεῦσαι δεῖ καὶ τοῦτο, καὶ τῆς πρὸς αὐτὸ συμπαθείας ἀπαλλαγῆναι.", "st": "26.4"}, {"sp": "N", "t": "Λείπεται δὴ οὖν ἡ τοῦ ψυχικοῦ σώματος κάθαρσις, ἣν ποιήσασθαι δεῖ τοῖς ἱεροῖς ἑπόμενον θεσμοῖς καὶ ταῖς τῶν ἱερῶν τέχναις. Σωματικωτέρα δέ πως αὕτη ἡ κάθαρσις· διὸ καὶ ὑλῶν ἐφάπτεται παντοδαπῶν, θεραπεύουσα παντοίως καὶ μεταπείθουσα δραστηρίως τὸ ζωτικὸν τοῦτο σῶμα χωρισθῆναι τῆς ὕλης, καὶ ἀναπτῆναι πρὸς τὸν αἰθέριον τόπον, ὅπου τὴν κατάταξιν ἔχειν αὐτῷ εὐδαιμονία ἦν πρώτη. Πάντα δὲ τὰ περὶ τοῦτο δρώμενα, ἐὰν θεοπρεπῶς καὶ μὴ ἀγυρτικῶς γίνηται, συνεπόμενα τοῖς τῆς ἀρετῆς καὶ ἀληθείας κανόσιν εὑρίσκεται. Αἱ γὰρ τῆς λογικῆς ψυχῆς καθάρσεις καὶ τοῦ αὐγοειδοῦς ὀχήματος προμηθοῦνται, ὅπως ἂν αὐταῖς ὑπόπτερον καὶ τοῦτο γενόμενον μὴ ἐμποδὼν ἵστηται πρὸς τὴν ἄνω πορείαν. Πτεροφυΐα δὲ αὐτοῦ ἀρίστη, ἡ κατὰ μικρὸν μελέτη τῆς τῶν περιγείων ἀποστάσεως, καὶ ὁ πρὸς τὴν ἀϋλίαν ἐθισμός, καὶ ἡ ἀπόθεσις ὧν ἂν ἐπλήσθη μολυσμῶν ἐκ τῆς πρὸς τὸ ὑλικὸν σῶμα συζεύξεως. Διὰ γὰρ τούτων ἀναβιώσκεται τρόπον τινά, καὶ συλλέγεται, καὶ θείου πληροῦται τόνου, καὶ τῇ νοερᾷ τελειότητι τῆς ψυχῆς συνάπτεται.", "st": "26.5"}, {"sp": "N", "t": "Τί οὖν ἡ ἐνίων βρωμάτων ἀποχὴ πρὸς ταῦτα συμβάλλοιτο ἄν; Τοῖς ἐθιζομένοις ἀπὸ πάντων χωρίζεσθαι τῶν θνητῶν, τὸ τινῶν ἐντεῦθεν ἤδη παντελῶς ἀποσχέσθαι, καὶ μάλιστα τῶν γλυκυθυμούντων καὶ κατατεινόντων εἰς γένεσιν τὸ θνητὸν σῶμα, πρὸ ὁδοῦ ἂν γένοιτο εἰς κάθαρσιν. Διὸ καὶ ἐν τοῖς συμβολικοῖς παραγγέλμασιν ἐπετάττετό τινων ἀποχή, μείζονα μὲν καὶ καθολικώτερον ἔχουσα τὸν προηγούμενον νοῦν, ἑπομένως δὲ καὶ τοῦ μερικοῦ τούτου ἀπείργουσα, οὗ ἂν τὴν μνήμην ἑκάστοτε ποιῆται· οἷον, «μήτραν ζῴου μὴ ἐσθίειν». Τοῦτο δὲ οὑτωσὶ λεγόμενον ἑνός τινος ἀφίστησιν ἡμᾶς τῶν περὶ γῆν, καὶ τούτου σμικροτάτου. Ἐὰν δὲ εἰς τὸ πολύνουν τῆς Πυθαγορικῆς βαθύτητος ἀπίδῃς, τὴν ὅλης τῆς γενέσεως ἀποχὴν δι' ἑνός τινος παραδείγματος διδαχθήσῃ· καὶ ὡς ἐν βρώμασι τοῦτο οὐ προσοισόμεθα, οὕτως ἐν τοῖς τοῦ αὐγοειδοῦς καθαρσίοις τὸ ἀπὸ τούτου νοούμενον ἐπιτηδεύσομεν. Ὁμοίως δὲ καὶ τὸ «καρδίαν μὴ ἐσθίειν» προηγουμένως μὲν εἰς τὴν τοῦ θυμικοῦ κατάστασιν μὴ ἰέναι λέγει· κατ' ἐπακολούθησιν δέ, καὶ τὴν τούτου τοῦ μέρους ἀποχὴν εἰσηγεῖται. Κατὰ δὲ τὸν αὐτὸν λόγον, καὶ τὸ «θνησιμαίων ἀπέχεσθαι» δεῖν θεωρήσομεν τὸ μὲν ὅλον τῆς θνητῆς φύσεως ἀπείργειν ἡμᾶς, ἤδη δὲ καὶ τῆς τῶν ἀθύτων καὶ ἀνιέρων σαρκῶν μεταλήψεως. Δίκαιον γὰρ τῶν συμβολικῶν νουθετήσεων καὶ τὸ προφαινόμενον φυλάττειν καὶ τὸ εἴσω νοούμενον. Ἐκ γὰρ τῆς συνεχοῦς τοῦ φαινομένου τηρήσεως ἡ τῶν μειζόνων μελετᾶται κατόρθωσις.", "st": "26.6"}, {"sp": "N", "t": "Οὕτως οὖν καὶ νῦν ἀκουσόμεθα, ὡς διὰ βραχυτάτου τοῦ λόγου μεγίστων ἔργων ἀρχὰς ἡμῖν ἐνδιδόντος τοῦ ἔπους. «Εἴργου» γάρ φησι «βρωμάτων», ὃ ταὐτόν ἐστι τῷ «ἀπέχου φθαρτῶν σωμάτων». Ἐπεὶ δὲ οὐ πάντων νῦν ἀπέχεσθαι δυνατόν, ἐπάγει «ὧν εἴπομεν». Καὶ ποῦ περὶ τούτων εἴρηται ὑποδείκνυσιν, «ἔν τε καθαρμοῖς, ἔν τε λύσει ψυχῆς»· ἵν' ἡ ἀποχὴ τῶν τροφῶν τῆς διαυγείας τοῦ σωματικοῦ ὀχήματος ἐπιμέλειαν ποιῆται πρέπουσαν τῇ καθαιρομένῃ ψυχῇ καὶ ἀπολυομένῃ τῶν ὑλικῶν κατοχῶν. Τῇ δὲ τοιαύτῃ ἐπιτηδεύσει τὸν κριτικὸν ἐπέστησε λογισμόν, τὸν δυνάμενον τὴν τοῦ αὐγοειδοῦς θεραπείαν τῇ καθαρότητι τῆς ψυχῆς σύμφωνον ἀποδοῦναι. Διὸ καὶ ἡνίοχον γνώμην αὐτὸν προσηγόρευσεν, ὡς ἐφεστάναι πεφυκότα τῇ τοῦ ὀχήματος εὐταξίᾳ. Γνώμην μέν, ὅτι λογικῆς ψυχῆς δύναμις ἦν· ἡνίοχον δέ, ὅτι ἐφαπτομένη καὶ ἐπιστατοῦσα τοῦ σώματος. Τὸ δὲ ὁρατικὸν ὄμμα ὑπὲρ τὸν ἡνίοχον τέτακται. Εἰ γὰρ καὶ μία ψυχή, ἀλλ' ὄμματι μὲν οἷον θεωρεῖ τὸ τῆς ἀληθείας πεδίον· τῇ δὲ ἀναλόγῳ πρὸς χεῖρα δυνάμει τὸ συμφυὲς σῶμα κατέχει, καὶ πρὸς ἑαυτὴν ἐπιστρέφει, ἵν' ὅλη πρὸς τὸ θεῖον ἴδῃ, καὶ τὴν θείαν ὁμοίωσιν κτήσηται.", "st": "26.7"}, {"sp": "N", "t": "Καὶ ὁ μὲν καθόλου τῆς ἀποχῆς τύπος τοιοῦτος, καὶ τοσούτων ἀγαθῶν στοχαζόμενος· τὰ δὲ ἐπὶ μέρους ἐν τοῖς ἱεροῖς ἀποφθέγμασιν ἐν ἀπορρήτῳ παρεδίδοτο· ὧν ἕκαστον εἰ καὶ μερικὴν ἀποχὴν εἰσηγεῖτο, οἷον κυάμων μὲν ἐν σπέρμασι, θνησειδίων δὲ ἐν ζῴοις, καὶ τούτων κατὰ γένος, ὡς ἐπὶ ἰχθύων τὸ ἐρυθρίνου ἀπέχεσθαι, καὶ ἐν χερσαίοις ἄλλου, καὶ ἑτέρου τινὸς ἐν πτηνοῖς, καὶ τὸ τελευταῖον, μέρη τινὰ ζῴων ἀπηγόρευεν, οἷον κεφαλὴν μὴ ἐσθίειν, μηδὲ καρδίαν· ὅμως καὶ ἐν ἑκάστῳ τούτων τὴν τελειότητα τῆς καθάρσεως ἐναπετυποῦτο ὁ λόγος· διὰ μέν τινας φυσικὰς ἰδιότητας τόδε ἢ τόδε εἰς σωματικὴν ἀποχὴν κατατάξας, δι' ἑκάστου δὲ τῆς θνητῆς προσπαθείας κάθαρσιν εἰσηγούμενος, καὶ ἐθίζων διὰ πάντων εἰς ἑαυτὸν ἐπιστραφῆναι τὸν ἄνθρωπον, καὶ τοῦ μὲν τῆς γενέσεως καὶ φθορᾶς τόπου ἐξαναδῦναι, πρὸς δὲ τὸ Ἠλύσιον πεδίον καὶ Αἰθέρα τὸν ἐλεύθερον μετοικίσασθαι.", "st": "26.8"}, {"sp": "N", "t": "Ἐπειδὴ δὲ ἐν τάξει τὴν ἐπίδοσιν τῆς ἀποχῆς ἐποιοῦντο, διὰ τοῦτο καὶ μαχόμενα, ὡς ἂν οἰηθείη τις, εὑρίσκεται παρ' αὐτοῖς σύμβολα. Τῷ γὰρ «ζῴων ἀπέχεσθαι» τὸ «καρδίας ἀπέχεσθαι» ἐναντίον· εἰ μή πού τις τὸ μὲν «καρδίας ἀπέχου» τοῖς ἀρχομένοις παρηγγέλθαι λέγοι, τὸ δὲ «ζῴων» τοῖς ἤδη τελείοις. Περιττὴ γὰρ ἡ κατὰ μέρος ἀποχή, οἷς τὸ ὅλον ζῷον ἀπηγορεύετο. Διὸ οὐ παρέργως προσέχειν δεῖ τῇ τάξει τῆς ἀναβάσεως, ἣν ἐμφαίνει τὰ ἔπη. «Εἴργου» γάρ φησι «βρωμάτων»· εἶτα, ὡς ἐρωτῶντός τινος, «ποίων;» ἀπεκρίνατο, «ὧν εἴπομεν». Καὶ πάλιν, ὡς πρὸς δευτέραν πεῦσιν ζητοῦσαν, ποῦ εἶπον περὶ τούτων οἱ Πυθαγόρειοι, καὶ ἐν ποίαις μαθημάτων παραδόσεσιν ἀποχὰς βρωμάτων συνέφηναν, ἐπήγαγεν, «ἔν τε καθαρμοῖς, ἔν τε λύσει ψυχῆς»· ὡς τῶν μὲν καθαρμῶν προηγουμένων, τῆς δὲ λύσεως ἐπακολουθούσης. Καθαρμοὶ δὲ λογικῆς ψυχῆς εἰσιν αἱ μαθηματικαὶ ἐπιστῆμαι, καὶ ἀναγωγὸς λύσις ἡ διαλεκτικὴ τῶν ὄντων ἐποπτεία. Διὸ καὶ ἑνικῶς ἀπήγγελται, «ἔν τε λύσει ψυχῆς», ὅτι εἰς μίαν ἐπιστήμην αὕτη τελεῖ, τῆς μαθηματικῆς πλῆθος ἐπιστημῶν περιεχούσης.", "st": "26.9"}, {"sp": "N", "t": "Τοῖς οὖν ἐπὶ ψυχῆς εἰς κάθαρσιν καὶ ἀπόλυσιν οἰκείως παρειλημμένοις δεῖ τὰ ἀναλογοῦντα καὶ ἐπὶ τοῦ αὐγοειδοῦς ἐπιτάξαι. Οὐκοῦν τοῖς τε μαθηματικοῖς καθαρμοῖς τοὺς τελεστικοὺς συνεισιέναι, καὶ τῇ διαλεκτικῇ λύσει τὴν ἱερατικὴν ἀναγωγὴν συνέπεσθαι ἀνάγκη. Ταῦτα γὰρ ἰδίως καθαίροντα καὶ τελειοῦντα τὸ πνευματικὸν ὄχημα τῆς λογικῆς ψυχῆς, τῆς μὲν ὑλικῆς ἀζωΐας αὐτὸ χωρίζει, πρὸς δὲ τὴν τῶν καθαρῶν πνευμάτων συνουσίαν ἐπιτηδείως ἔχειν παρασκευάζει. «Μὴ καθαρῷ γὰρ καθαροῦ ἐφάπτεσθαι οὐκ ἔστι θέμις.» Ὥσπερ οὖν τὴν ψυχὴν ἐπιστήμῃ καὶ ἀρετῇ προσήκει κοσμῆσαι, ὅπως ἂν τοῖς ἀεὶ τοιούτοις συνεῖναι δύνηται· οὕτω καὶ τὸ αὐγοειδὲς καθαρὸν καὶ ἄϋλον δεῖ παρασκευάσαι, ἵνα τὴν τῶν αἰθερίων σωμάτων ἀνάσχηται κοινωνίαν. Δι' ὁμοιότητος γὰρ πάντα φιλεῖ πρὸς ἄλληλα συνάπτεσθαι, τῇ δὲ ἀνομοιότητι καὶ τὰ ἐγγὺς ὄντα τοῖς τόποις χωρίζεται.", "st": "26.10"}, {"sp": "N", "t": "Τοῦτο τῆς τελειοτάτης φιλοσοφίας τὸ μέτρον οἱ Πυθαγόρειοι παρέδοσαν, πρὸς τὴν ὅλου τοῦ ἀνθρώπου τελειότητα οἰκεῖον καὶ σύμμετρον. Ὁ γὰρ ψυχῆς μόνης ἐπιμέλειαν ποιούμενος, τοῦ δὲ σώματος ἀμελῶν, οὐ τὸν ὅλον ἄνθρωπον καθαίρει. Πάλιν δ' αὖ ὁ τοῦ σώματος οἰόμενος δεῖν ἐπιμελεῖσθαι χωρὶς τῆς ψυχῆς, ἢ τὰς τοῦ σώματος θεραπείας συντελέσειν τι τῇ ψυχῇ μηδὲν δι' ἑαυτῆς καθαιρομένῃ, τὸ αὐτὸ διαμαρτάνει. Ὁ δὲ δι' ἀμφοτέρων οἰκείως προϊὼν ὅλος τελειοῦται, καὶ κατὰ τοῦτο συνάπτεται τῇ τῶν ἱερῶν τέχνῃ ἡ φιλοσοφία, ὡς περὶ τὴν τοῦ αὐγοειδοῦς κάθαρσιν πραγματευομένῃ· ἣν εἰ χωρίσειας τοῦ φιλοσόφου νοῦ, οὐκ ἔτι τὴν αὐτὴν δύναμιν ἔχουσαν εὑρήσεις. Καὶ γὰρ τῶν συμπληρούντων τὴν ἡμετέραν τελείωσιν τὰ μὲν ὁ φιλόσοφος νοῦς προεξεῦρε, τὰ δὲ ἡ τελεστικὴ ἐνέργεια συνεισήγαγε, τῷ φιλοσόφῳ νῷ ἑπομένη. Τελεστικὴν δὲ ἐνέργειαν λέγω τὴν τοῦ αὐγοειδοῦς καθαρτικὴν δύναμιν, ἵνα τῆς ὅλης φιλοσοφίας τὸ μὲν θεωρητικὸν προηγῆται, ὡς νοῦς, τὸ δὲ πρακτικόν, ὡς δύναμις, ἕπηται. Τοῦ δὲ πρακτικοῦ δύο θῶμεν εἴδη, πολιτικὸν καὶ τελεστικόν· τὸ μὲν διὰ τῶν ἀρετῶν τῆς ἀλογίας ἀποκαθαῖρον ἡμᾶς, τὸ δὲ διὰ τῶν ἱερῶν μεθόδων τὰς ὑλικὰς φαντασίας ἀποτέμνον. Δεῖγμα δὲ οὐ μικρὸν τῆς μὲν πολιτικῆς φιλοσοφίας οἱ ἐν κοινῷ κείμενοι νόμοι, τῆς δὲ τελεστικῆς τὰ τῶν πόλεων ἱερά.", "st": "26.11"}, {"sp": "N", "t": "Καὶ ἔστι τὸ μὲν ἀκρότατον τῆς ὅλης φιλοσοφίας ὁ θεωρητικὸς νοῦς· μέσον δέ, ὁ πολιτικός· καὶ τρίτον, ὁ τελεστικός· τοῦ μὲν πρώτου πρὸς τὰ δύο τὴν ὀφθαλμοῦ ἀναλογίαν ἀποσῴζοντος· τῶν δὲ μετ' αὐτὸ πρὸς ἐκεῖνο τὴν χειρὸς καὶ ποδὸς ἀξίαν ἐχόντων· πρὸς ἄλληλα δὲ πάντων συντεταγμένων, ὡς ἀτελὲς εἶναι ὁτιοῦν τούτων, καὶ ἐγγὺς μάταιον, μὴ τῆς τῶν λοιπῶν συνεργείας τυγχάνον. Διὸ εἰς μίαν ἕνωσιν συνελθεῖν δεῖ τὴν τῆς ἀληθείας εὑρετικὴν ἐπιστήμην, καὶ τὴν ἀρετῆς προβλητικὴν δύναμιν, καὶ τὴν καθαρότητος ἀπεργαστικήν, ἵνα σύμφωνον τῷ ἡγουμένῳ νῷ τὸ πολιτικὸν ἔργον ἀποτελῆται, καὶ τούτοις ἀμφοτέροις ὁμολογούμενον τὸ ἱερὸν ἔργον ἀποφαίνηται.", "st": "26.12"}, {"sp": "N", "t": "Τοῦτο τῆς Πυθαγορικῆς ἀγωγῆς τὸ πέρας, ὅλους δι' ὅλων ὑποπτέρους γενέσθαι πρὸς τὴν τῶν θείων ἀγαθῶν μετάληψιν, ἵν' ὅταν ὁ τοῦ θανάτου καιρὸς ἐνστῇ, καταλιπόντες ἐπὶ γῆς τὸ θνητὸν σῶμα, καὶ τὴν τούτου φύσιν ἀποδυσάμενοι, πρὸς τὴν οὐρανίαν πορείαν ὦσιν εὔζωνοι οἱ τῶν φιλοσοφίας ἀγώνων ἀθληταί· τότε γὰρ καὶ τὴν ἀρχαίαν αὐτοῖς ἀποδίδοσθαι στάσιν, καὶ θεοποιεῖσθαι, ὅσον οἷόν τε ἀνθρώποις θεοὺς γενέσθαι, μηνύει ὁ λόγος διὰ τῶν ἑξῆς.", "st": "26.13"}, {"sp": "SEC", "t": "XXVII · 70–71", "st": "27"}, {"sp": "N", "t": "<span class=\"lemma\">ἢν δ' ἀπολείψας σῶμα ἐς αἰθέρ' ἐλεύθερον ἔλθῃς,<br>ἔσσεαι ἀθάνατος θεός, ἄμβροτος, οὐκ ἔτι θνητός.<\/span>", "st": "27.0"}, {"sp": "N", "t": "Τοῦτο πέρας τῶν πόνων τὸ κάλλιστον. Τοῦτο, ὡς Πλάτων φησίν, ὁ μέγας ἀγὼν καὶ ἐλπὶς ἡ μεγάλη. Τοῦτο φιλοσοφίας ὁ τελειότατος καρπός, τοῦτο τῆς ἱερατικῆς καὶ τελεστικῆς τέχνης τὸ μέγιστον ἔργον, οἰκειῶσαι μὲν καὶ ἀναγαγεῖν πρὸς τὰ ὄντως καλά, ἀπολῦσαι δὲ τῶν τῇδε πόνων, ὡς ἔκ τινος καταγείου σπηλαίου τῆς ἐνύλου ζωῆς, καὶ ἀναγαγεῖν πρὸς τὰς αἰθερίους αὐγάς, καὶ ταῖς μακάρων ἐνιδρῦσαι νήσοις τοὺς διὰ τῶν προειρημένων ὁδεύσαντας. Τούτοις γὰρ καὶ τὸ τῆς ἀποθεώσεως ἀπόκειται γέρας· ἐπειδὴ εἰς θεῶν γένος οὐ θέμις ἀφικνεῖσθαι ἄλλῳ ἢ τῷ κτησαμένῳ ἀλήθειαν μὲν καὶ ἀρετὴν ἐν ψυχῇ, καθαρότητα δὲ ἐν τῷ πνευματικῷ αὐτῆς ὀχήματι. Οὕτω γὰρ ὑγιής τε καὶ ὁλόκληρος γενόμενος εἰς τὸ τῆς ἀρχαίας ἕξεως εἶδος ἀποκαθίσταται, διὰ τῆς πρὸς τὸν ὀρθὸν λόγον ἑνώσεως ἀπολαβὼν ἑαυτόν, καὶ πάντα τὸν θεῖον κόσμον ἀναγνωρίσας, καὶ τὸν δημιουργὸν τουδὶ τοῦ παντός, κατὰ τὸ δυνατὸν ἀνθρώπῳ, ἐξευρών. Τοῦτο δὲ γενόμενος ὡς οἷόν τε μετὰ τὴν κάθαρσιν, ὃ ἀεί εἰσιν οἱ μὴ εἰς γένεσιν πίπτειν πεφυκότες, ταῖς μὲν γνώσεσιν ἑνοῦται τῷ παντί, καὶ πρὸς αὐτὸν ἀνάγεται τὸν θεόν· σῶμα δὲ συμφυὲς ἔχων, τόπου δεῖται εἰς κατάταξιν ἀστροειδῆ, οἷον θέσιν ζητῶν. Πρέποι δ' ἂν τῷ τοιούτῳ σώματι τόπος ὁ ὑπὸ σελήνην προσεχῶς, ὡς ὑπερέχων μὲν τῶν φθαρτῶν σωμάτων, ὑποβεβηκὼς δὲ τῶν οὐρανίων, ὃν αἰθέρα ἐλεύθερον οἱ Πυθαγόρειοι καλοῦσιν· αἰθέρα μέν, ὡς ἄϋλον καὶ ἀΐδιον σῶμα· ἐλεύθερον δέ, ὡς ὑλικῶν παθημάτων καθαρόν.", "st": "27.1"}, {"sp": "N", "t": "Τί οὖν ὁ ἐκεῖσε ἐλθὼν ἔσται, ἢ τοῦτο, ὅ φησιν, «ἔσσεαι ἀθάνατος θεός», ὡμοιωμένος τοῖς ἐν ἀρχῇ τῶν ἐπῶν λεχθεῖσιν ἀθανάτοις θεοῖς, οὐ φύσει ἀθάνατος θεός. Πῶς γὰρ τὸ ἀπὸ χρόνου τινὸς προκόψαν καὶ ἐπιδεδωκὸς εἰς ἀρετὴν καὶ ἀποθέωσιν τοῖς ἐξ ἀϊδίου τοιούτοις εἰς ταὐτὸν ἄν ποτε κατασταίη; Δηλοῖ δὲ τοῦτο ἡ προσθήκη· τῷ γὰρ «ἔσσεαι ἀθάνατος θεὸς» ἐπήγαγεν, «ἄμβροτος, οὐκ ἔτι θνητός»· ἵνα κατὰ ἀφαίρεσιν τοῦ βροτοῦ καὶ τοῦ θνητοῦ ἡ θεοποιία ἡμῶν νοῆται, ἅτε μὴ φύσει μηδὲ κατ' οὐσίαν ἡμῖν ἐνυπάρχουσα, ἀλλ' ἐκ προκοπῆς καὶ κατ' ἐπίδοσιν ἐπιγενομένη. Ὡς ἄλλο γένος εἶναι τοῦτο θεῶν, ἀθανάτων μὲν τῇ ἀνόδῳ, θνητῶν δὲ τῇ καθόδῳ γιγνομένων, οἳ καὶ τῶν ἀγαθῶν ἡρώων ἐξ ἀνάγκης ὑποβεβήκασιν, εἴπερ ἐκεῖνοι μὲν ἀεὶ νοοῦσι τὸν θεόν, οὗτοι δὲ καὶ εἰς ἄγνοιαν αὐτοῦ ποτὲ πίπτουσιν. Οὐ γὰρ δὴ τὸ τρίτον γένος τελειωθὲν ἢ τοῦ μέσου γένοιτο ἂν κρεῖττον ἢ τῷ πρώτῳ ἴσον, ἀλλὰ μένον τρίτον ὁμοιοῦται τῷ πρώτῳ γένει, ὑποτεταγμένον τῷ μέσῳ. Ἡ γὰρ κατὰ σχέσιν ἐν ἀνθρώποις δρωμένη πρὸς τοὺς οὐρανίους ὁμοιότης ἤδη προϋπάρχει τελειότερον καὶ προσφυέστερον τοῖς ἡρωϊκοῖς καὶ μέσοις γένεσι. Καὶ οὕτω κοινὴ καὶ μία πάντων τῶν λογικῶν γενῶν τελειότης θεωρεῖται ἡ πρὸς τὸν δημιουργὸν θεὸν ὁμοιότης. Αὕτη δὲ ἀεὶ μὲν καὶ ὡσαύτως ὑπάρχει τοῖς οὐρανίοις· ἀεὶ δὲ μόνον, οὐχ ὡσαύτως δέ, τοῖς μονίμοις αἰθερίοις· οὔτε δὲ ἀεὶ οὔτε ὡσαύτως τοῖς μεταπίπτουσιν αἰθερίοις καὶ ἐπὶ γῆς πολιτεύεσθαι πεφυκόσι. Τὴν δὲ πρώτην καὶ ἀρίστην ὁμοίωσιν πρὸς θεὸν εἴ τις τῆς δευτέρας καὶ τρίτης ἀπεικασίας παράδειγμα ποιοῖτο, ἢ τὴν δευτέραν τῆς τρίτης, λέγοι ἂν ὀρθῶς. Οὐ γὰρ μόνον σκοπὸς ὁμοιωθῆναι τῷ δημιουργῷ θεῷ, ἀλλὰ καὶ ὡς πρὸς κανόνα, τὴν ἀρίστην ἢ τὴν μέσην ὁμοίωσιν. Εἰ δὲ ἀπολειπόμενοι τούτων τυγχάνομεν οἵας δυνάμεθα τυχεῖν, αὐτὸ τοῦτο τὸ κατὰ φύσιν ἔχομεν, καὶ τὸ τέλειον τῆς ἀρετῆς ἐν τούτῳ καρπούμεθα, ἐν τῷ τὸ μέτρον τῆς οὐσίας ἡμῶν μήτε ἀγνοεῖν μήτε δυσχεραίνειν. Ἀκροτάτη δὲ ἀρετὴ τοῖς τε τῆς δημιουργίας ὅροις ἐμμένειν, οἷς πάντα κατ' εἶδος διακέκριται, καὶ τοῖς τῆς προνοίας ἕπεσθαι νόμοις, δι' οὓς τὰ πάντα, κατὰ τὴν οἰκείαν δύναμιν, πρὸς τὸ σύμμετρον ἀγαθὸν οἰκειοῦται.", "st": "27.2"}, {"sp": "SEC", "t": "Ἐπίλογος", "st": "28"}, {"sp": "N", "t": "Τοιαύτη τῶν Χρυσῶν Ἐπῶν ἡ ἐξήγησις ἡμῖν γέγονε, περιέχουσα ἐν αὐτῇ Πυθαγορείων δογμάτων μετρίαν σύνοψιν. Ἔδει γὰρ μήτε ἐν τῇ τῶν ἐπῶν βραχύτητι στῆσαι τὸν λόγον (οὕτω γὰρ ἂν πολλὰ διέλαθεν ὅτι καλῶς νενομοθέτηται), μήτε εἰς μῆκος ἀποτεῖναι τῆς ὅλης φιλοσοφίας αὐτόν (μεῖζον γὰρ τοῦτο ἢ κατὰ τὸν παρόντα λόγον), ἀλλὰ τὸ μέτρον τῶν λόγων, ὅσον οἷόν τε, πρὸς τὸν τούτων ποιήσασθαι νοῦν, τοσοῦτον μόνον ἐν αὐτοῖς ἐξαπλώσαντας, ὅσον ἐκ τῶν καθόλου δογμάτων τῇ τῶν ἐπῶν ἐξηγήσει προσήρμοττεν. Ἔστι γὰρ οὐδὲν ἄλλο τὰ ἔπη ταῦτα ἢ τελειότατος χαρακτὴρ φιλοσοφίας, καὶ τῶν κεφαλαιωδεστέρων αὐτῆς δογμάτων ἐπιτομή, καὶ ὑπὸ τῶν ἤδη τὴν θείαν οἶμον ἀναβεβηκότων ὑπογραφεῖσα τοῖς μετ' αὐτοὺς παιδευτικὴ στοιχείωσις· ἃ δὴ καὶ τῷ ὄντι εἴποι τις ἂν τῆς ἀνθρωπίνης εὐγενείας εἶναι γνώρισμα κάλλιστον, καὶ οὐχ ἑνός τινος τῶν Πυθαγορείων ἀπομνημόνευμα, ὅλου δὲ τοῦ ἱεροῦ συλλόγου, καὶ ὡς ἂν αὐτοὶ εἴποιεν, τοῦ ὁμαΐου παντὸς ἀπόφθεγμα κοινόν.", "st": "28.0"}, {"sp": "N", "t": "Διὸ καὶ νόμος ἦν ἕωθέν τε ἀνισταμένους αὐτοὺς ἀκροᾶσθαι τούτων τῶν ἐπῶν, ὥσπερ τινῶν Πυθαγορικῶν θεσμῶν, ἑνός τινος ὑπαναγινώσκοντος, καὶ πρὸς ἑσπέραν εἰς ὕπνον μέλλοντας τρέπεσθαι· ὅπως ἂν τῇ συνεχείᾳ τῆς μελέτης τῶν τοιούτων λόγων ζῶντα ἐν αὐτοῖς ἀποφήνωσι τὰ δόγματα. Ὃ δὴ καὶ ἡμᾶς ποιεῖν δίκαιον, πρὸς τὸ συναίσθησιν τῆς ἀπ' αὐτῶν ὠφελείας ὀψὲ γοῦν ποτε κτήσασθαι.", "st": "28.1"}], []);})();
